INSERT INTO social_questions (id, subject, chapter, section, number, stage, is_difficult, question, supplement, answer, answer_kana) VALUES
  (1, '地理', '第1章 世界と日本のすがた', '1. 地球のすがた', 1, 1, FALSE, '( ) は太陽系の第3惑星で、表面積が約5.1億km², 半径が約6400km, 周囲が約4万kmのほぼ球体に近い形をしている。', '', '地球', ''),
  (2, '地理', '第1章 世界と日本のすがた', '1. 地球のすがた', 2, 1, FALSE, '六大陸の中で最も面積が大きい大陸を何というか。', '陸地の全面積の37%を占める', 'ユーラシア大陸', ''),
  (3, '地理', '第1章 世界と日本のすがた', '1. 地球のすがた', 3, 1, FALSE, '六大陸の一つで、2と陸続きの大陸を何というか。', '2つの大陸の境にはスエズ運河がつくられている', 'アフリカ大陸', ''),
  (4, '地理', '第1章 世界と日本のすがた', '1. 地球のすがた', 4, 1, FALSE, '六大陸の一つで、南アメリカ大陸と陸続きの大陸を何というか。', '2つの大陸の境にはパナマ運河がつくられている', '北アメリカ大陸', ''),
  (5, '地理', '第1章 世界と日本のすがた', '1. 地球のすがた', 6, 1, FALSE, '六大陸の中で最も面積が小さい大陸を何というか。', '全土が大陸名と同じ国の領土である', 'オーストラリア大陸', ''),
  (6, '地理', '第1章 世界と日本のすがた', '1. 地球のすがた', 7, 1, FALSE, '三大洋の中で最も面積が大きい海洋を何というか。', '全海洋面積の約46%を占め、六大陸すべてを合わせた面積よりも大きい', '太平洋', ''),
  (7, '地理', '第1章 世界と日本のすがた', '1. 地球のすがた', 8, 1, FALSE, '三大洋の一つで、2・3と4・5の間に広がる海洋を何というか。', '大陸移動によってつくられた三大洋の中では新しい海洋である', '大西洋', ''),
  (8, '地理', '第1章 世界と日本のすがた', '1. 地球のすがた', 9, 1, FALSE, '三大洋の中で最も面積が小さい海洋を何というか。', '全海洋面積の約20%を占める', 'インド洋', ''),
  (9, '地理', '第1章 世界と日本のすがた', '1. 地球のすがた', 10, 2, FALSE, '六大陸の一つで、どの国の領土にも属していない極地を含む大陸を何というか。', '', '南極大陸', ''),
  (10, '地理', '第1章 世界と日本のすがた', '1. 地球のすがた', 11, 2, FALSE, '地球の表面積を大陸と海洋で比較すると、約7割を ( ) が占めている。', '陸地の多くは北半球に分布している', '海洋', ''),
  (11, '地理', '第1章 世界と日本のすがた', '1. 地球のすがた', 12, 2, TRUE, '地球上の陸地の面積が最大となるように見える半球を ( ) とよぶ。', '陸地全体の約84%が含まれている', '陸半球', ''),
  (12, '地理', '第1章 世界と日本のすがた', '1. 地球のすがた', 13, 2, TRUE, '地球上の海洋の面積が最大となるように見える半球を ( ) とよぶ。', '海洋全体の約64%が含まれている', '水半球', ''),
  (13, '地理', '第1章 世界と日本のすがた', '2. 世界の地域区分', 15, 1, FALSE, '世界を6つの州に分けたとき、ユーラシア大陸のウラル山脈から東の地域を何というか。', '世界の総人口の約60%の46.4億人(2020年)が住む', 'アジア州', ''),
  (14, '地理', '第1章 世界と日本のすがた', '2. 世界の地域区分', 16, 1, FALSE, '15はさらに、シベリアなど6つの地域に分けられるが、わたしたちが住む日本は ( ) に含まれる。', '中華人民共和国(中国)や大韓民国(韓国)などもこの地域に含まれる', '東アジア', ''),
  (15, '地理', '第1章 世界と日本のすがた', '2. 世界の地域区分', 17, 1, FALSE, '世界を6つの州に分けたとき、ユーラシア大陸のウラル山脈から西の地域を何というか。', '人口は約7.5億人(2020年)と州別では3位', 'ヨーロッパ州', ''),
  (16, '地理', '第1章 世界と日本のすがた', '2. 世界の地域区分', 18, 1, FALSE, '世界を6つの州に分けたとき、サハラ砂漠があり、マダガスカル島などがある地域を何というか。', '', 'アフリカ州', ''),
  (17, '地理', '第1章 世界と日本のすがた', '2. 世界の地域区分', 19, 1, FALSE, '世界を6つの州に分けたとき、オーストラリア大陸と太平洋上の多くの島々からなる地域を何というか。', '6つの州の中で面積が最小', 'オセアニア州', ''),
  (18, '地理', '第1章 世界と日本のすがた', '2. 世界の地域区分', 20, 2, FALSE, 'アメリカ合衆国とカナダは、おもにアングロサクソン系のイギリス人によって開拓が進められたことから ( ) ともよばれる。', '', 'アングロアメリカ', ''),
  (19, '地理', '第1章 世界と日本のすがた', '2. 世界の地域区分', 21, 2, FALSE, '中央アメリカ・南アメリカは、スペイン語・ポルトガル語を話す民族によって開拓が進められたことから ( ) ともよばれる。', 'これに対して、イギリスとつながりの深いアメリカ合衆国とカナダは20とよばれる', 'ラテンアメリカ', ''),
  (20, '地理', '第1章 世界と日本のすがた', '2. 世界の地域区分', 22, 2, TRUE, '山脈・河川・湖沼・海洋などの自然の地形を利用した国境を何というか。', '例:フランスとスペインはピレネー山脈を国境としている', '自然的国境', ''),
  (21, '地理', '第1章 世界と日本のすがた', '2. 世界の地域区分', 23, 2, TRUE, '経線や緯線など、人間がつくり出したものをもとにして定めた国境を何というか。', '例:カナダとアメリカ合衆国は北緯49度を国境としている', '人為的国境', 'じんいてき'),
  (22, '地理', '第1章 世界と日本のすがた', '2. 世界の地域区分', 24, 2, FALSE, 'ニュージーランドやフィリピンなどのように、国土の周りが海に囲まれている国を何というか。', '他に、キューバやアイスランド、マダガスカルなどがある。海洋国ともいう', '島国', ''),
  (23, '地理', '第1章 世界と日本のすがた', '2. 世界の地域区分', 25, 2, FALSE, 'スイスやモンゴルなどのように、国土がまったく海に面していない国を何というか。', '19と北アメリカ州には存在しない', '内陸国', ''),
  (24, '地理', '第1章 世界と日本のすがた', '3. 地球儀と世界地図', 27, 1, FALSE, '地球の表面上で、北極点と南極点の中間に位置する、緯度0度の線を何というか。', '全周は約4万km', '赤道', 'せきどう'),
  (25, '地理', '第1章 世界と日本のすがた', '3. 地球儀と世界地図', 28, 1, FALSE, '同じ緯度を結んだ、27と平行に引かれた南北の位置を表す線を何というか。', '27を0度とし、南北をそれぞれ90度に分け、北を北緯、南を南緯と表す', '緯線', 'いせん'),
  (26, '地理', '第1章 世界と日本のすがた', '3. 地球儀と世界地図', 29, 1, FALSE, '地球の表面上で、北極点と南極点を結んだ東西の位置を表す線を何というか。', '', '経線', 'けいせん'),
  (27, '地理', '第1章 世界と日本のすがた', '3. 地球儀と世界地図', 30, 1, FALSE, 'イギリスのロンドン郊外にある旧グリニッジ天文台を通る29(経度0度)を基準に東西を180度ずつに分け、東回りに180度までを ( ) という。', '西回りに180度までを西経という', '東経', 'とうけい'),
  (28, '地理', '第1章 世界と日本のすがた', '3. 地球儀と世界地図', 31, 1, FALSE, '29の基準となるイギリスの旧グリニッジ天文台を通る経度0度の線を何というか。', '世界の時刻の基準となる線', '本初子午線', 'ほんしょしごせん'),
  (29, '地理', '第1章 世界と日本のすがた', '3. 地球儀と世界地図', 34, 2, FALSE, '北緯66度34分以北の地域を ( ) とよび、夏至には太陽が沈まず、冬至には太陽が昇らない。', '', '北極圏', 'けん'),
  (30, '地理', '第1章 世界と日本のすがた', '3. 地球儀と世界地図', 35, 2, FALSE, '地球の地軸が公転面に対する垂直方向から23度26分(約23.4度)傾いているため、夏至の日の正午に北緯23度26分の真上に、冬至の日の正午に南緯23度26分の真上に太陽がくる緯線を何というか。', '', '回帰線', ''),
  (31, '地理', '第1章 世界と日本のすがた', '3. 地球儀と世界地図', 36, 2, FALSE, '夏至のころに34で見られる、夜になっても太陽が沈まない現象を何というか。', '反対に、一日中太陽が昇らない現象を極夜という', '白夜', 'びゃくや'),
  (32, '地理', '第1章 世界と日本のすがた', '3. 地球儀と世界地図', 37, 2, FALSE, '27を基準に地球を南北に二分したとき、北に位置する範囲を何というか。', '大陸の多くが分布している', '北半球', ''),
  (33, '地理', '第1章 世界と日本のすがた', '3. 地球儀と世界地図', 38, 2, FALSE, '27を基準に地球を南北に二分したとき、南に位置する範囲を何というか。', '37と38では季節が逆になる', '南半球', ''),
  (34, '地理', '第1章 世界と日本のすがた', '4. 日本のすがた', 39, 1, FALSE, '現在はロシア連邦が不法占拠している、日本の最北端の島を何というか。', '千島列島で最大の面積', '択捉島', 'えとろふとう'),
  (35, '地理', '第1章 世界と日本のすがた', '4. 日本のすがた', 40, 1, FALSE, '東京都に属する、日本の最南端の島を何というか。', '水没しないよう護岸工事が行われた', '沖ノ鳥島', 'おきのとりしま'),
  (36, '地理', '第1章 世界と日本のすがた', '4. 日本のすがた', 41, 1, FALSE, '東京都の小笠原諸島に属する、日本の最東端の島を何というか。', '近海の海底で大量のレアメタルが発見された', '南鳥島', 'みなみとりしま'),
  (37, '地理', '第1章 世界と日本のすがた', '4. 日本のすがた', 42, 1, FALSE, '沖縄県に属する、日本の最西端の島を何というか。', '亜熱帯の気候に属し、年平均気温も24.0度と高い', '与那国島', 'よなぐにじま'),
  (38, '地理', '第1章 世界と日本のすがた', '4. 日本のすがた', 44, 1, FALSE, '現在、ロシア連邦が不法占拠している、39の島など4島からなる島々をまとめて何というか。', '第二次世界大戦後にソ連が占拠して以来、現在に至る', '北方領土', ''),
  (39, '地理', '第1章 世界と日本のすがた', '4. 日本のすがた', 45, 1, FALSE, '44とは、北海道の北東に連なる39・ ( ) ・歯舞群島・色丹島の4島をまとめたよび名である。', '', '国後島', ''),
  (40, '地理', '第1章 世界と日本のすがた', '4. 日本のすがた', 46, 1, FALSE, '1905年に日本の領土として島根県に編入されたが、現在は韓国が不法占拠している島を何というか。', '', '竹島', ''),
  (41, '地理', '第1章 世界と日本のすがた', '4. 日本のすがた', 47, 1, FALSE, '東シナ海上に位置し、近年、中国や台湾が領有権を主張している沖縄県に属する島々を何というか。', '周辺海域に天然ガスなどの地下資源の埋蔵が確認されている。日本が実効支配しており、領土問題は存在しない', '尖閣諸島', 'せんかく'),
  (42, '地理', '第1章 世界と日本のすがた', '4. 日本のすがた', 48, 1, FALSE, '標準時の基準となる、日本では兵庫県明石市を通る東経135度の経線を何というか。', '', '標準時子午線', ''),
  (43, '地理', '第1章 世界と日本のすがた', '4. 日本のすがた', 49, 1, FALSE, '2つの地域の標準時の差を ( ) という。', '地球は24時間かけて1回転しているので、経度15度につき1時間の差が生じる', '時差', ''),
  (44, '地理', '第1章 世界と日本のすがた', '4. 日本のすがた', 50, 2, FALSE, '日本の領土を形成する、39から42までの約3000kmにわたる範囲にある島々をまとめて何というか。', '国土面積は約38万km²', '日本列島', ''),
  (45, '地理', '第1章 世界と日本のすがた', '2. 世界の地域区分', 51, 2, FALSE, 'その国の主権がおよぶ領域のうち，干潮時の海岸線から12海里までの海洋の部分を( )という。', '日本の場合は12海里(約22.2km)。国によって水域の幅が異なる', '領海', 'りょうかい'),
  (46, '地理', '第1章 世界と日本のすがた', '2. 世界の地域区分', 52, 2, FALSE, 'その国の主権がおよぶ領域のうち，陸地の部分を( )という。', '日本の52は本州・北海道・九州・四国とその周りにある約1万4000の小さな島々', '領土', 'りょうど'),
  (47, '地理', '第1章 世界と日本のすがた', '2. 世界の地域区分', 53, 2, FALSE, 'その国の主権がおよぶ領域のうち，51と52の上空を( )という。', '宇宙空間は含まれない', '領空', 'りょうくう'),
  (48, '地理', '第1章 世界と日本のすがた', '2. 世界の地域区分', 54, 2, FALSE, 'どの国の43や51にも含まれない水域を( )という。', '漁業などの経済活動も自由に行うことができる', '公海', 'こうかい'),
  (49, '地理', '第1章 世界と日本のすがた', '2. 世界の地域区分', 55, 2, FALSE, '国や地域で共通して使用する時間で，通常，定めた経線の真上に太陽が来たときを正午とする時刻を何というか。', '国土面積が広いため複数の55を使用している国もある', '標準時', 'ひょうじゅんじ'),
  (50, '地理', '第1章 世界と日本のすがた', '2. 世界の地域区分', 56, 2, FALSE, '日付の更新の矛盾を防ぐため，太平洋上の180度の経線にほぼ沿って南北に定められた線を何というか。', 'この線を西から東に越えるときは日付を1日戻し，東から西に越えるときは日付を1日進める', '日付変更線', 'ひづけへんこうせん'),
  (51, '地理', '第1章 世界と日本のすがた', '2. 世界の地域区分', 57, 2, TRUE, '夏に限って55より時刻を1時間進める制度を何というか。', '現在，日本では導入されていない', 'サマータイム', ''),
  (52, '地理', '第2章 世界のさまざまな地域', '1. 世界の気候', 59, 1, FALSE, '熱帯に属し，一年を通して高温多雨の気候区を何というか。', 'アマゾンのセルバや東南アジアのジャングルなどに分布する', '熱帯雨林気候', 'ねったいうりんきこう'),
  (53, '地理', '第2章 世界のさまざまな地域', '1. 世界の気候', 60, 1, FALSE, '熱帯に属し，年中高温で雨季と乾季のある気候区を何というか。', '背の高い草，まばらに木が生える熱帯草原が広がる', 'サバナ気候', ''),
  (54, '地理', '第2章 世界のさまざまな地域', '1. 世界の気候', 61, 1, FALSE, '中緯度の大陸や内陸部に広がる，年間の降水量が少ない気候帯を( )という。', '', '乾燥帯', 'かんそうたい'),
  (55, '地理', '第2章 世界のさまざまな地域', '1. 世界の気候', 62, 1, FALSE, '61に属し，降水量がほとんどなく，一日の温度差が非常に大きい気候区を何というか。', '', '砂漠気候', 'さばくきこう'),
  (56, '地理', '第2章 世界のさまざまな地域', '1. 世界の気候', 63, 1, FALSE, '中緯度地域の大陸の東岸や西岸，内陸部に分布する温暖な気候帯を何というか。', '日本の大部分がこの気候帯に含まれる', '温帯', 'おんたい'),
  (57, '地理', '第2章 世界のさまざまな地域', '1. 世界の気候', 64, 1, FALSE, '63に属し，地中海の沿岸や中緯度の大陸西岸に分布する，夏に乾燥し，冬に比較的降水量が多い気候区を何というか。', '', '地中海性気候', 'ちちゅうかいせいきこう'),
  (58, '地理', '第2章 世界のさまざまな地域', '1. 世界の気候', 65, 1, FALSE, '63に属し，大陸の西岸に見られ，冬も暖流と偏西風の影響で高緯度のわりに温暖な気候区を何というか。', '', '西岸海洋性気候', 'せいがんかいようせいきこう'),
  (59, '地理', '第2章 世界のさまざまな地域', '1. 世界の気候', 66, 1, FALSE, '夏と冬で吹く方向の異なる風を何というか。', '夏は海洋から大陸へ，冬は大陸から海洋へ吹く', '季節風(モンスーン)', 'きせつふう'),
  (60, '地理', '第2章 世界のさまざまな地域', '1. 世界の気候', 67, 1, FALSE, '一年を通じて西から吹く風を何というか。', '中緯度の大陸西岸の気候に影響を与える', '偏西風', 'へんせいふう'),
  (61, '地理', '第2章 世界のさまざまな地域', '1. 世界の気候', 68, 1, FALSE, '北半球の高緯度地域に分布する，夏と冬の気温差が大きく，冬の寒さが厳しい気候帯を何というか。', '北半球のみに分布し，南半球には分布しない', '冷帯(亜寒帯)', 'れいたい/あかんたい'),
  (62, '地理', '第2章 世界のさまざまな地域', '1. 世界の気候', 69, 1, FALSE, '南極と北極の周辺に分布する，一年中気温が低く，降水量が少ない気候帯を( )という。', '', '寒帯', 'かんたい'),
  (63, '地理', '第2章 世界のさまざまな地域', '1. 世界の気候', 70, 1, FALSE, '69に属し，夏は氷がとけ，こけ類が生える，シベリア北部やグリーンランド南部沿岸などに分布する気候区を何というか。', '', 'ツンドラ気候', ''),
  (64, '地理', '第2章 世界のさまざまな地域', '1. 世界の気候', 71, 2, FALSE, '一年のうちで雨の多い季節を( )といい，60に属する地域では，夏に雨が多くなる。', '一年のうちで雨の少ない季節を乾季といい，60に属する地域では，冬は雨の少ない乾季となる', '雨季', 'うき'),
  (65, '地理', '第2章 世界のさまざまな地域', '1. 世界の気候', 73, 2, FALSE, '68から69の気候帯にかけて見られる，年中凍結している岩や土を何というか。', '地球温暖化の影響で融解が進んでいるところもある', '永久凍土', 'えいきゅうとうど'),
  (66, '地理', '第2章 世界のさまざまな地域', '1. 世界の気候', 74, 2, TRUE, '69に属し，降水量が少なく，一年中，氷や雪におおわれている気候区を何というか。', '', '氷雪気候', 'ひょうせつきこう'),
