  (191, '地理', '第3章 地域調査と日本の地域的特色', '2. 世界の地形', 207, 1, FALSE, 'スカンディナビア半島の北西岸などで見られる、氷河に侵食されてできたU字谷に海水が入り込んでできた入り江を( )という。', 'グリーンランドやチリ南部の海岸などでも、この地形が見られる', 'フィヨルド', ''),
  (192, '地理', '第3章 地域調査と日本の地域的特色', '2. 世界の地形', 208, 1, FALSE, '阿蘇山などに見られる、火山の噴火により山頂付近が落ち込んだり、吹き飛んだりしてできた窪地を( )という。', '', 'カルデラ', ''),
  (193, '地理', '第3章 地域調査と日本の地域的特色', '2. 世界の地形', 209, 2, FALSE, '地球の表面をおおっている厚さ100kmほどの硬い岩盤を何というか。', 'マントルの対流によって水平に移動する', 'プレート', ''),
  (194, '地理', '第3章 地域調査と日本の地域的特色', '2. 世界の地形', 210, 2, FALSE, '海の209が沈み込んでいる、深さ6000m以上の溝状の海底地形を何というか。', '', '海溝', 'かいこう'),
  (195, '地理', '第3章 地域調査と日本の地域的特色', '2. 世界の地形', 211, 2, TRUE, '209の衝突部分に形成される、水深が6000mより浅い海底の溝を何というか。', '日本の近海には南海211などがある', 'トラフ', ''),
  (196, '地理', '第3章 地域調査と日本の地域的特色', '3. 日本の地形', 213, 1, FALSE, '日本の屋根ともよばれる、飛騨山脈・木曽山脈・赤石山脈を総称して何というか。', '3000m級の山々が連なる', '日本アルプス', ''),
  (197, '地理', '第3章 地域調査と日本の地域的特色', '3. 日本の地形', 214, 1, FALSE, '川が山地から平地に出るところに土砂が積もってできた、扇の形をした地形を( )という。', '果樹園などに利用されることが多い', '扇状地', 'せんじょうち'),
  (198, '地理', '第3章 地域調査と日本の地域的特色', '3. 日本の地形', 215, 1, FALSE, '川が海や湖に出るところに土砂が積もってできた、低平な地形を( )という。', '水田などに利用される', '三角州(デルタ)', 'さんかくす'),
  (199, '地理', '第3章 地域調査と日本の地域的特色', '3. 日本の地形', 216, 1, FALSE, '山地が沈んだり、海面が上昇したりしてできた、出入りの多い海岸を( )という。', '三陸海岸の南部や若狭湾岸、志摩半島などでこの地形が見られる', 'リアス海岸', ''),
  (200, '地理', '第3章 地域調査と日本の地域的特色', '3. 日本の地形', 217, 1, FALSE, '北海道の北東に広がる、千島列島によって太平洋と隔てられている海洋を何というか。', '冬には流氷が流れてきて北海道の沿岸に着岸する', 'オホーツク海', ''),
  (201, '地理', '第3章 地域調査と日本の地域的特色', '3. 日本の地形', 218, 1, FALSE, 'ユーラシア大陸の東に位置し、日本、ロシア連邦、朝鮮半島に囲まれた海洋を何というか。', '', '日本海', ''),
  (202, '地理', '第3章 地域調査と日本の地域的特色', '3. 日本の地形', 219, 1, FALSE, '中国の東に位置し、朝鮮半島、九州、南西諸島に囲まれた海洋を何というか。', '海底に天然ガスの埋蔵が確認されたが、その開発をめぐって中国との間で問題になっている', '東シナ海', ''),
  (203, '地理', '第3章 地域調査と日本の地域的特色', '3. 日本の地形', 220, 1, FALSE, '大陸の周辺に広がる、水深が200mくらいまでの浅い海底を何というか。', 'プランクトンが育ちやすく、良い漁場でもある', '大陸棚', 'たいりくだな'),
  (204, '地理', '第3章 地域調査と日本の地域的特色', '3. 日本の地形', 221, 1, FALSE, '日本の太平洋側の近海を南下する千島海流ともよばれている寒流を何というか。', 'プランクトンが多く、水産資源が豊富なためこうよばれる', '親潮', 'おやしお'),
  (205, '地理', '第3章 地域調査と日本の地域的特色', '3. 日本の地形', 222, 1, FALSE, '日本の太平洋側の近海を北上する日本海流ともよばれている暖流を何というか。', '濃い藍色をしているためこうよばれる', '黒潮', 'くろしお'),
  (206, '地理', '第3章 地域調査と日本の地域的特色', '3. 日本の地形', 223, 1, FALSE, '潮境ともいわれる、暖流と寒流がぶつかる海域を何というか。', '東北地方の三陸沖などがその代表', '潮目', 'しおめ'),
  (207, '地理', '第3章 地域調査と日本の地域的特色', '3. 日本の地形', 224, 2, FALSE, 'ある河川に流れ込む水が集まってくる範囲の面積を( )という。', '日本最大は利根川、世界最大はアマゾン川', '流域面積', 'りゅういきめんせき'),
  (208, '地理', '第3章 地域調査と日本の地域的特色', '3. 日本の地形', 225, 2, FALSE, '強い風によって運ばれてきた砂が積もってできた、丘状の地形を( )という。', '', '砂丘', 'さきゅう'),
  (209, '地理', '第3章 地域調査と日本の地域的特色', '3. 日本の地形', 226, 2, FALSE, '川や海に土砂を運び入れて陸地にすることを( )といい、住宅地や工場用地などに利用される。', '', '埋め立て', ''),
  (210, '地理', '第3章 地域調査と日本の地域的特色', '3. 日本の地形', 227, 2, FALSE, '海洋を一定方向に流れる海水の流れを( )という。', '低緯度から高緯度への流れを暖流、高緯度から低緯度への流れを寒流という', '海流', 'かいりゅう'),
  (211, '地理', '第3章 地域調査と日本の地域的特色', '3. 日本の地形', 228, 2, FALSE, '222から分かれて日本海側を本州に沿って北上する暖流を何というか。', '日本海沿岸地域の寒さを和らげているが、冬は降雪の原因となる', '対馬海流', 'つしまかいりゅう'),
  (212, '地理', '第3章 地域調査と日本の地域的特色', '4. 日本の気候と自然災害', 229, 1, FALSE, '日本の気候区分の一つで、冷帯(亜寒帯)に属し、夏が短く冬の寒さが厳しい気候を何というか。', '', '北海道の気候', ''),
  (213, '地理', '第3章 地域調査と日本の地域的特色', '4. 日本の気候と自然災害', 230, 1, FALSE, '日本の気候区分の一つで、夏は南東の季節風の影響で雨が多く、冬は乾燥した北西の季節風の影響で晴れの日が多い気候を何というか。', '', '太平洋側の気候', ''),
  (214, '地理', '第3章 地域調査と日本の地域的特色', '4. 日本の気候と自然災害', 231, 1, FALSE, '日本の気候区分の一つで、冬に北西の季節風の影響で雪や雨が多い気候を何というか。', '', '日本海側の気候', ''),
  (215, '地理', '第3章 地域調査と日本の地域的特色', '4. 日本の気候と自然災害', 233, 1, FALSE, '日本の気候区分の一つで、夏の季節風は四国山地、冬の季節風は中国山地で遮られるため、一年を通して降水量が少なく、冬も比較的温暖な気候を何というか。', '', '瀬戸内の気候', 'せとうち'),
  (216, '地理', '第3章 地域調査と日本の地域的特色', '4. 日本の気候と自然災害', 234, 1, FALSE, '日本の気候区分の一つで、一年を通して降水量が多く、夏は高温となり冬でも温暖な亜熱帯の気候を何というか。', '年平均気温は20度を超える', '南西諸島の気候', ''),
  (217, '地理', '第3章 地域調査と日本の地域的特色', '4. 日本の気候と自然災害', 235, 1, FALSE, 'プレートや地盤のずれによっておこる、大地を振動させる自然災害を( )という。', 'マグニチュードはエネルギーの大きさ、震度は揺れの大きさを表す', '地震', 'じしん'),
  (218, '地理', '第3章 地域調査と日本の地域的特色', '4. 日本の気候と自然災害', 236, 1, FALSE, '235や海底火山の噴火などによって海底が動き、海水がもちあがることによって生じる非常に波長の長い波を( )という。', '', '津波', 'つなみ'),
  (219, '地理', '第3章 地域調査と日本の地域的特色', '4. 日本の気候と自然災害', 237, 1, FALSE, '日本列島で見られる、6月から7月にかけて続く長雨を何というか。', '北海道では237の影響を受けることが少ない', '梅雨', 'つゆ'),
  (220, '地理', '第3章 地域調査と日本の地域的特色', '4. 日本の気候と自然災害', 238, 1, FALSE, 'フィリピン諸島東方の洋上や南シナ海で発生し、発達しながら日本に上陸することもある熱帯低気圧を何というか。', '', '台風', 'たいふう'),
  (221, '地理', '第3章 地域調査と日本の地域的特色', '4. 日本の気候と自然災害', 239, 1, FALSE, '夏に気温が下がったり、日照時間が不足したりすることで作物の実りが悪くなる自然災害を何というか。', '', '冷害', 'れいがい'),
  (222, '地理', '第3章 地域調査と日本の地域的特色', '4. 日本の気候と自然災害', 240, 1, FALSE, '235や火山の噴火、洪水などによる被害状況を予測し、避難場所などを示した地図を何というか。', '', 'ハザードマップ(防災マップ)', ''),
  (223, '地理', '第3章 地域調査と日本の地域的特色', '4. 日本の気候と自然災害', 241, 2, FALSE, '地下にたまったマグマが、地表や水中に噴出することによって形成される山を何というか。', '桜島(御岳)や霧島山は現在も活発に活動している', '火山', 'かざん'),
  (224, '地理', '第3章 地域調査と日本の地域的特色', '4. 日本の気候と自然災害', 242, 2, FALSE, '237や238に伴う集中豪雨によって河川が増水し、水があふれ出る現象を何というか。', '', '洪水', 'こうずい'),
  (225, '地理', '第3章 地域調査と日本の地域的特色', '4. 日本の気候と自然災害', 243, 2, FALSE, '238や発達した低気圧によって、海水面が上昇する現象を( )という。', '238の通過時と満潮時とが一致すると被害が大きくなる', '高潮', 'たかしお'),
  (226, '地理', '第3章 地域調査と日本の地域的特色', '4. 日本の気候と自然災害', 244, 2, FALSE, '集中豪雨などによって、泥・砂・岩などが泥水状態となって一挙に斜面を流れ下る現象を何というか。', '', '土石流', 'どせきりゅう'),
  (227, '地理', '第3章 地域調査と日本の地域的特色', '4. 日本の気候と自然災害', 245, 2, FALSE, '降水量が少なく、日照りのために受ける自然災害を何というか。', '農作物の生育が遅れたり、枯れたりするなどの被害が出る', '干害', 'かんがい'),
  (228, '地理', '第3章 地域調査と日本の地域的特色', '4. 日本の気候と自然災害', 246, 2, FALSE, '1995年1月17日午前5時46分ごろに発生した、淡路島の北部を震源とする大きな235による災害を何というか。', '神戸市を中心に多くの被害や犠牲者が出た', '阪神・淡路大震災', 'はんしん あわじだいしんさい'),
  (229, '地理', '第3章 地域調査と日本の地域的特色', '4. 日本の気候と自然災害', 247, 2, FALSE, '2011年3月11日午後2時46分ごろに発生した、三陸沖を震源とする大きな235とそれに伴う大きな236などによる災害を何というか。', '戦後最悪の災害となった', '東日本大震災', 'ひがしにほんだいしんさい'),
  (230, '地理', '第3章 地域調査と日本の地域的特色', '4. 日本の気候と自然災害', 248, 2, FALSE, '電気・ガス・水道の供給施設、通信施設、鉄道・道路の交通施設、食料など、生活するうえで欠かせない「生命線」のことを何というか。', '', 'ライフライン', ''),
  (231, '地理', '第3章 地域調査と日本の地域的特色', '5. 日本の人口', 249, 1, FALSE, '一定の範囲にどれだけの人が住んでいるかを表した数値を( )という。', '通常1km2あたりの人数で表す', '人口密度', 'じんこうみつど'),
  (232, '地理', '第3章 地域調査と日本の地域的特色', '5. 日本の人口', 250, 1, FALSE, '出生率の低下により、総人口に占める子どもの割合が低下することを( )という。', '日本の合計特殊出生率は1.36(2019年)', '少子化', 'しょうしか'),
  (233, '地理', '第3章 地域調査と日本の地域的特色', '5. 日本の人口', 251, 1, FALSE, '総人口に占める65歳以上の人口の割合が高くなることを ( ) という。', '医療の発達で平均寿命がのび、高齢者の占める割合が増加した', '高齢化', 'こうれいか'),
  (234, '地理', '第3章 地域調査と日本の地域的特色', '5. 日本の人口', 252, 1, FALSE, '250と251が続く傾向にあることを何というか。', '労働力の不足と、現役世代の社会保障費の負担増などの問題を抱えている', '少子高齢化', 'しょうしこうれいか'),
  (235, '地理', '第3章 地域調査と日本の地域的特色', '5. 日本の人口', 254, 1, FALSE, '東京大都市圏、京阪神大都市圏(大阪大都市圏)、名古屋大都市圏をあわせて何というか。', 'それぞれ50km圏内の人口の合計は、日本の総人口の半数近くを占める', '三大都市圏', 'さんだいとしけん'),
  (236, '地理', '第3章 地域調査と日本の地域的特色', '5. 日本の人口', 255, 1, FALSE, '政令で指定された、人口が50万人以上の都市を何というか。', '都道府県の行政の一部を行うことができる。2021年現在、20都市が指定されている', '政令指定都市', 'せいれいしていとし'),
  (237, '地理', '第3章 地域調査と日本の地域的特色', '5. 日本の人口', 256, 1, FALSE, '都市に過度に人口が集中する現象を ( ) という。', '日本では太平洋ベルトの大都市に人口が集中している', '過密', 'かみつ'),
  (238, '地理', '第3章 地域調査と日本の地域的特色', '5. 日本の人口', 257, 1, FALSE, '都市部で工業活動や自動車などの排出熱が蓄積されて、郊外より気温が高くなる現象を何というか。', '都市はビルの増加やアスファルト舗装などにより熱がたまりやすくなっている', 'ヒートアイランド現象', ''),
  (239, '地理', '第3章 地域調査と日本の地域的特色', '5. 日本の人口', 258, 1, FALSE, '住宅不足を解消するため、大都市近郊に計画的に建設された大規模な住宅街を何というか。', '1970年代に東京では多摩、大阪では千里などに建設された', 'ニュータウン', ''),
  (240, '地理', '第3章 地域調査と日本の地域的特色', '5. 日本の人口', 259, 1, FALSE, '都市部への人口流出などにより、人口が著しく減少することを ( ) という。', '', '過疎(化)', 'かそ(か)'),
  (241, '地理', '第3章 地域調査と日本の地域的特色', '5. 日本の人口', 260, 2, FALSE, 'アジアやアフリカなどの発展途上国で見られる、短期間に人口が急激に増加する現象を ( ) という。', '環境衛生の改善や医療の発達などによって死亡率が低下する一方、高い出生率が続くことからおこる', '人口爆発', 'じんこうばくはつ'),
  (242, '地理', '第3章 地域調査と日本の地域的特色', '5. 日本の人口', 261, 2, FALSE, '15歳未満の人口を年少人口、15歳以上65歳未満の人口を ( )、65歳以上の人口を老年人口という。', '', '生産年齢人口', 'せいさんねんれいじんこう'),
  (243, '地理', '第3章 地域調査と日本の地域的特色', '5. 日本の人口', 262, 2, FALSE, '北海道地方の札幌市、東北地方の仙台市、中国・四国地方の広島市など、その地方の政治・経済の中心となっている都市を何というか。', '', '地方中枢都市', 'ちほうちゅうすうとし'),
  (244, '地理', '第3章 地域調査と日本の地域的特色', '5. 日本の人口', 263, 2, FALSE, '都心部の地価の高騰などにより、郊外に移り住む人が増えたことで、都心部の人口が減少し、郊外の人口が増加した現象を何というか。', '近年は都心部の再開発により、郊外から都心部に移り住む人が増えている(都心回帰)', 'ドーナツ化現象', ''),
  (245, '地理', '第3章 地域調査と日本の地域的特色', '5. 日本の人口', 264, 2, FALSE, '259が進み、65歳以上の高齢者の割合が50%を超え、地域社会の生活の維持が困難になり、存続が危ぶまれる集落を ( ) という。', '', '限界集落', 'げんかいしゅうらく'),
  (246, '地理', '第3章 地域調査と日本の地域的特色', '5. 日本の人口', 265, 2, FALSE, '出身地から都市に移住した人が、再び出身地に戻ることを ( ) という。', '', 'Uターン', ''),
  (247, '地理', '第3章 地域調査と日本の地域的特色', '6. 日本の資源・エネルギー', 266, 1, FALSE, '石油・石炭などを燃焼させることで生じる二酸化炭素に代表される地球の気温を上昇させる気体を総称して ( ) という。', '', '温室効果ガス', 'おんしつこうかガス'),
  (248, '地理', '第3章 地域調査と日本の地域的特色', '6. 日本の資源・エネルギー', 267, 1, FALSE, 'コバルトやクロムなど、埋蔵量が少なく採掘が難しい希少な金属のことを何というか。', 'パソコンやスマートフォンなどの生産に欠かせない金属', 'レアメタル(希少金属)', 'きしょうきんぞく'),
  (249, '地理', '第3章 地域調査と日本の地域的特色', '6. 日本の資源・エネルギー', 268, 1, FALSE, 'ダムなどにためた水が落下するときのエネルギーを利用して発電する方法を何というか。', '日本アルプスなどの山岳地帯に大規模なダムがある', '水力発電', 'すいりょくはつでん'),
  (250, '地理', '第3章 地域調査と日本の地域的特色', '6. 日本の資源・エネルギー', 269, 1, FALSE, '水力・風力・太陽光など、自然界で再生し、繰り返し利用することのできるエネルギーを何というか。', '', '再生可能エネルギー(自然エネルギー)', ''),
  (251, '地理', '第3章 地域調査と日本の地域的特色', '6. 日本の資源・エネルギー', 270, 1, FALSE, 'とうもろこしやさとうきびなどを原料としてつくられるアルコール系の燃料を ( ) という。', '', 'バイオエタノール(バイオ燃料)', 'バイオねんりょう'),
