  (309, '地理', '第4章 日本の諸地域', '3. 近畿地方', 332, 1, FALSE, '京都府と大阪府の境で，宇治川・木津川・桂川が合流して大阪湾へ注ぐ河川を何というか。', '', '淀川', 'よど'),
  (310, '地理', '第4章 日本の諸地域', '3. 近畿地方', 333, 1, FALSE, '滋賀県の中央に位置する日本最大の湖を何というか。', '水質汚染を防ぐために，滋賀県ではリンを含む合成洗剤の販売や使用を禁止する条例を制定するなど，さまざまな取り組みを行っている', '琵琶湖', 'びわこ'),
  (311, '地理', '第4章 日本の諸地域', '3. 近畿地方', 334, 1, FALSE, '近畿地方の南部に位置する，日本最大の半島を何というか。', '林業がさかんな地域で，吉野すぎや尾鷲ひのきが有名', '紀伊半島', 'きい'),
  (312, '地理', '第4章 日本の諸地域', '3. 近畿地方', 335, 1, FALSE, '大阪府と兵庫県を中心に形成された工業地帯を何というか。', '中小企業の工場が多い', '阪神工業地帯', 'はんしん'),
  (313, '地理', '第4章 日本の諸地域', '3. 近畿地方', 336, 2, FALSE, '三重県の東部につき出た，リアス海岸の広がる半島を何というか。', '英虞湾の真珠，的矢湾のかきの養殖が有名', '志摩半島', 'しま'),
  (314, '地理', '第4章 日本の諸地域', '3. 近畿地方', 337, 2, FALSE, '明石海峡大橋で本州と結ばれている，近郊農業がさかんな兵庫県の島を何というか。', 'たまねぎや花の栽培がさかん', '淡路島', 'あわじ'),
  (315, '地理', '第4章 日本の諸地域', '3. 近畿地方', 338, 2, FALSE, '京都の伝統的工芸品の一つで，応仁の乱の際，陣が置かれた場所に発達した絹織物を何というか。', '清水焼や京友禅などの伝統的工芸品もある', '西陣織', 'にしじんおり'),
  (316, '地理', '第4章 日本の諸地域', '3. 近畿地方', 339, 2, FALSE, '大阪湾の泉州沖を埋め立てて造成された，24時間離着陸が可能な国際空港を何というか。', '', '関西国際空港', ''),
  (317, '地理', '第4章 日本の諸地域', '4. 中部地方', 340, 1, FALSE, '北アルプスともよばれる，新潟県・富山県・長野県・岐阜県の県境を南北に連なる山脈を何というか。', '最高峰は奥穂高岳(3190m)', '飛騨山脈', 'ひだ'),
  (318, '地理', '第4章 日本の諸地域', '4. 中部地方', 341, 1, FALSE, '中央アルプスともよばれる，長野県の中央を南北に連なる山脈を何というか。', '最高峰は木曽駒ヶ岳(2956m)', '木曽山脈', 'きそ'),
  (319, '地理', '第4章 日本の諸地域', '4. 中部地方', 342, 1, FALSE, '南アルプスともよばれる，山梨県・長野県・静岡県の県境を南北に連なる山脈を何というか。', '最高峰は北岳(3193m)', '赤石山脈', 'あかいし'),
  (320, '地理', '第4章 日本の諸地域', '4. 中部地方', 344, 1, FALSE, '関東山地から流れ出し，長野県から新潟県を通り日本海へ注ぐ日本最長の河川を何というか。', '', '信濃川', 'しなの'),
  (321, '地理', '第4章 日本の諸地域', '4. 中部地方', 345, 1, FALSE, '長野県から流れ出し，長良川・揖斐川と合流して伊勢湾に注ぐ河川を何というか。', '', '木曽川', 'きそ'),
  (322, '地理', '第4章 日本の諸地域', '4. 中部地方', 346, 1, FALSE, '344の下流に広がる，日本有数の稲作地帯として知られる新潟県の平野を何というか。', '銘柄米(ブランド米)のコシヒカリが有名', '越後平野', 'えちご'),
  (323, '地理', '第4章 日本の諸地域', '4. 中部地方', 347, 1, FALSE, '山梨県中央部に位置し，扇状地で果物の栽培がさかんな盆地を何というか。', '山梨県のぶどう・ももの生産量は日本一(2019年)', '甲府盆地', 'こうふぼんち'),
  (324, '地理', '第4章 日本の諸地域', '4. 中部地方', 348, 1, FALSE, '豊川用水が引かれ，温暖な気候を利用した電照菊やメロンの栽培がさかんな愛知県の半島を何というか。', '愛知県には他に愛知用水(知多半島)，豊川用水(岡崎平野)が引かれている', '渥美半島', 'あつみ'),
