  (326, '地理', '第4章 日本の諸地域', '4. 中部地方', 351, 2, FALSE, '関東地方の北西部で関東地方と中部地方の境になっている山脈を何というか。', '新潟県・福島県・群馬県の県境に位置する', '越後山脈', 'えちごさんみゃく'),
  (327, '地理', '第4章 日本の諸地域', '4. 中部地方', 352, 2, FALSE, '長野県と山梨県にまたがる、高原野菜の栽培がさかんな野辺山原が山麓に広がる山を何というか。', '野辺山原はレタスの栽培がさかん', '八ヶ岳', 'やつがたけ'),
  (328, '地理', '第4章 日本の諸地域', '4. 中部地方', 353, 2, FALSE, '岐阜県の飛騨高地から流れ出して日本海に注ぐ、流域でイタイイタイ病が発生した河川を何というか。', '', '神通川', 'じんつうがわ'),
  (329, '地理', '第4章 日本の諸地域', '4. 中部地方', 354, 2, FALSE, '長野県・山梨県・静岡県を流れて駿河湾に注ぐ、日本三大急流の一つの河川を何というか。', '球磨川と最上川を含めて日本三大急流という', '富士川', ''),
  (330, '地理', '第4章 日本の諸地域', '4. 中部地方', 355, 2, FALSE, '福井県の日本海沿岸部のリアス海岸が広がる湾を何というか。', '沿岸部に原子力発電所が集中している', '若狭湾', 'わかさわん'),
  (331, '地理', '第4章 日本の諸地域', '4. 中部地方', 356, 2, FALSE, '周辺地域で精密機械・電気機械工業が発達している、天竜川の水源になっている湖を何というか。', 'かつて周辺地域で製糸業がさかんであった', '諏訪湖', ''),
  (332, '地理', '第4章 日本の諸地域', '4. 中部地方', 357, 2, FALSE, '345・長良川・揖斐川流域に広がる、愛知県北西部から岐阜県南西部に位置する平野を何というか。', '', '濃尾平野', 'のうび'),
  (333, '地理', '第4章 日本の諸地域', '4. 中部地方', 358, 2, FALSE, '静岡県の大井川下流に広がる、茶の生産がさかんな台地を何というか。', '静岡県の茶の生産量は全国一で、以下鹿児島県・三重県と続く(2020年)', '牧ノ原', 'まきのはら'),
  (334, '地理', '第4章 日本の諸地域', '4. 中部地方', 359, 2, FALSE, '静岡県の遠洋漁業の基地として冷凍施設なども整っている、まぐろ・かつおの水揚げ量が日本有数の港はどこか。', '', '焼津港', ''),
  (335, '地理', '第4章 日本の諸地域', '4. 中部地方', 360, 2, FALSE, '静岡県の太平洋側に発達した工業地域を何というか。', '自動車を中心とする機械工業や、製紙・パルプ工業などが発達している', '東海工業地域', ''),
  (336, '地理', '第4章 日本の諸地域', '4. 中部地方', 361, 2, FALSE, '知多半島の沖合を埋め立てて造成された、24時間利用可能な国際空港を何というか。', '愛称はセントレア', '中部国際空港', ''),
  (337, '地理', '第4章 日本の諸地域', '5. 関東地方', 362, 1, FALSE, '越後山脈から流れ出し、銚子で太平洋に注ぐ流域面積が日本最大の河川を何というか。', '', '利根川', ''),
