  (346, '地理', '第4章 日本の諸地域', '5. 関東地方', 371, 2, FALSE, '関東地方で冬に吹く、乾いた北西の季節風を ( ) という。', '日本海側に雪を降らせたあと、乾いた風となって363に吹きおろす', 'からっ風', ''),
  (347, '地理', '第4章 日本の諸地域', '5. 関東地方', 372, 2, FALSE, '365から工場が移転し、工業団地が進出したことで発展した、栃木県・群馬県・茨城県に形成されている工業地域を何というか。', '', '北関東工業地域', ''),
  (348, '地理', '第4章 日本の諸地域', '5. 関東地方', 373, 2, FALSE, '東京に集中しすぎた都市機能を分散させるため、横浜市につくられた新都心を何というか。', 'さいたま市にはさいたま新都心、千葉市・習志野市には幕張新都心がつくられた', 'みなとみらい21', ''),
  (349, '地理', '第4章 日本の諸地域', '5. 関東地方', 374, 2, FALSE, '東京都大田区に位置する、羽田空港ともよばれる国際空港を何というか。', '国内線の発着が主であったが、国際線の発着も増加した', '東京国際空港', ''),
  (350, '地理', '第4章 日本の諸地域', '6. 東北地方', 375, 1, FALSE, '青森県から福島県まで東北地方を南北に連なる、日本最長の山脈を何というか。', '西に出羽山地、東に北上高地が南北に連なる', '奥羽山脈', 'おうう'),
  (351, '地理', '第4章 日本の諸地域', '6. 東北地方', 376, 1, FALSE, '世界最大規模のぶなの原生林が広がり、世界自然遺産にも登録されている、青森県と秋田県の県境に位置する山地を何というか。', '', '白神山地', 'しらかみ'),
  (352, '地理', '第4章 日本の諸地域', '6. 東北地方', 377, 1, FALSE, 'りんごの栽培がさかんな、岩木川流域に広がる青森県西部の平野を何というか。', 'りんごの集散地は弘前市', '津軽平野', 'つがる'),
  (353, '地理', '第4章 日本の諸地域', '6. 東北地方', 378, 1, FALSE, '青森県の八戸市から宮城県の牡鹿半島まで続く海岸を何というか。', '南部はリアス海岸で良港が多く、わかめやかきなどの養殖業がさかんだが、東日本大震災で津波による大きな被害を受けた', '三陸海岸', ''),
  (354, '地理', '第4章 日本の諸地域', '6. 東北地方', 379, 1, FALSE, '夏に東北地方の太平洋側に吹く、冷たく湿った北東の風を ( ) という。', '冷害の原因となる', 'やませ', ''),
  (355, '地理', '第4章 日本の諸地域', '6. 東北地方', 380, 2, FALSE, '北上川・阿武隈川流域に広がる、稲作がさかんな平野を何というか。', '「ササニシキ」などの銘柄米（ブランド米）の産地', '仙台平野', ''),
  (356, '地理', '第4章 日本の諸地域', '6. 東北地方', 381, 2, FALSE, '最上川の下流域に広がる、稲作がさかんな平野を何というか。', '河口に位置する酒田市は、北前船の拠点として発展した', '庄内平野', 'しょうない'),
  (357, '地理', '第4章 日本の諸地域', '6. 東北地方', 383, 2, FALSE, '青森県と北海道を結ぶ、全長53.85kmの海底トンネルを何というか。', '1988年に完成した', '青函トンネル', 'せいかん'),
  (358, '地理', '第4章 日本の諸地域', '7. 北海道地方', 384, 1, FALSE, '小麦・じゃがいも・てんさい・あずきなどの畑作がさかんな、北海道南東部の平野を何というか。', 'てんさいは砂糖の原料', '十勝平野', 'とかち'),
  (359, '地理', '第4章 日本の諸地域', '7. 北海道地方', 385, 1, FALSE, '土地改良により日本有数の稲作地帯になった、北海道西部の平野を何というか。', '他の場所から土を運ぶ客土を行った', '石狩平野', 'いしかり'),
  (360, '地理', '第4章 日本の諸地域', '7. 北海道地方', 386, 1, FALSE, '火山灰土と濃霧の影響で畑作には向かなかったが、パイロットファームがつくれた日本有数の酪農地域となった、北海道東部の台地を何というか。', '1973年には新酪農村も建設された', '根釧台地', 'こんせん'),
  (361, '地理', '第4章 日本の諸地域', '7. 北海道地方', 387, 2, FALSE, '北海道の中南部に位置し、狩勝峠から襟裳岬にかけて南北に連なる山脈を何というか。', '', '日高山脈', 'ひだか'),
  (362, '地理', '第4章 日本の諸地域', '7. 北海道地方', 388, 2, FALSE, '2005年に世界自然遺産に登録された、北海道東部のオホーツク海につき出た半島を何というか。', '', '知床半島', ''),
  (363, '地理', '第4章 日本の諸地域', '7. 北海道地方', 389, 2, FALSE, '北海道などの寒冷地に設けられている、路面の凍結を防ぐための設備を何というか。', '電熱線や温水パイプを道路の下に埋設し、その熱で雪をとかす', 'ロードヒーティング', ''),
  (364, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 1, 1, FALSE, '約1万年前まで続いた、打製石器を使用し、狩猟・採集などを行って移動生活をしていた時代を何というか。', '', '旧石器時代', 'きゅうせっきじだい'),
  (365, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 2, 1, FALSE, '打製石器だけではなく、磨製石器や土器を使用し、農耕や牧畜を行うようになった時代を何というか。', '', '新石器時代', 'しんせっきじだい'),
  (366, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 3, 1, FALSE, '紀元前3000年ごろに都市国家がつくられ、時間を60進法で測ることなどが考え出された文明を何というか。', '', 'メソポタミア文明', 'メソポタミアぶんめい'),
  (367, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 4, 1, FALSE, 'アフリカのナイル川の流域で紀元前3000年ごろに生まれた文明を何というか。', '', 'エジプト文明', 'エジプトぶんめい'),
  (368, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 5, 1, FALSE, '紀元前2500年ごろ、道路や下水道施設が計画的に整備された都市を中心に栄えた文明を何というか。', '', 'インダス文明', 'インダスぶんめい'),
  (369, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 6, 1, FALSE, '黄河流域や長江流域で生まれた文明を何というか。', '紀元前16世紀ごろに王朝が生まれ、紀元前11世紀には封建制度が整った', '中国文明', 'ちゅうごくぶんめい'),
  (370, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 7, 1, FALSE, '殷で使用された、漢字のもととなった文字を何というか。', '占いの結果を記すために亀の甲羅や牛の骨に刻まれた文字', '甲骨文字', 'こうこつもじ'),
  (371, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 8, 1, FALSE, '紀元前6世紀ごろに現れた思想家によって説かれ、のちの中国・朝鮮・日本の政治や文化に大きな影響を与えた思想を何というか。', '', '儒教(儒学)', 'じゅきょう(じゅがく)'),
  (372, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 9, 1, FALSE, '( )は、紀元前4世紀ごろから実力を強め、紀元前221年に初めて中国を統一した。', '戦国時代の諸国の一つ', '秦', 'しん'),
  (373, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 10, 1, FALSE, '9の王で、初めて皇帝を名乗り、貨幣や文字の統一を行い、思想・言論統制を行った人物はだれか。', '中央集権的な郡県制度による専制政治を行った', '始皇帝', 'しこうてい'),
  (374, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 11, 1, FALSE, '北方の遊牧民族の侵入を防ぐために築かれた建造物を何というか。', '現存の大部分は、14〜17世紀の明の時代につくられたもの', '万里の長城', 'ばんりのちょうじょう'),
  (375, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 12, 1, FALSE, '紀元前1世紀には地中海沿岸地域を統一し、実用的な文化が発達した国を何というか。', '', 'ローマ帝国', 'ローマていこく'),
  (376, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 13, 2, FALSE, '約700万年前にアフリカに現れた、直立歩行をしていた最も古い人類を漢字2字で何というか。', '最古の人類は、アフリカのチャドで発見されたサヘラントロプス・チャデンシス', '猿人', 'えんじん'),
  (377, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 14, 2, FALSE, '13に次いで、今から200万年ほど前に現れた、打製石器を使用し、火やことばを使う人類を漢字2字で何というか。', '脳が13の約2倍になる', '原人', 'げんじん'),
  (378, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 15, 2, FALSE, '20万年ほど前に現れた、完成度の高い打製石器や骨角器を使用する、現在の人類の直接の祖先と考えられている人類を漢字2字で何というか。', '', '新人', 'しんじん'),
  (379, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 17, 2, FALSE, '3で、紀元前18世紀ごろに制定された全282条からなる法典を何というか。', '「目には目を、歯には歯を」', 'ハンムラビ法典', 'ハンムラビほうてん'),
  (380, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 19, 2, FALSE, '月の満ち欠けを基準につくられ、3で使用された暦を何というか。', '', '太陰暦', 'たいいんれき'),
  (381, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 20, 2, FALSE, '4でつくられ、現在も砂漠の中にそびえている王たちの墓を( )という。', '', 'ピラミッド', ''),
  (382, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 21, 2, FALSE, 'パキスタン南部インダス川下流にある5の代表的な遺跡は何か。', '計画的に建設された都市であった', 'モヘンジョ=ダロ', ''),
  (383, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 22, 2, FALSE, '( )はアーリヤ人の侵入の中で生まれ、現在では憲法で禁止されているが、今もインド社会に大きな影響力をもつ身分制度である。', '', 'カースト制度', 'カーストせいど'),
  (384, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 23, 2, FALSE, '紀元前16世紀ごろに黄河流域でおこった、現在確認されている中国で最も古い王朝を何というか。', '', '殷', 'いん'),
  (385, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 24, 2, FALSE, '8のもととなる、仁(思いやりの心)と礼(正しい行い)を重んじる政治を説いた、春秋・戦国時代の思想家はだれか。', '', '孔子', 'こうし'),
  (386, '歴史', '第1章 古代までの日本', '1. 人類の出現と古代文明', 25, 2, FALSE, '9の滅亡後、劉邦によって建国され、武帝の時代に朝鮮や中央アジア、ベトナムにまで支配を広げた大帝国を何というか。', '', '前漢', 'ぜんかん'),
  (387, '歴史', '第1章 古代までの日本', '2. 日本の旧石器時代と縄文・弥生時代', 26, 1, FALSE, '約1万2000年前〜紀元前4世紀ごろまで続いた新石器時代に属し、土器をつくり、おもに狩猟や採集でくらしていた時代を何というか。', '', '縄文時代', 'じょうもんじだい'),
  (388, '歴史', '第1章 古代までの日本', '2. 日本の旧石器時代と縄文・弥生時代', 28, 1, FALSE, '26の時代の人々が食べた貝殻が積もってできた遺跡を何というか。', '動物・魚の骨や壊れた土器、人骨なども出土する', '貝塚', 'かいづか'),
  (389, '歴史', '第1章 古代までの日本', '2. 日本の旧石器時代と縄文・弥生時代', 29, 1, FALSE, '26の時代から奈良時代にかけて一般的に用いられた、当時の人々の住居を何というか。', '地面を掘り下げ、草などで屋根をふく', 'たて穴住居', 'たてあなじゅうきょ'),
  (390, '歴史', '第1章 古代までの日本', '2. 日本の旧石器時代と縄文・弥生時代', 30, 1, FALSE, '26の時代に安産や豊かな収穫を祈ってつくられたと思われる土製の人形を何というか。', '女性をかたどったものが多い', '土偶', 'どぐう'),
  (391, '歴史', '第1章 古代までの日本', '2. 日本の旧石器時代と縄文・弥生時代', 31, 1, FALSE, '青森県に位置し、大型掘立柱建物跡や計画的にくりが栽培されていたことが確認できる26の時代の大規模な集落遺跡を何というか。', '2021年、世界文化遺産に登録された', '三内丸山遺跡', 'さんないまるやまいせき'),
  (392, '歴史', '第1章 古代までの日本', '2. 日本の旧石器時代と縄文・弥生時代', 32, 1, FALSE, '紀元前4世紀ごろ〜紀元後3世紀ごろまで続いた、稲作が九州地方に伝えられ、東日本にまで広がった時代を何というか。', '', '弥生時代', 'やよいじだい'),
  (393, '歴史', '第1章 古代までの日本', '2. 日本の旧石器時代と縄文・弥生時代', 33, 1, FALSE, '1884年に東京都文京区で発見された、薄手でやや高温で焼かれた赤褐色をした土器を何というか。', '', '弥生土器', 'やよいどき'),
  (394, '歴史', '第1章 古代までの日本', '2. 日本の旧石器時代と縄文・弥生時代', 34, 1, FALSE, '周りを堀で囲み、物見やぐらもつくられた、佐賀県の大規模な環濠集落跡を何というか。', '激しい戦闘の跡がある', '吉野ヶ里遺跡', 'よしのがりいせき'),
  (395, '歴史', '第1章 古代までの日本', '2. 日本の旧石器時代と縄文・弥生時代', 35, 1, FALSE, '奴国の王が後漢の光武帝から授けられたと考えられているもので、江戸時代に発見されたものは何か。', '「漢委奴国王」と刻まれている', '金印', 'きんいん'),
  (396, '歴史', '第1章 古代までの日本', '2. 日本の旧石器時代と縄文・弥生時代', 36, 1, FALSE, '3世紀の日本で、30余りの小国を従え、その位置について北九州説と畿内説がある国を何というか。', '', '邪馬台国', 'やまたいこく'),
  (397, '歴史', '第1章 古代までの日本', '2. 日本の旧石器時代と縄文・弥生時代', 37, 1, FALSE, '36の女王の( )は、魏の皇帝に使者を送り、「親魏倭王」の称号や銅鏡100枚などを授けられた。', '', '卑弥呼', 'ひみこ'),
  (398, '歴史', '第1章 古代までの日本', '2. 日本の旧石器時代と縄文・弥生時代', 38, 2, FALSE, '( )は、1946年に相沢忠洋が日本で初めて打製石器を発見した、群馬県にある旧石器時代の遺跡である。', '', '岩宿遺跡', 'いわじゅくいせき'),
  (399, '歴史', '第1章 古代までの日本', '2. 日本の旧石器時代と縄文・弥生時代', 39, 2, FALSE, '明治時代にアメリカの動物学者モースが発見し、日本初の発掘調査が行われた28を何というか。', '', '大森貝塚', 'おおもりかいづか'),
  (400, '歴史', '第1章 古代までの日本', '2. 日本の旧石器時代と縄文・弥生時代', 40, 2, FALSE, '実った稲の穂先を摘み取るときに使われる磨製石器を何というか。', '穴にひもを通して使用する', '石包丁', 'いしぼうちょう'),
  (401, '歴史', '第1章 古代までの日本', '2. 日本の旧石器時代と縄文・弥生時代', 41, 2, FALSE, '銅とすずの合金でつくられた、金属器を何というか。', '鉄器と同時期に伝えられた', '青銅器', 'せいどうき'),
  (402, '歴史', '第1章 古代までの日本', '2. 日本の旧石器時代と縄文・弥生時代', 43, 2, FALSE, '福岡県博多付近にあったと考えられている「後漢書」東夷伝に記されている小国を何というか。', '', '奴国', 'なこく(なのくに)'),
  (403, '歴史', '第1章 古代までの日本', '2. 日本の旧石器時代と縄文・弥生時代', 44, 2, FALSE, '36や37についての記述が見られる、3世紀後半に成立した中国の歴史書を何というか。', '「三国志」の中の一部', '『魏志』倭人伝', '「ぎし」わじんでん'),
  (404, '歴史', '第1章 古代までの日本', '3. 古墳文化と大和政権', 45, 1, FALSE, '天皇や豪族の墓がさかんにつくられていた3世紀後半〜6世紀末ごろまでの時代を何というか。', '', '古墳時代', 'こふんじだい'),
  (405, '歴史', '第1章 古代までの日本', '3. 古墳文化と大和政権', 46, 1, FALSE, '天皇や豪族をほうむるためにつくられた巨大な墓を何というか。', '近畿地方を中心に、吉備、出雲、毛野、筑紫などに多く分布', '古墳', 'こふん'),
  (406, '歴史', '第1章 古代までの日本', '3. 古墳文化と大和政権', 47, 1, FALSE, '46のうち、円形と方形を組み合わせた、かぎ穴形のものを何というか。', '規模の大きな46の多くがこの形をしている', '前方後円墳', 'ぜんぽうこうえんふん'),
  (407, '歴史', '第1章 古代までの日本', '3. 古墳文化と大和政権', 48, 1, FALSE, '46の上や周りに置かれた、円筒や家などさまざまな形をした土製の焼き物を何というか。', '当時の生活が推測できる', '埴輪', 'はにわ'),
  (408, '歴史', '第1章 古代までの日本', '3. 古墳文化と大和政権', 49, 1, FALSE, '3世紀後半に奈良盆地を中心とした地域に出現した有力豪族が連合して成立した政権を何というか。', '5世紀には、九州〜東北南部まで勢力を拡大', '大和政権(ヤマト王権)', 'やまとせいけん(ヤマトおうけん)'),
  (409, '歴史', '第1章 古代までの日本', '3. 古墳文化と大和政権', 50, 1, FALSE, '7世紀後半から天皇とよばれるようになった、49の首長を何というか。', '稲荷山古墳出土の鉄剣などに、この文字が刻まれている', '大王', 'おおきみ(だいおう)'),
  (410, '歴史', '第1章 古代までの日本', '3. 古墳文化と大和政権', 51, 1, FALSE, 'おもに4〜6世紀に、大陸や朝鮮半島から一族で移住し、養蚕や機織などの優れた技術や仏教・儒教などをもたらした人々を何というか。', '', '渡来人', 'とらいじん'),
  (411, '歴史', '第1章 古代までの日本', '3. 古墳文化と大和政権', 56, 2, FALSE, '稲荷山古墳から出土した鉄剣に刻まれている「ワカタケル大王」は（ ）天皇と考えられている。', '', '雄略', 'ゆうりゃく'),
  (412, '歴史', '第1章 古代までの日本', '3. 古墳文化と大和政権', 57, 2, FALSE, '51は高温で焼かれた硬い土器づくりを伝えたが、この土器を何というか。', '1000〜1200度の高温で焼いてつくった', '須恵器', 'すえき'),
  (413, '歴史', '第1章 古代までの日本', '3. 古墳文化と大和政権', 58, 2, FALSE, '（ ）は51などによりもたらされ、5世紀ごろからその音を借りて日本人の名前や地名を書き表すようになった。', '', '漢字', 'かんじ'),
  (414, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 59, 1, FALSE, '593年、（ ）は推古天皇の政治の補佐役となり、天皇中心の国家づくりを行った。', '厩戸皇子（厩戸王）の後世のよび名である', '聖徳太子', 'しょうとくたいし'),
  (415, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 60, 1, FALSE, '59が定めた、家柄にとらわれず、才能のある人材を役人に取り立て、冠の色で区別する制度を何というか。', '', '冠位十二階', 'かんいじゅうにかい'),
  (416, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 61, 1, FALSE, '59が定めた、和を尊重することや、天皇に服従することを内容とした、朝廷の役人としての心構えを示した法令を何というか。', '仏教や儒教の影響を強く受けている', '十七条の憲法', 'じゅうしちじょうのけんぽう'),
  (417, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 62, 1, FALSE, '59が、中国の進んだ政治制度や文化を学ぶとともに、対等な外交を行う目的で隋に派遣した使節を何というか。', '', '遣隋使', 'けんずいし'),
  (418, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 63, 1, FALSE, '渡来人が文化の形成に大きな役割を果たした、日本で最初の仏教文化を何というか。', '', '飛鳥文化', 'あすかぶんか'),
  (419, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 65, 1, FALSE, '645年、それまで政治の実権を握っていた蘇我氏を倒して始められた政治改革を何というか。', '翌年、土地と人民を直接国家が支配する方針が示された', '大化の改新', 'たいかのかいしん'),
  (420, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 66, 1, FALSE, '65を推し進め、都を近江の大津宮に移し、668年に即位して天智天皇となった人物はだれか。', '最初の全国的戸籍である庚午年籍を作成', '中大兄皇子', 'なかのおおえのおうじ'),
  (421, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 67, 1, FALSE, '天皇や豪族による土地と人民の支配をやめて、朝廷が直接支配することを何というか。', '646年に改新の詔で示された', '公地公民', 'こうちこうみん'),
  (422, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 68, 1, FALSE, '66の死後、天皇の子と天皇の弟との間で皇位をめぐっておきた争いを何というか。', '日本の古代における最大の内乱', '壬申の乱', 'じんしんのらん'),
  (423, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 69, 1, FALSE, '68に勝利した大海人皇子は、673年に即位して（ ）となり、天皇中心の強力な政治体制をつくり、律令に基づく政治を推し進めた。', '', '天武天皇', 'てんむてんのう'),
  (424, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 70, 1, FALSE, '701年に、刑部親王、藤原不比等などが中国の律令にならって制定した、初の本格的に整った律令を何というか。', '', '大宝律令', 'たいほうりつりょう'),
  (425, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 71, 2, FALSE, '仏教の受け入れに反対した物部氏を滅ぼし、大王と婚姻関係を結ぶことで権力を強めた豪族を何というか。', '渡来人を保護して、勢力を強めた', '蘇我氏', 'そがし'),
  (426, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 72, 2, FALSE, '592年、日本で最初の女性天皇として即位したのはだれか。', 'おいの59らとともに、天皇中心の国づくりを進めた', '推古天皇', 'すいこてんのう'),
  (427, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 73, 2, FALSE, '72が即位した592年から、平城京に都が移される710年までの期間を（ ）時代という。', '', '飛鳥', 'あすか'),
  (428, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 74, 2, FALSE, '天皇が女性や幼少のときに天皇に代わり政治を行うための役職を何というか。', '皇族以外がこの役職に就いたのは、866年の藤原良房が最初', '摂政', 'せっしょう'),
  (429, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 75, 2, FALSE, '589年に中国を統一し、黄河と長江を結ぶ大運河を建設した王朝を何というか。', '都は大興城（長安）に置かれた', '隋', 'ずい'),
  (430, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 76, 2, FALSE, '59の命によって、607〜608年、608〜609年の2回、62として派遣された人物はだれか。', '煬帝のもとに国書を持参したとされる', '小野妹子', 'おののいもこ'),
  (431, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 77, 2, FALSE, '75を滅ぼし、律令を整備して均田制を実施した、中国の統一王朝を何というか。', '朝鮮半島北部から、中央アジア・ベトナムにまで領土を広げた', '唐', 'とう'),
  (432, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 78, 2, FALSE, '現在の西安にあった、最盛期には人口が100万人を超えた77の都を何というか。', '日本の平城京の4倍以上の面積があった', '長安', 'ちょうあん'),
  (433, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 79, 2, FALSE, '66とともに65を推し進め、死の間際に「藤原」の姓を授かり、藤原氏の祖となった人物はだれか。', '', '中臣鎌足', 'なかとみのかまたり'),
  (434, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 80, 2, FALSE, '百済を再興するため、66が大軍を派遣したが、77・新羅の連合軍に敗北した戦いを何というか。', '敗北後、都を近江に移し、各地に城を築いた', '白村江の戦い', 'はくすきのえ'),
  (435, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 81, 2, FALSE, '69のころから使われるようになったと考えられている、それまでの「大王」という呼称に代わる君主の称号を何というか。', '', '天皇', 'てんのう'),
  (436, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 82, 2, FALSE, '（ ）とは、律令制度における役所のことをいう。', '中央には神祇官・太政官と、政治を分担して行う省が置かれた', '二官八省', 'にかんはっしょう'),
  (437, '歴史', '第1章 古代までの日本', '4. 律令国家へのあゆみ', 83, 2, FALSE, '常任ではなく適任者がいないときは欠員とされた、律令制のもとでの最高責任者を何というか。', 'その下に左大臣・右大臣が置かれた', '太政大臣', 'だいじょうだいじん'),
  (438, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 86, 1, FALSE, '諸国の政治・裁判を行うために中央から派遣され、地方の役人を指揮・監督した役人を何というか。', '', '国司', 'こくし'),
  (439, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 87, 1, FALSE, '戸籍に基づき、6歳以上の人々に性別や身分に応じて田を支給し、死ねば国に返えさせた制度を何というか。', '', '班田収授法', 'はんでんしゅうじゅのほう'),
  (440, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 88, 1, FALSE, '87によって支給された、男子は2段、女子はその3分の2の広さの田を（ ）という。', '奴婢にはそれぞれ良民の3分の1が支給された', '口分田', 'くぶんでん'),
  (441, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 89, 1, FALSE, '88を支給された農民に課せられた、収穫量の約3％の稲を納めさせた税を何というか。', '国府（一部は中央）に納めた', '租', 'そ'),
  (442, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 90, 1, FALSE, '3年間九州北部の防衛にあたる（ ）は、兵役を課せられた兵士の中から選ばれた。', 'おもに東国の農民が派遣された', '防人', 'さきもり'),
  (443, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 91, 1, FALSE, '743年に出された、新たに開墾した土地の私有を認めることを定めた法令を何というか。', '私有地はのちの荘園のもととなった', '墾田永年私財法', 'こんでんえいねんしざいのほう'),
  (444, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 92, 1, FALSE, '630年から894年に停止されるまで、中国の進んだ制度を取り入れるために朝廷が派遣した使節を何というか。', '菅原道真の進言で停止', '遣唐使', 'けんとうし'),
  (445, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 93, 1, FALSE, '92が伝えた唐の文化の影響を強く受けた、国際的性格をもった奈良時代の文化を何というか。', '', '天平文化', 'てんぴょうぶんか'),
  (446, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 94, 1, FALSE, '（ ）は、仏教を深く信仰し、仏教の力で国を治めようと、国分寺・国分尼寺の建立、大仏の造立などを命じた。', '', '聖武天皇', 'しょうむてんのう'),
  (447, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 97, 1, FALSE, '712年に完成した、稗田阿礼が暗記していた皇室を中心とした神話や歴史を太安万侶がまとめた歴史書を何というか。', '', '古事記', 'こじき'),
  (448, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 98, 1, FALSE, '720年に完成した、舎人親王・太安万侶らが中国の歴史書の形式にならって記した日本最古の公式の歴史書を何というか。', '', '日本書紀', 'にほんしょき'),
  (449, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 99, 1, FALSE, '天皇から貴族、農民、90にまでわたる約4500首の歌が集められた日本最古の和歌集を何というか。', '', '万葉集', 'まんようしゅう'),
  (450, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 100, 2, FALSE, '7世紀後半の天武天皇の時代に、日本で初めて鋳造されたといわれる貨幣を何というか。', '流通の程度は不明', '富本銭', 'ふほんせん'),
  (451, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 101, 2, FALSE, '708年に鋳造され，85を中心に流通した貨幣を何というか。', '85の東西の市などで使われた', '和同開珎', 'わどうかいちん'),
  (452, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 102, 2, FALSE, '九州北部に置かれ，「遠の朝廷」とよばれた，唐や朝鮮との外交や防衛にあたる役所を何というか。', '', '大宰府', 'だざいふ'),
  (453, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 103, 2, FALSE, '税を徴収し，兵を集めるために，6年ごとに作成された基本台帳を何というか。', '最も古いものは天智天皇のときの庚午年籍', '戸籍', 'こせき'),
  (454, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 104, 2, FALSE, '地方の特産物を中央に納めさせた，成年男子に課せられた税を何というか。', '絹などを都まで運んで納めた', '調', 'ちょう'),
  (455, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 105, 2, FALSE, '都での10日間の労役の代わりに布を納めさせた，成年男子に課せられた税を何というか。', '', '庸', 'よう'),
  (456, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 106, 2, FALSE, '山上憶良が奈良時代の農民の苦しい生活を表した歌である（ ）は，99に収められている。', '', '貧窮問答歌', 'びんきゅうもんどうか'),
  (457, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 107, 2, FALSE, '723年に出された，新しく開墾すれば3代，荒れた土地を回復すれば1代，その土地を自由に耕作できるとした法令を何というか。', '', '三世一身の法', 'さんぜいいっしんのほう'),
  (458, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 109, 2, FALSE, '断面が台形や三角形の木材を井げたに組み上げて壁面をつくる建築様式を何というか。', '96はこの建築様式を用いて建てられている', '校倉造', 'あぜくらづくり'),
  (459, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 110, 2, FALSE, '大僧正に任じられ，95の大仏造立に協力した人物はだれか。', '渡来人の子孫で，民衆に仏教を広め，池や橋などをつくって人々からしたわれた', '行基', 'ぎょうき'),
  (460, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 111, 2, FALSE, '（ ）は，何度も遭難し，盲目になりながらも日本に戒律を伝えた唐の高僧である。', '', '鑑真', 'がんじん'),
  (461, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 112, 2, FALSE, '唐から来日した111が759年に創建した，律宗の総本山にあたる寺院を何というか。', '世界文化遺産「古都奈良の文化財」の一つ', '唐招提寺', 'とうしょうだいじ'),
  (462, '歴史', '第1章 古代までの日本', '5. 平城京と天平文化', 113, 2, FALSE, '国ごとに，その地に伝わる伝説，産物などをまとめさせた書物を何というか。', '出雲・播磨・豊後・肥前・常陸の5つの国のものが残っている', '風土記', 'ふどき'),
  (463, '歴史', '第1章 古代までの日本', '6. 平安京と貴族の政治', 114, 1, FALSE, '794年に都を移してから，鎌倉幕府が成立するまでの約400年間を何時代というか。', '', '平安時代', 'へいあんじだい'),
  (464, '歴史', '第1章 古代までの日本', '6. 平安京と貴族の政治', 115, 1, FALSE, '乱れた律令政治を立て直すために，政治と宗教を切り離そうと2度も遷都を行った天皇はだれか。', '1度目は784年，長岡京に遷都した', '桓武天皇', 'かんむてんのう'),
  (465, '歴史', '第1章 古代までの日本', '6. 平安京と貴族の政治', 117, 1, FALSE, '大化の改新の中心となった中臣鎌足を祖とし，不比等等の時代から天皇家との婚姻関係を強めていった一族を何というか。', '', '藤原氏', 'ふじわらうじ'),
  (466, '歴史', '第1章 古代までの日本', '6. 平安京と貴族の政治', 118, 1, FALSE, '天皇が成人してからも，天皇を補佐する役職を（ ）という。', '117がその役職に就くのが慣例となった', '関白', 'かんぱく'),
  (467, '歴史', '第1章 古代までの日本', '6. 平安京と貴族の政治', 119, 1, FALSE, '117の一族が，天皇の補佐役として政治の実権を握り，天皇に代わって行った政治を何というか。', '', '摂関政治', 'せっかんせいじ'),
  (468, '歴史', '第1章 古代までの日本', '6. 平安京と貴族の政治', 120, 1, FALSE, '11世紀の初め，4人の娘を天皇のきさきにし，117の一族の全盛期を築いた人物はだれか。', '「この世をば わが世とぞ思う 望月の 欠けたることもなしと思えば」という歌を詠んだ', '藤原道長', 'ふじわらのみちなが'),
  (469, '歴史', '第1章 古代までの日本', '6. 平安京と貴族の政治', 121, 1, FALSE, '120の子で，父とともに119の全盛期を築き，約50年間天皇を補佐する位に居続けた人物はだれか。', '', '藤原頼通', 'ふじわらのよりみち'),
  (470, '歴史', '第1章 古代までの日本', '6. 平安京と貴族の政治', 122, 1, FALSE, '743年に出された墾田永年私財法により，有力な寺社や貴族が所有するようになった私有地を（ ）という。', '', '荘園', 'しょうえん'),
  (471, '歴史', '第1章 古代までの日本', '6. 平安京と貴族の政治', 123, 2, FALSE, '東北地方の蝦夷を支配するために，坂上田村麻呂は115から（ ）に任命された。', '', '征夷大将軍', 'せいがいたいしょうぐん'),
  (472, '歴史', '第1章 古代までの日本', '6. 平安京と貴族の政治', 124, 2, FALSE, '唐から帰国した僧によって広められた，法華経を教典の中心とする仏教の一派を（ ）という。', '山中で厳しい修行を積む', '天台宗', 'てんだいしゅう'),
  (473, '歴史', '第1章 古代までの日本', '6. 平安京と貴族の政治', 125, 2, FALSE, '（ ）は804年に遣唐使とともに唐に渡り，124の教えを学んで翌年に帰国し，日本に広めた。', '伝教大師ともいわれる', '最澄', 'さいちょう'),
  (474, '歴史', '第1章 古代までの日本', '6. 平安京と貴族の政治', 126, 2, FALSE, '滋賀県大津市比叡山に位置する124の宗派の総本山である寺院を何というか。', '鎌倉仏教の法然や道元らもこの寺院で学んだ', '延暦寺', 'えんりゃくじ'),
  (475, '歴史', '第1章 古代までの日本', '6. 平安京と貴族の政治', 127, 2, FALSE, '806年，唐から帰国した僧によって開かれた仏教で，密教の一派である宗派を何というか。', '', '真言宗', 'しんごんしゅう'),
  (476, '歴史', '第1章 古代までの日本', '6. 平安京と貴族の政治', 128, 2, FALSE, '遣唐使とともに唐に渡り，密教を学んで127を日本に広めた僧はだれか。', '弘法大師ともいわれる', '空海', 'くうかい'),
  (477, '歴史', '第1章 古代までの日本', '6. 平安京と貴族の政治', 129, 2, FALSE, '和歌山県伊都郡高野町に位置する127の宗派の総本山である寺院を何というか。', '128が816年に創建した', '金剛峯寺', 'こんごうぶじ'),
  (478, '歴史', '第1章 古代までの日本', '7. 国風文化', 130, 1, FALSE, '（ ）とは，漢字をくずしたり，漢字のへんやつくりからつくられた，おもに女性が使用した文字である。', '', 'かな文字', ''),
  (479, '歴史', '第1章 古代までの日本', '7. 国風文化', 131, 1, FALSE, '一条天皇の中宮である彰子（藤原道長の娘）に仕え，130を用いて長編小説を著した女性はだれか。', '', '紫式部', 'むらさきしきぶ'),
  (480, '歴史', '第1章 古代までの日本', '7. 国風文化', 132, 1, FALSE, '一条天皇の皇后である定子（藤原道隆の娘）に仕えた，清原元輔の娘で，随筆を著した女性はだれか。', '', '清少納言', 'せいしょうなごん'),
  (481, '歴史', '第1章 古代までの日本', '7. 国風文化', 133, 1, FALSE, '（ ）は，「万葉集」以後の約1100首の歌が収められた最初の勅撰和歌集である。', '醍醐天皇の命でまとめられた', '古今和歌集', 'こきんわかしゅう'),
  (482, '歴史', '第1章 古代までの日本', '7. 国風文化', 134, 1, FALSE, '11世紀，藤原頼通が宇治にあった別荘を寺とし，その境内に建てた阿弥陀堂を何というか。', '本尊は定朝による阿弥陀如来像', '平等院鳳凰堂', 'びょうどういんほうおうどう'),
  (483, '歴史', '第1章 古代までの日本', '7. 国風文化', 135, 2, FALSE, '（ ）は，894年に遣唐使の派遣の停止を進言し，のちに藤原氏の陰謀によって大宰府に流された。', '天満宮に祭られている', '菅原道真', 'すがわらのみちざね'),
  (484, '歴史', '第1章 古代までの日本', '7. 国風文化', 136, 2, FALSE, '光源氏を中心とする平安貴族の生活を描いた，131が著した小説を何というか。', '11世紀初めに成立した54帖からなる長編小説', '源氏物語', 'げんじものがたり'),
  (485, '歴史', '第1章 古代までの日本', '7. 国風文化', 137, 2, FALSE, '132が宮廷生活をしていたところに見聞きしたことや，季節の感想，人生観などを記した随筆を何というか。', '', '枕草子', 'まくらのそうし'),
  (486, '歴史', '第1章 古代までの日本', '7. 国風文化', 138, 2, FALSE, '平安時代の貴族・歌人で，土佐の国司の任期を終えて都に帰るまでの日記を130で著したのはだれか。', '133の撰者の一人でもある', '紀貫之', 'きのつらゆき'),
  (487, '歴史', '第1章 古代までの日本', '7. 国風文化', 139, 2, FALSE, '阿弥陀仏にすがり念仏を唱えれば，死後，極楽浄土に生まれ変わることができるという，平安時代中期に広まった教えを（ ）という。', '', '浄土信仰', 'じょうどしんこう'),
  (488, '歴史', '第1章 古代までの日本', '7. 国風文化', 140, 2, FALSE, '平安時代の貴族の邸宅の建築様式を何というか。', '建物は渡り廊下でつながれている', '寝殿造', 'しんでんづくり'),
  (489, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 141, 1, FALSE, '10世紀に，一族の争いをきっかけに反乱をおこし，一時，関東一帯を占拠して新皇と称した人物はだれか。', '平貞盛・藤原秀郷らに討たれた', '平将門', 'たいらのまさかど'),
  (490, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 142, 1, FALSE, '伊予の国司であったが任期が終わっても都に戻らず，瀬戸内海の海賊を率いて反乱をおこした人物はだれか。', '源経基らに討たれた', '藤原純友', 'ふじわらのすみとも'),
  (491, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 143, 1, FALSE, '後三条天皇の子で，藤原氏をおさえて自らが政治を行うために，1086年に幼少の天皇に位を譲って政治を行ったのはだれか。', '', '白河天皇', 'しらかわてんのう'),
  (492, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 144, 1, FALSE, '（ ）とは，天皇が位を譲った後も，上皇・法皇として政治を行う形態である。', '1086年に143が始めた', '院政', 'いんせい'),
  (493, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 145, 1, FALSE, '後白河天皇と崇徳上皇の対立に藤原氏一族の争いがからんで，1156年，京都でおきた戦乱を何というか。', '平氏と源氏も勢力を二分して戦った', '保元の乱', 'ほうげんのらん'),
  (494, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 146, 1, FALSE, '145の後，平氏と源氏の対立が激しくなり，藤原氏内部の対立とも結びついて，1159年，再び京都でおきた戦乱を何というか。', 'この戦乱後，平氏の政権が成立した', '平治の乱', 'へいじのらん'),
  (495, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 147, 1, FALSE, '1167年，武士として初めて太政大臣となり，平氏の全盛期を築いたのはだれか。', '娘を天皇のきさきとし，その子を天皇に立てた', '平清盛', 'たいらのきよもり'),
  (496, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 148, 1, FALSE, '147は兵庫の港を修築して（ ）貿易を行った。', '輸入品は銅銭・絹織物・陶磁器など，輸出品は硫黄・刀剣・金など', '日宋', 'にっそう'),
  (497, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 149, 1, FALSE, '1185年に国ごとに置かれた，軍事・犯罪の取り締まりを行う鎌倉幕府の地方機関を何というか。', '', '守護', 'しゅご'),
  (498, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 150, 1, FALSE, '1185年に荘園や公領に置かれた，年貢の取り立てなどを行う鎌倉幕府の地方機関を何というか。', '当初は，149とともに，源義経を捕らえることを名目に朝廷に設置を認めさせた', '地頭', 'じとう'),
  (499, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 151, 1, FALSE, '( ) とは，1185年に開かれ，1333年に滅ぶまで約150年間続いた初の本格的な武家政権である。', '成立時期についてはいろいろな説がある', '鎌倉幕府', 'かまくらばくふ'),
  (500, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 152, 1, FALSE, '1192年に征夷大将軍に任じられたのはだれか。', '1180年，伊豆で平氏打倒の兵を挙げた', '源頼朝', 'みなもとのよりとも'),
  (501, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 153, 1, FALSE, '151の政権において，将軍を補佐する役職を何というか。', '代々，152の妻の実家である北条氏が世襲した', '執権', 'しっけん'),
  (502, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 155, 1, FALSE, '将軍が154に対して，領地を保護したり，手柄があれば新しい土地を与えたりすることを ( ) という。', '', '御恩', 'ごおん'),
  (503, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 156, 1, FALSE, '将軍からの155に対し，154が将軍に忠誠を誓い，戦いがおこれば将軍のために戦うことを ( ) という。', '', '奉公', 'ほうこう'),
  (504, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 157, 1, FALSE, '152の妻で，1221年の戦乱に際して，幕府内の結束を訴える演説を行ったのはだれか。', '「尼将軍」とよばれた', '北条政子', 'ほうじょうまさこ'),
  (505, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 158, 1, FALSE, '後鳥羽上皇が政治の実権を朝廷に取り戻そうと，1221年に兵を挙げたできごとを何というか。', '源氏の直系将軍が絶えたことがきっかけ', '承久の乱', 'じょうきゅうのらん'),
  (506, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 159, 1, FALSE, '158の後，朝廷の監視や西国の武士の統率を行うために，京都に置かれた役所を何というか。', '代々，北条氏が任命された', '六波羅探題', 'ろくはらたんだい'),
  (507, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 160, 1, FALSE, '鎌倉幕府第3代執権で，158で上皇方を破ったのはだれか。', '1225年，評定制を設置した', '北条泰時', 'ほうじょうやすとき'),
  (508, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 161, 1, FALSE, '1232年，160が裁判の基準を示すために定めた，51か条からなる初の武家法を何というか。', '貞永式目ともいわれる', '御成敗式目', 'ごせいばいしきもく'),
  (509, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 162, 2, FALSE, '平安時代の中ごろ，自分の土地や財産を守るために武装した有力な農民と，軍事担当の中・下級貴族との交流から生まれた，武芸を専門とする者を何というか。', '階級そのものを指す場合もある', '武士', 'ぶし'),
  (510, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 163, 2, FALSE, '162たちがつくった一族や従者からなるまとまりを ( ) という。', 'このまとまりの頭を棟梁という', '武士団', 'ぶしだん'),
  (511, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 164, 2, FALSE, '桓武天皇の子孫で，もともと関東に勢力があったが，のちに西国に勢力をのばした162の棟梁の家柄の一つを何というか。', '', '平氏', 'へいし'),
  (512, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 165, 2, FALSE, '162の力を社会に示すこととなった141の乱と142の乱を合わせて， ( ) という。', '同時期に2つの反乱がおき，朝廷は大きな衝撃を受けた', '承平・天慶の乱', 'じょうへい・てんぎょうのらん'),
  (513, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 166, 2, FALSE, '清和天皇の子孫で，11世紀以降，東国に勢力をのばしていった162の棟梁の家柄の一つを何というか。', '', '源氏', 'げんじ'),
  (514, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 167, 2, FALSE, '11世紀の陸奥で，安倍頼時・貞任親子が国司に対しておこした反乱を何というか。', '166が清原氏の力を借りてしずめた', '前九年合戦', 'ぜんくねんかっせん'),
  (515, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 169, 2, FALSE, '藤原清衡が，現在の岩手県の168に1124年に建立した，清衡・基衡・秀衡の遺体が安置されている阿弥陀堂を何というか。', '', '中尊寺金色堂', 'ちゅうそんじこんじきどう'),
  (516, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 170, 2, FALSE, '145では勝利したが，146で147に敗れ，逃走中に暗殺された，源頼朝の父はだれか。', '', '源義朝', 'みなもとのよしとも'),
  (517, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 171, 2, FALSE, '現在の神戸港の一部で，147が148貿易の拠点として改修した港を何というか。', '', '大輪田泊', 'おおわだのとまり'),
  (518, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 172, 2, FALSE, '( ) は，兄である166の棟梁が164打倒のために挙兵すると，これに加わって164を滅ぼした。', 'のちに兄と対立し，168に逃れた', '源義経', 'みなもとのよしつね'),
  (519, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 173, 2, FALSE, '1185年に，172の軍勢によって164が滅亡した戦乱を何というか。', '現在の山口県の関門海峡で行われた海戦である', '壇ノ浦の戦い', 'だんのうらのたたかい'),
  (520, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 174, 2, FALSE, '鎌倉に幕府が置かれていた12世紀末から1333年に滅びるまでの約150年間を ( ) という。', '', '鎌倉時代', 'かまくらじだい'),
  (521, '歴史', '第2章 中世の日本', '1. 武士の台頭と鎌倉幕府の成立', 175, 2, FALSE, '土地を仲立ちにした，主君と家臣の主従関係で成り立つ制度を ( ) という。', '151は，この制度に基づいて成立した最初の政権', '封建制度', 'ほうけんせいど'),
  (522, '歴史', '第2章 中世の日本', '2. 武士・民衆の生活と鎌倉時代の文化', 176, 1, FALSE, '月に数回，寺社の門前などで，定められた日に商品を売買する ( ) が開かれるようになった。', '鎌倉時代は月に3度開かれる三斎市であったが，室町時代には月に6度開かれる六斎市も生まれた', '定期市', 'ていきいち'),
  (523, '歴史', '第2章 中世の日本', '2. 武士・民衆の生活と鎌倉時代の文化', 177, 1, FALSE, '後鳥羽上皇の命で，藤原定家らは ( ) という和歌集を編集した。', '繊細で華麗な歌が集められている', '新古今和歌集', 'しんこきんわかしゅう'),
  (524, '歴史', '第2章 中世の日本', '2. 武士・民衆の生活と鎌倉時代の文化', 178, 1, FALSE, '「枕草子」とともに随筆の傑作とされる，兼好法師が著した鎌倉時代末期の随筆を何というか。', '', '徒然草', 'つれづれぐさ'),
  (525, '歴史', '第2章 中世の日本', '2. 武士・民衆の生活と鎌倉時代の文化', 179, 1, FALSE, '「南無阿弥陀仏」と念仏を唱えれば，だれでも極楽浄土に生まれ変われると説く浄土宗を開いた僧はだれか。', '', '法然', 'ほうねん'),
  (526, '歴史', '第2章 中世の日本', '2. 武士・民衆の生活と鎌倉時代の文化', 180, 1, FALSE, '179の弟子の親鸞が，師の教えを発展させて開いた宗派を何というか。', '自分の罪を自覚した悪人こそが救われると説いた（悪人正機説）', '浄土真宗(一向宗)', 'じょうどしんしゅう(いっこうしゅう)'),
  (527, '歴史', '第2章 中世の日本', '2. 武士・民衆の生活と鎌倉時代の文化', 181, 1, FALSE, '「南無妙法蓮華経」と唱えれば成仏し，国家も安泰であると教える法華宗を開いた僧はだれか。', '他宗を激しく非難し，弾圧を受けた', '日蓮', 'にちれん'),
  (528, '歴史', '第2章 中世の日本', '2. 武士・民衆の生活と鎌倉時代の文化', 182, 1, FALSE, '座禅を行うことで自己の悟りを開く，自力本願をめざす仏教を何というか。', '6世紀ごろに中国に伝わった仏教の一派', '禅宗', 'ぜんしゅう'),
  (529, '歴史', '第2章 中世の日本', '2. 武士・民衆の生活と鎌倉時代の文化', 183, 1, FALSE, '182の一派である臨済宗を宋から伝え，幕府の保護を受け，鎌倉で教えを広めた僧はだれか。', '日本に茶をもたらした', '栄西', 'えいさい'),
  (530, '歴史', '第2章 中世の日本', '2. 武士・民衆の生活と鎌倉時代の文化', 184, 1, FALSE, '182の一派で，厳しい修行を重んじ，永平寺を座禅の道場とした曹洞宗を開いた僧はだれか。', '', '道元', 'どうげん'),
  (531, '歴史', '第2章 中世の日本', '2. 武士・民衆の生活と鎌倉時代の文化', 185, 2, TRUE, '荘園を荘園領主と地頭で二分し，互いに干渉しないようにしたことを何というか。', '', '下地中分', 'したじちゅうぶん'),
  (532, '歴史', '第2章 中世の日本', '2. 武士・民衆の生活と鎌倉時代の文化', 186, 2, FALSE, '西日本を中心に，稲作の後に裏作として麦を栽培する ( ) が行われるようになった。', '', '二毛作', 'にもうさく'),
  (533, '歴史', '第2章 中世の日本', '2. 武士・民衆の生活と鎌倉時代の文化', 187, 2, FALSE, '平安時代末期の混乱した世のありさまを書き，人生の無常を説いた鴨長明の随筆を何というか。', '冒頭の「ゆく河の流れは絶えずして」が有名', '方丈記', 'ほうじょうき'),
  (534, '歴史', '第2章 中世の日本', '2. 武士・民衆の生活と鎌倉時代の文化', 188, 2, FALSE, '( ) は，平氏の栄枯盛衰を描いた軍記物で，盲目の琵琶法師が各地で語り広めた。', '', '平家物語', 'へいけものがたり'),
  (535, '歴史', '第2章 中世の日本', '2. 武士・民衆の生活と鎌倉時代の文化', 189, 2, FALSE, '( ) は，鎌倉時代に大仏様という建築様式で再建された。', '奈良時代に創建。1180年に焼失し，1199年に再建された', '東大寺南大門', 'とうだいじなんだいもん'),
  (536, '歴史', '第2章 中世の日本', '2. 武士・民衆の生活と鎌倉時代の文化', 191, 2, FALSE, '快慶らとともに190を制作した，鎌倉時代を代表する仏師はだれか。', '', '運慶', 'うんけい'),
  (537, '歴史', '第2章 中世の日本', '2. 武士・民衆の生活と鎌倉時代の文化', 192, 2, TRUE, '鎌倉時代から室町時代にかけて流行した，藤原隆信が描いた「伝平重盛像」などのような写実的な肖像画を何というか。', '', '似絵', 'にせえ'),
  (538, '歴史', '第2章 中世の日本', '2. 武士・民衆の生活と鎌倉時代の文化', 193, 2, FALSE, '信じる信じないにかかわらず，念仏を唱えれば救われるとして，念仏や踊念仏をすすめる，一遍が開いた宗派を何というか。', '', '時宗', 'じしゅう'),
  (539, '歴史', '第2章 中世の日本', '3. 元の襲来と鎌倉幕府の滅亡', 194, 1, FALSE, '13世紀，日本に服属を要求してきた元の皇帝はだれか。', '1279年，南宋を滅ぼし，中国全土を支配した', 'フビライ=ハン', ''),
  (540, '歴史', '第2章 中世の日本', '3. 元の襲来と鎌倉幕府の滅亡', 195, 1, FALSE, '194の服属要求を拒否した，鎌倉幕府の第8代執権はだれか。', '鎌倉に円覚寺を建てた', '北条時宗', 'ほうじょうときむね'),
  (541, '歴史', '第2章 中世の日本', '3. 元の襲来と鎌倉幕府の滅亡', 196, 1, FALSE, '194が日本を征服するために，2度大軍を派遣したできごとを何というか。', '蒙古襲来ともいう', '元寇', 'げんこう'),
  (542, '歴史', '第2章 中世の日本', '3. 元の襲来と鎌倉幕府の滅亡', 198, 1, FALSE, '196のうち，1281年の2度目の襲来を ( ) という。', '元軍は暴風雨によって大被害を受け，撤退を余儀なくされた', '弘安の役', 'こうあんのえき'),
  (543, '歴史', '第2章 中世の日本', '3. 元の襲来と鎌倉幕府の滅亡', 199, 1, FALSE, '1297年，幕府が御家人救済のために出した，失った土地をただで取り戻させるための法令を何というか。', '効果はなく，かえって社会は混乱した', '徳政令(永仁の徳政令)', 'えいにんのとくせいれい'),
  (544, '歴史', '第2章 中世の日本', '3. 元の襲来と鎌倉幕府の滅亡', 200, 1, FALSE, '1333年，鎌倉幕府を倒し，政治権力を朝廷に取り戻そうとして兵を挙げた天皇はだれか。', '流された隠岐から脱出した', '後醍醐天皇', 'ごだいごてんのう'),
  (545, '歴史', '第2章 中世の日本', '3. 元の襲来と鎌倉幕府の滅亡', 201, 1, FALSE, '200のよびかけに応じ、六波羅探題を滅ぼした( )は、のちに武家政治の復活をよびかけ、京都に幕府を開いた。', '', '足利尊氏', 'あしかがたかうじ'),
  (546, '歴史', '第2章 中世の日本', '3. 元の襲来と鎌倉幕府の滅亡', 202, 2, FALSE, '13世紀中ごろにアジアからヨーロッパにまたがる大帝国となった、モンゴル民族の国家を何というか。', '', 'モンゴル帝国', 'ていこく'),
  (547, '歴史', '第2章 中世の日本', '3. 元の襲来と鎌倉幕府の滅亡', 203, 2, FALSE, '( )は全モンゴルの部族を統一し、202の初代皇帝となり、大帝国を築いた。', '幼名はテムジンという', 'チンギス=ハン', ''),
  (548, '歴史', '第2章 中世の日本', '3. 元の襲来と鎌倉幕府の滅亡', 204, 2, FALSE, '202が都を大都(現在の北京)に移した後、中国風に定めた国の名を( )という。', '朝鮮・チベットなどを属国とした', '元', 'げん'),
  (549, '歴史', '第2章 中世の日本', '3. 元の襲来と鎌倉幕府の滅亡', 205, 2, FALSE, '194に仕え、帰国後に「世界の記述(東方見聞録)」を口述したイタリアのベネチア出身の商人はだれか。', '日本を「黄金の国ジパング」として紹介した', 'マルコ=ポーロ', ''),
  (550, '歴史', '第2章 中世の日本', '3. 元の襲来と鎌倉幕府の滅亡', 206, 2, FALSE, '204の再度の襲来に備えて、幕府が博多湾岸に築いた、約20kmにおよぶ石垣を( )という。', '', '防塁(石塁)', 'ぼうるい(せきるい)'),
  (551, '歴史', '第2章 中世の日本', '4. 南北朝の動乱と室町幕府の成立', 207, 1, FALSE, '鎌倉幕府の滅亡後、後醍醐天皇が行った天皇・公家中心の政治を何というか。', '武士の不満が募り、わずか2年半で失敗に終わった', '建武の新政', 'けんむのしんせい'),
  (552, '歴史', '第2章 中世の日本', '4. 南北朝の動乱と室町幕府の成立', 208, 1, FALSE, '武家政治の復活をよびかけた足利尊氏が挙兵の後、京都を占領して光明天皇を立てると、後醍醐天皇が吉野に朝廷を移したため、2つの朝廷が争う( )時代となった。', '吉野を南朝、京都を北朝という', '南北朝', 'なんぼくちょう'),
  (553, '歴史', '第2章 中世の日本', '4. 南北朝の動乱と室町幕府の成立', 209, 1, FALSE, '1392年に2つの朝廷の統一を実現させ、また、中国との貿易を行ったり、「花の御所」を造営するなど、幕府の全盛期を築いた第3代将軍はだれか。', '', '足利義満', 'あしかがよしみつ'),
  (554, '歴史', '第2章 中世の日本', '4. 南北朝の動乱と室町幕府の成立', 210, 1, FALSE, '足利尊氏が1338年に征夷大将軍に任じられてから、1573年まで続いた武家政権を何というか。', '織田信長によって滅ぼされた', '室町幕府', 'むろまちばくふ'),
  (555, '歴史', '第2章 中世の日本', '4. 南北朝の動乱と室町幕府の成立', 211, 1, FALSE, '1368年、朱元璋が元を滅ぼして、中国を統一して建てた漢民族の王朝を( )という。', '', '明', 'みん'),
  (556, '歴史', '第2章 中世の日本', '4. 南北朝の動乱と室町幕府の成立', 212, 1, FALSE, '朝鮮半島や中国沿岸を襲った、瀬戸内や九州地方の武士・漁民を中心とした武装集団を何というか。', '', '倭寇', 'わこう'),
  (557, '歴史', '第2章 中世の日本', '4. 南北朝の動乱と室町幕府の成立', 213, 1, FALSE, '209が始めた、日本と211との間で行われた貿易を何というか。', '日本からの輸出品は銅・硫黄・刀剣など、輸入品は銅銭・生糸・絹織物など', '日明貿易(勘合貿易)', 'にちみんぼうえき(かんごうぼうえき)'),
  (558, '歴史', '第2章 中世の日本', '4. 南北朝の動乱と室町幕府の成立', 215, 2, FALSE, '国内の支配を拡大し、一国を自分の領地とした守護は( )に成長した。', '土地を国内の地頭や武士に分け与え、家臣とした', '守護大名', 'しゅごだいみょう'),
  (559, '歴史', '第2章 中世の日本', '4. 南北朝の動乱と室町幕府の成立', 216, 2, FALSE, '210で将軍を補佐する役職を何というか。', '足利氏一族の有力215の細川氏、畠山氏、斯波氏の3氏が交代で任命された', '管領', 'かんれい'),
  (560, '歴史', '第2章 中世の日本', '4. 南北朝の動乱と室町幕府の成立', 217, 2, FALSE, '213は、日本が家臣の立場で行う( )貿易の形式がとられた。', '貢物に対し、皇帝が返礼として多くの物を与えた', '朝貢', 'ちょうこう'),
  (561, '歴史', '第2章 中世の日本', '4. 南北朝の動乱と室町幕府の成立', 218, 2, FALSE, '高麗の実権を握った李成桂が1392年、新たに朝鮮半島に建国した国を何というか。', '14世紀末から約100年間、日朝貿易が行われた', '朝鮮(朝鮮国)', 'ちょうせん(ちょうせんこく)'),
  (562, '歴史', '第2章 中世の日本', '4. 南北朝の動乱と室町幕府の成立', 219, 2, FALSE, '15世紀の初め、中山の尚氏が沖縄本島を統一して、建国した国を何というか。', '都は首里、貿易港は那覇に置かれた', '琉球王国', 'りゅうきゅうおうこく'),
  (563, '歴史', '第2章 中世の日本', '4. 南北朝の動乱と室町幕府の成立', 220, 2, FALSE, '219でさかんに行われていた、輸入した品物をそのままの形で他国に輸出する貿易形態を( )という。', '', '中継貿易', 'ちゅうけいぼうえき'),
  (564, '歴史', '第2章 中世の日本', '4. 南北朝の動乱と室町幕府の成立', 221, 2, FALSE, '15世紀の中ごろ、和人と対立し、アイヌ民族を率いて蜂起したアイヌ民族の首長はだれか。', '', 'コシャマイン', ''),
  (565, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 222, 1, FALSE, '商人などは、( )とよばれる同業者組合をつくり、寺社や公家に税を納めることで、営業の独占などの特権を手に入れた。', '', '座', 'ざ'),
  (566, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 223, 1, FALSE, '定期市で売買される商品などを、馬の背に乗せて物資を運んだ業者を( )という。', '荷車に物資を積み、牛馬に引かせた業者を車借という', '馬借', 'ばしゃく'),
  (567, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 224, 1, FALSE, '高利貸し業も兼ねた、鎌倉・室町時代の酒造業者を何というか。', '幕府に税を納めてその保護を受けた', '酒屋', 'さかや'),
  (568, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 225, 1, FALSE, '鎌倉・室町時代の質屋や金融業者は、質に入れた品物を保管する土蔵をもっていたことから( )とよばれた。', '', '土倉', 'どそう'),
  (569, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 226, 1, FALSE, '困難な状況になったとき、現状を変えるために、みんなで同じ行動をとって、領主などに要求することを( )という。', '', '一揆', 'いっき'),
  (570, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 227, 1, FALSE, '226の一種で、農民(土民)がおこすものの総称を何というか。', '借金の帳消しなどを要求した', '土一揆', 'つちいっき(どいっき)'),
  (571, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 229, 1, FALSE, '室町幕府第8代将軍( )は、後継者問題から大きな乱を引きおこした。', '京都の東山に銀閣を建てた', '足利義政', 'あしかがよしまさ'),
  (572, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 230, 1, FALSE, '将軍の後継者争いに守護大名の対立がからみ、京都を中心に11年間にわたって続いた争乱を何というか。', '', '応仁の乱', 'おうにんのらん'),
  (573, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 231, 1, FALSE, '230以降、豊臣秀吉が全国統一を完成するまで、約100年間続いた戦乱の時代を( )という。', '', '戦国時代', 'せんごくじだい'),
  (574, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 232, 1, FALSE, '守護大名に代わって領国を支配するようになった実力のある家臣や地侍を( )という。', '北条早雲・毛利元就・斎藤道三など', '戦国大名', 'せんごくだいみょう'),
  (575, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 233, 1, FALSE, '230のころから広まった、身分が下の者が、実力で上の者を倒して、とって代わる風潮を( )という。', '', '下剋上', 'げこくじょう'),
  (576, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 234, 1, FALSE, '232が自分の領国を支配するために、家臣や領民に対して独自に定めた法令を何というか。', '今川氏の「今川仮名目録」など', '分国法(家法)', 'ぶんこくほう(かほう)'),
  (577, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 235, 2, FALSE, '鎌倉時代に、港湾や都市で荷物の積み替えや保管、輸送を行った業者を何というか。', '', '問(問丸)', 'とい(といまる)'),
  (578, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 237, 2, FALSE, '有力農民を中心とした自治組織を( )といい、用水や入会地の使い方などを話し合って、村を運営していた。', '', '惣(惣村)', 'そう(そうそん)'),
  (579, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 238, 2, FALSE, '237の運営に関する話し合いの場を( )といい、村の掟や祭り、農耕行事などについて話し合われた。', '', '寄合', 'よりあい'),
  (580, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 239, 2, FALSE, '230によってとだえていた祇園祭を復活させた、京都の有力商人が結成した自治組織を何というか。', '', '町衆', 'ちょうしゅう(まちしゅう)'),
  (581, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 240, 2, FALSE, '勘合貿易や朝鮮・琉球との貿易で栄えた港町で、戦乱から町を守るために周りを濠で囲み、兵を雇って、自治を行ったが、織田信長に屈服した都市はどこか。', '自治を行った豪商を会合衆という', '堺', 'さかい'),
  (582, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 241, 2, FALSE, '230での東軍の中心人物である( )は、将軍のあと継ぎとして、当初は将軍の弟である足利義視を支援した。', '', '細川勝元', 'ほそかわかつもと'),
  (583, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 242, 2, FALSE, '230での西軍の中心人物である( )は、将軍のあと継ぎとして、当初は将軍の子である足利義尚を支援した。', '', '山名持豊(山名宗全)', 'やまなもちとよ(やまなそうぜん)'),
  (584, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 243, 2, FALSE, '1485年、国人と農民らが、守護畠山氏の退去を求めてこれを実現し、以後8年間にわたって自治を行った226を何というか。', '', '山城国一揆', 'やましろのくにいっき'),
  (585, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 244, 2, FALSE, '浄土真宗信徒である農民・国人・僧侶らが、各地でおこした226を何というか。', '近畿・北陸・東海の各地で226をおこした', '一向一揆', 'いっこういっき'),
  (586, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 245, 2, FALSE, '244の一つで、1488年に守護の富樫氏を倒し、以後、約100年間の自治を行った226を何というか。', '', '加賀の一向一揆', 'かがのいっこういっき'),
  (587, '歴史', '第2章 中世の日本', '5. 民衆の成長と戦国大名', 246, 2, FALSE, '232が、城を中心に家臣団や商工業者を移住させて形成された町を何というか。', '領国の政治・経済・文化の中心として発展した', '城下町', 'じょうかまち'),
  (588, '歴史', '第2章 中世の日本', '6. 室町時代の文化', 247, 1, FALSE, '足利義満が北山の山荘内に造営した3層の建物を( )といい、3層それぞれに建築様式が異なる。', '義満の死後、鹿苑寺となった', '金閣', 'きんかく'),
  (589, '歴史', '第2章 中世の日本', '6. 室町時代の文化', 249, 1, FALSE, '足利義満の保護を受けて、父である観阿弥とともに248を大成したのはだれか。', '芸術論集である「風姿花伝(花伝書)」を著した', '世阿弥', 'ぜあみ'),
  (590, '歴史', '第2章 中世の日本', '6. 室町時代の文化', 250, 1, FALSE, '( )は、248の合間に演じられた滑稽な演劇で、庶民の生活から題材をとり、俗語を使うことで、人々に喜ばれた。', '', '狂言', 'きょうげん'),
  (591, '歴史', '第2章 中世の日本', '6. 室町時代の文化', 251, 1, FALSE, '足利義政が東山の山荘に仏殿として造営した2層の建物を何というか。', '義政の死後，慈照寺となった', '銀閣', 'ぎんかく'),
  (592, '歴史', '第2章 中世の日本', '6. 室町時代の文化', 254, 1, FALSE, '明に渡って253を学び，日本的な様式を大成した人物はだれか。', '禅宗の僧で，大内氏の保護を受けた', '雪舟', 'せっしゅう'),
  (593, '歴史', '第2章 中世の日本', '6. 室町時代の文化', 255, 1, FALSE, '絵入りのやさしい文章で書かれ，のちのおとぎ話のもとになった物語を何というか。', '「一寸法師」「浦島太郎」など', '御伽草子', 'おとぎぞうし'),
  (594, '歴史', '第2章 中世の日本', '6. 室町時代の文化', 256, 2, FALSE, '鎌倉幕府の成立以降，朝廷や貴族を指して「( )」というようになった。', 'これに対して，武士は「武家」という', '公家', 'くげ'),
  (595, '歴史', '第2章 中世の日本', '6. 室町時代の文化', 257, 2, FALSE, '14世紀末～15世紀初めの足利義満のときの文化を，義満が山荘を造営した場所から( )文化という。', '臨済宗の僧による五山文学が発達した', '北山', 'きたやま'),
  (596, '歴史', '第2章 中世の日本', '6. 室町時代の文化', 258, 2, FALSE, '15世紀後半の足利義政のときの文化を，義政が山荘を造営した場所から( )文化という。', '簡素で気品ある文化', '東山', 'ひがしやま'),
  (597, '歴史', '第2章 中世の日本', '6. 室町時代の文化', 259, 2, FALSE, '251と同じ敷地内にある，足利義政の書斎であった( )は，252の典型的な例とされる。', '', '東求堂同仁斎', 'とうぐどうどうじんさい'),
  (598, '歴史', '第2章 中世の日本', '6. 室町時代の文化', 260, 2, FALSE, '室町時代のころにおこった日本の庭園形式の一つで，石と砂で自然を表現した庭園を漢字3字で何というか。', '龍安寺の石庭などが有名', '枯山水', 'かれさんすい'),
  (599, '歴史', '第2章 中世の日本', '6. 室町時代の文化', 261, 2, FALSE, '川沿いの河原で生活し，庭園造りや手工業の分野で優れた能力を発揮した中世の賤民を何というか。', '', '河原者', 'かわらもの'),
  (600, '歴史', '第2章 中世の日本', '6. 室町時代の文化', 262, 2, FALSE, '数人の者が，和歌の上の句と下の句を次々に重ねて合作する( )は，庶民の間に流行し，宗祇が大成した。', '', '連歌', 'れんが'),
  (601, '歴史', '第2章 中世の日本', '6. 室町時代の文化', 263, 2, TRUE, '上杉憲実によって再興され，宣教師のフランシスコ=ザビエルが「坂東の大学」と紹介した学校を何というか。', '', '足利学校', 'あしかががっこう'),
  (602, '歴史', '第3章 近世の日本', '1. ヨーロッパとイスラム世界', 264, 1, FALSE, 'キリスト教の宗派のなかでローマ教皇を最高の権威とする教会を何というか。', '中世ヨーロッパの政治・社会・文化に大きな影響力をもった', 'カトリック教会', ''),
  (603, '歴史', '第3章 近世の日本', '1. ヨーロッパとイスラム世界', 265, 1, FALSE, 'イスラム教勢力によって奪われた聖地を取り戻すために，ローマ教皇が国王や諸侯によびかけて派遣した軍を何というか。', '', '十字軍', 'じゅうじぐん'),
  (604, '歴史', '第3章 近世の日本', '1. ヨーロッパとイスラム世界', 266, 1, FALSE, '14世紀から16世紀にかけて，ヨーロッパ各地に広まった人文主義に基づく文化運動を( )(文芸復興)という。', '', 'ルネサンス', ''),
  (605, '歴史', '第3章 近世の日本', '1. ヨーロッパとイスラム世界', 267, 1, FALSE, 'ドイツで宗教改革を始めた( )は，ローマ教皇の免罪符の販売を批判し，信仰のよりどころは聖書であると唱えた。', '', 'ルター', ''),
  (606, '歴史', '第3章 近世の日本', '1. ヨーロッパとイスラム世界', 268, 1, FALSE, '宗教改革に対抗し，264内部で生まれた，厳格な規律のもとに，海外布教に力を入れた組織を何というか。', '', 'イエズス会', ''),
  (607, '歴史', '第3章 近世の日本', '1. ヨーロッパとイスラム世界', 269, 1, FALSE, '1543年に，種子島に漂着したポルトガル人によって，日本に伝えられたものは何か。', '当時の築城法や戦法に大きな変化をもたらした', '鉄砲', 'てっぽう'),
  (608, '歴史', '第3章 近世の日本', '1. ヨーロッパとイスラム世界', 270, 1, FALSE, '1549年，キリスト教の布教のために来日し，鹿児島に上陸した268の宣教師はだれか。', '', 'フランシスコ=ザビエル', ''),
  (609, '歴史', '第3章 近世の日本', '1. ヨーロッパとイスラム世界', 271, 2, FALSE, 'ローマ教皇が265の派遣をよびかけて奪い返そうとした聖地は( )である。', 'ヨルダン川西岸に位置する，キリスト教・イスラム教・ユダヤ教の聖地', 'エルサレム', ''),
  (610, '歴史', '第3章 近世の日本', '1. ヨーロッパとイスラム世界', 272, 2, FALSE, 'スイスのジュネーブを中心に宗教改革を進め，勤勉で富をつくることは神の心にかなう，としたのはだれか。', '', 'カルバン', ''),
  (611, '歴史', '第3章 近世の日本', '1. ヨーロッパとイスラム世界', 274, 2, FALSE, '( )は，ポルトガル国王の命によってアフリカ西岸を南下し，喜望峰を経て，アフリカ東岸を北上し，インド洋を横断する航路を開拓した。', '', 'バスコ=ダ=ガマ', ''),
  (612, '歴史', '第3章 近世の日本', '1. ヨーロッパとイスラム世界', 275, 2, FALSE, 'スペイン国王の援助を得て，世界一周に成功したのは( )の船隊である。', '275は途中，フィリピンで先住民に殺された', 'マゼラン', ''),
  (613, '歴史', '第3章 近世の日本', '1. ヨーロッパとイスラム世界', 276, 2, FALSE, 'キリスト教の信者となった大名のことを( )という。', '貿易による利益を求めて信者となる大名もいた。大友義鎮(大友宗麟)・有馬晴信・大村純忠・高山右近など', 'キリシタン大名', ''),
  (614, '歴史', '第3章 近世の日本', '1. ヨーロッパとイスラム世界', 277, 2, FALSE, '1582年，九州の276がローマに派遣した使節を何というか。', '彼らが帰国したときには，日本ではキリスト教の布教は禁止されていた', '天正遣欧(少年)使節', 'てんしょうけんおう'),
  (615, '歴史', '第3章 近世の日本', '1. ヨーロッパとイスラム世界', 278, 2, FALSE, '16世紀にポルトガル・スペイン船が来航し，平戸や長崎で行われた貿易を何というか。', '', '南蛮貿易', 'なんばんぼうえき'),
  (616, '歴史', '第3章 近世の日本', '2. 織田信長の統一事業', 279, 1, FALSE, '室町幕府が滅んだ1573年から，江戸幕府が開かれた1603年までの約30年間を( )という。', '2つの城の所在地名から名づけられた', '安土桃山時代', 'あづちももやまじだい'),
  (617, '歴史', '第3章 近世の日本', '2. 織田信長の統一事業', 280, 1, FALSE, '尾張の戦国大名で，天下統一をめざして京都に上り，1573年に室町幕府を滅ぼしたが，1582年に家臣に背かれて自害したのはだれか。', '', '織田信長', 'おだのぶなが'),
  (618, '歴史', '第3章 近世の日本', '2. 織田信長の統一事業', 281, 1, FALSE, '1560年，駿河・遠江・三河を支配した戦国大名が大軍を率いて京都へ上ろうとするのを280が破った戦乱を何というか。', '', '桶狭間の戦い', 'おけはざま'),
  (619, '歴史', '第3章 近世の日本', '2. 織田信長の統一事業', 283, 1, FALSE, '280が築いた，日本初の本格的な天守をもつ，5層7階の城を何というか。', '琵琶湖のほとりに築かれた', '安土城', 'あづちじょう'),
  (620, '歴史', '第3章 近世の日本', '2. 織田信長の統一事業', 284, 1, FALSE, '283の城下町において，280が行った，商業振興のために商人の特権を廃止し，自由な商業活動ができるようにした政策を何というか。', '', '楽市・楽座', 'らくいち らくざ'),
  (621, '歴史', '第3章 近世の日本', '2. 織田信長の統一事業', 285, 2, FALSE, '281で敗れて，殺された戦国大名はだれか。', '徳川家康は幼いとき，285の人質になっていた', '今川義元', 'いまがわよしもと'),
  (622, '歴史', '第3章 近世の日本', '2. 織田信長の統一事業', 286, 2, FALSE, '280に擁立されて将軍となったが，その後，280と対立したために，京都から追放された室町幕府最後の将軍はだれか。', '', '足利義昭', 'あしかがよしあき'),
  (623, '歴史', '第3章 近世の日本', '2. 織田信長の統一事業', 287, 2, FALSE, '応仁の乱のころから現れた，馬に乗らず徒歩で戦う雑兵を何というか。', '戦国時代になると，戦闘の中心となって活躍した', '足軽', 'あしがる'),
  (624, '歴史', '第3章 近世の日本', '2. 織田信長の統一事業', 288, 2, FALSE, '1582年，京都に滞在していた280が家臣に背かれて，自害したできごとを何というか。', '', '本能寺の変', 'ほんのうじ'),
  (625, '歴史', '第3章 近世の日本', '2. 織田信長の統一事業', 289, 2, FALSE, '毛利攻めの援軍の途中で反乱を決意し，主君の280を自害に追い込む288をおこしたが，直後の山崎の戦いで敗れた武将はだれか。', '', '明智光秀', 'あけちみつひで'),
  (626, '歴史', '第3章 近世の日本', '3. 豊臣秀吉の統一事業と対外政策', 290, 1, FALSE, '織田信長の後継者として天下統一事業を進め，1590年に全国を統一したのはだれか。', '', '豊臣秀吉', 'とよとみひでよし'),
  (627, '歴史', '第3章 近世の日本', '3. 豊臣秀吉の統一事業と対外政策', 291, 1, FALSE, '290が，石山本願寺の跡地に築いた( )は，天下統一の拠点となったが，1615年に落城し，のち徳川氏が再建した。', '', '大阪城', 'おおさかじょう'),
  (628, '歴史', '第3章 近世の日本', '3. 豊臣秀吉の統一事業と対外政策', 292, 1, FALSE, '290が全国の田畑の面積や等級，収穫高，土地の耕作者を調べるために，役人を派遣して行った土地調査事業を( )という。', '', '太閤検地', 'たいこうけんち'),
  (629, '歴史', '第3章 近世の日本', '3. 豊臣秀吉の統一事業と対外政策', 293, 1, FALSE, '290は一揆を防ぎ，百姓を田畑の耕作に専念させるために，百姓から武器を取り上げる( )を行った。', '', '刀狩', 'かたながり'),
  (630, '歴史', '第3章 近世の日本', '3. 豊臣秀吉の統一事業と対外政策', 294, 1, FALSE, '292や293によって，武士と農民の区別をはっきりさせる( )が進み，身分制度の基礎ができた。', '', '兵農分離', 'へいのうぶんり'),
  (631, '歴史', '第3章 近世の日本', '3. 豊臣秀吉の統一事業と対外政策', 295, 2, FALSE, '292では，ものさし・ますが統一され，田畑の等級と面積から予想される生産高を( )で表し，記録された。', '', '石高', 'こくだか'),
  (632, '歴史', '第3章 近世の日本', '3. 豊臣秀吉の統一事業と対外政策', 296, 2, FALSE, '1587年，長崎が教会領として寄付されたことを知った290が宣教師の国外退去を命じた法令を何というか。', '外国船の来航は奨励した', 'バテレン追放令', ''),
  (633, '歴史', '第3章 近世の日本', '3. 豊臣秀吉の統一事業と対外政策', 297, 2, FALSE, '290が行った1回目の朝鮮侵略を( )といい，朝鮮北部まで兵を進めたが，朝鮮水軍や民衆の抵抗で苦戦し，1593年に休戦した。', '', '文禄の役', 'ぶんろく えき'),
  (634, '歴史', '第3章 近世の日本', '3. 豊臣秀吉の統一事業と対外政策', 298, 2, FALSE, '290が行った2回目の朝鮮侵略を( )というが，日本軍は苦戦が続き，290の病死によって撤退した。', '', '慶長の役', 'けいちょう えき'),
  (635, '歴史', '第3章 近世の日本', '3. 豊臣秀吉の統一事業と対外政策', 299, 2, FALSE, '290の朝鮮侵略のとき，水軍を率いて戦った朝鮮の武将はだれか。', '各地で日本軍を破ったが，戦死した', '李舜臣', 'りしゅんしん'),
  (636, '歴史', '第3章 近世の日本', '3. 豊臣秀吉の統一事業と対外政策', 300, 2, FALSE, '290の朝鮮侵略の際，朝鮮から連行された陶工の李参平が始めた焼き物を何というか。', '', '有田焼(伊万里焼)', 'ありたやき いまりやき'),
  (637, '歴史', '第3章 近世の日本', '4. 桃山文化', 301, 1, FALSE, '織田信長・豊臣秀吉の時代を中心とする, 豪壮・華麗で, 仏教の影響が薄く, 南蛮文化の影響も受けた文化を何というか。', '', '桃山文化', 'ももやまぶんか'),
  (638, '歴史', '第3章 近世の日本', '4. 桃山文化', 302, 1, FALSE, '堺の豪商出身で, 織田信長・豊臣秀吉に仕え, 簡素で深みのあるわび茶を大成したのはだれか。', '', '千利休', 'せんのりきゅう'),
  (639, '歴史', '第3章 近世の日本', '4. 桃山文化', 303, 1, FALSE, 'ポルトガル人・スペイン人との貿易やキリスト教の伝来によって日本に伝えられたヨーロッパの文化を何というか。', '', '南蛮文化', 'なんばんぶんか'),
  (640, '歴史', '第3章 近世の日本', '4. 桃山文化', 304, 2, FALSE, '兵庫県に位置する( )は, 現存する天守をもった城郭建築で, 白鷺城ともよばれる。', '世界文化遺産に登録されている', '姫路城', 'ひめじじょう'),
  (641, '歴史', '第3章 近世の日本', '4. 桃山文化', 306, 2, FALSE, '楽器を伴奏し, 物語に節をつけて語る芸能を( )といい, 江戸時代の直前のころから, 三味線を伴奏に取り入れることが定着した。', '', '浄瑠璃', 'じょうるり'),
  (642, '歴史', '第3章 近世の日本', '4. 桃山文化', 307, 2, FALSE, '出雲の阿国が京都の北野神社や四条河原で始めた芸能を何というか。', 'のちに歌舞伎に発展した', 'かぶき踊り', ''),
  (643, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 308, 1, FALSE, '豊臣秀吉の死後におこった, 全国支配の実権をめぐって行われた, 東軍と西軍による戦いを何というか。', '「天下分け目の戦い」といわれる', '関ヶ原の戦い', 'せきがはらのたたかい'),
  (644, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 309, 1, FALSE, '( )は三河の小大名であったが, 織田信長と同盟を結び, 勢力をのばした。豊臣秀吉によって領地を関東に移され, そこに幕府を開いた。', '', '徳川家康', 'とくがわいえやす'),
  (645, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 310, 1, FALSE, '1603年に309が征夷大将軍に任じられたことで, 江戸に開かれた武家政権を( )という。', '幕府が倒れる1867年まで260年余り続いた', '江戸幕府', 'えどばくふ'),
  (646, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 311, 1, FALSE, '徳川氏一族の大名を何というか。', 'この大名の中でも309の子から出たものを御三家といった', '親藩', 'しんぱん'),
  (647, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 312, 1, FALSE, '308以前から徳川氏の家臣であった大名を何というか。', '幕府の重職に就き, 重要地に配置された', '譜代大名', 'ふだいだいみょう'),
  (648, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 313, 1, FALSE, '308のころから徳川氏に従うようになった大名を何というか。', '江戸から遠い地に配置され, 幕府の要職には就くことはできなかった', '外様大名', 'とざまだいみょう'),
  (649, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 314, 1, FALSE, '1615年に初めて出された, 大名を統制するための法を( )という。', '違反した大名は厳しい処分を受けた', '武家諸法度', 'ぶけしょはっと'),
  (650, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 315, 1, FALSE, '第3代将軍の( )は314を改定し, 鎖国を完成させるなど, 幕府の体制を確立した。', '', '徳川家光', 'とくがわいえみつ'),
  (651, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 316, 1, FALSE, '1635年, 314に, 大名の妻子を江戸に住まわせ, 大名が一年おきに江戸と領国を往復する( )が追加された。', '', '参勤交代', 'さんきんこうたい'),
  (652, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 317, 1, FALSE, '年貢を確実に徴収し, 犯罪を防止するために, 本百姓5〜6戸を1組として, 連帯責任を負わせる制度を何というか。', '', '五人組', 'ごにんぐみ'),
  (653, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 318, 1, FALSE, '海外渡航の許可状を所持した日本の船が, 東南アジアに渡航して行った貿易を何というか。', '', '朱印船貿易', 'しゅいんせんぼうえき'),
  (654, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 319, 1, FALSE, '318によって, 東南アジアのルソン(フィリピン)・安南(ベトナム)・シャム(タイ)などに移住した日本人が各地に( )をつくった。', '', '日本町', 'にほんまち'),
  (655, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 320, 1, FALSE, '1637年, 厳しい年貢の取り立てと, キリスト教弾圧に苦しんだ人々が( )をおこした。', '大将は天草四郎(益田時貞)', '島原・天草一揆', 'しまばら・あまくさいっき'),
  (656, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 322, 1, FALSE, '禁教・貿易の統制・外交の独占を目的に, 日本人の海外渡航を禁止し, 外国船の来航を制限する幕府の外交政策を何というか。', '', '鎖国', 'さこく'),
  (657, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 323, 1, FALSE, '1641年, 幕府はオランダ商館を長崎につくった人工島の( )に移した。', '役人や特定の商人以外は立ち入りが禁止された', '出島', 'でじま'),
  (658, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 324, 1, FALSE, '将軍の代わりごとに来日するようになった朝鮮からの使節を何というか。', '秀吉の朝鮮侵略後とだえていた国交が回復', '朝鮮通信使', 'ちょうせんつうしんし'),
  (659, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 325, 1, FALSE, '北海道のことを, 江戸時代には( )とよんだ。', '室町時代に, 渡島半島に和人(日本人)が進出した', '蝦夷地', 'えぞち'),
  (660, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 326, 1, FALSE, '17世紀のごろ, 325の先住民族の首長である( )は325の南部を支配する藩の不当な交易に対して戦いをおこしたが, 敗れた。', '', 'シャクシャイン', ''),
  (661, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 327, 2, FALSE, '豊臣秀吉の家臣で, 308で西軍の中心として挙兵したが敗れ, 処刑されたのはだれか。', '秀吉の死後, 309と対立した', '石田三成', 'いしだみつなり'),
  (662, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 328, 2, FALSE, '徳川氏が豊臣氏を滅ぼした戦いを( )といい, 豊臣秀頼を冬の陣・夏の陣と2度にわたって攻め, 1615年に自害に追い込んだ。', '', '大坂の陣', 'おおさかのじん'),
  (663, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 329, 2, FALSE, '幕府から1万石以上の領地を与えられた家臣を何というか。', '江戸時代中期以降は約260〜270家ほど329があった', '大名', 'だいみょう'),
  (664, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 330, 2, FALSE, '312の中から4〜5名選ばれる, 将軍を補佐する常置の最高職を何というか。', '月ごとに交代で政治を統轄した', '老中', 'ろうじゅう'),
  (665, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 331, 2, FALSE, '将軍にお目見えが許された, 石高が1万石未満の将軍直属の家臣を何というか。', '御家人は331より下位の家臣で, 将軍にお目見えができなかった', '旗本', 'はたもと'),
  (666, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 332, 2, FALSE, '将軍が海外に渡航する船に対して発行した海外渡航の許可状を何というか。', '309はこれを積極的に発行した', '朱印状', 'しゅいんじょう'),
  (667, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 333, 2, FALSE, '長崎県の北部の島に位置する( )にはポルトガル船が来航し, 17世紀初期には, オランダやイギリスが商館を建設して栄えた。', 'オランダ商館が長崎の323に移されるまで, 南蛮貿易の開港場', '平戸', 'ひらど'),
  (668, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 334, 2, FALSE, 'キリスト教の禁教を徹底させるために310が行った, 民衆の信仰する宗教を調査する制度を何というか。', '', '宗門改', 'しゅうもんあらため'),
  (669, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 335, 2, FALSE, 'オランダ商館長が提出した, 海外情報を記した報告書を何というか。', '長崎奉行を通じて幕府に提出された', 'オランダ風説書', 'ふうせつがき'),
  (670, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 336, 2, FALSE, '324の実現の仲立ちを行ったり, 朝鮮の釜山に出先機関である倭館を設け, 藩士が常駐して貿易を独占した藩はどこか。', '', '対馬藩', 'つしまはん'),
  (671, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 337, 2, FALSE, '薩摩藩の監督のもとに, 将軍や琉球国王の代わりごとに江戸に送られた使節を何というか。', '', '琉球使節', 'りゅうきゅうしせつ'),
  (672, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 338, 2, FALSE, '独自の文化をもち, 狩猟と漁労を中心とした生活を行っていた, 325の先住民族を( )という。', '', 'アイヌ民族', ''),
  (673, '歴史', '第3章 近世の日本', '5. 江戸幕府の成立と鎖国', 339, 2, FALSE, '幕府の許可によって338との交易を独占して利益を得ていた, 渡島半島に置かれていた藩を何というか。', '', '松前藩', 'まつまえはん'),
  (674, '歴史', '第3章 近世の日本', '6. 産業・交通の発達と都市の繁栄', 340, 1, FALSE, '幕府や諸藩は年貢の増収を図るために, 新たに農地を広げる( )を積極的に進めた。', '', '新田開発', 'しんでんかいはつ'),
  (675, '歴史', '第3章 近世の日本', '6. 産業・交通の発達と都市の繁栄', 342, 1, FALSE, '稲刈り後の脱穀を行うときに, 一気に稲穂から米粒を外すことができる( )が開発された。', 'ほかに, 千石どおし・唐箕などの農具が開発された', '千歯こき', 'せんばこき'),
  (676, '歴史', '第3章 近世の日本', '6. 産業・交通の発達と都市の繁栄', 343, 1, FALSE, '商品として売ることを目的に栽培される農作物のことを何というか。', '綿・麻・菜種・藍・紅花など', '商品作物', 'しょうひんさくもつ'),
  (677, '歴史', '第3章 近世の日本', '6. 産業・交通の発達と都市の繁栄', 344, 1, FALSE, '五街道とは, 江戸と京都を結ぶ( )のほかに, 中山道・日光道中・奥州道中・甲州道中がある。', '参勤交代のために整備が進んだ', '東海道', 'とうかいどう'),
  (678, '歴史', '第3章 近世の日本', '6. 産業・交通の発達と都市の繁栄', 345, 1, FALSE, '治安を維持するため, 交通の要所に設けられ, 通行するには手形を必要とした施設を何というか。', '344の箱根や中山道の碓氷峠などに設置された', '関所', 'せきしょ'),
  (679, '歴史', '第3章 近世の日本', '6. 産業・交通の発達と都市の繁栄', 346, 1, FALSE, '江戸時代に栄えた, 江戸・大坂・京都を総称して三都といい, 江戸は「将軍のお膝もと」, 大坂は「( )」とよばれ, 京都では西陣織などがつくられた。', '', '天下の台所', 'てんかのだいどころ'),
  (680, '歴史', '第3章 近世の日本', '6. 産業・交通の発達と都市の繁栄', 347, 1, FALSE, '諸藩は年貢米や特産物を保管し, 販売するために, 大坂などに( )とよばれる建物を置いた。', '江戸・大津・長崎などにも置かれた', '蔵屋敷', 'くらやしき'),
  (681, '歴史', '第3章 近世の日本', '6. 産業・交通の発達と都市の繁栄', 348, 1, FALSE, '幕府や藩に税を納め, 許可を得て営業を独占した, 商工業者による同業者組合を( )という。', '', '株仲間', 'かぶなかま'),
  (682, '歴史', '第3章 近世の日本', '6. 産業・交通の発達と都市の繁栄', 349, 2, FALSE, '江戸〜大阪間を結ぶ航路を, 木綿や菜種油は( )が, 酒は樽廻船が定期的に運航した。', '樽廻船の方が小型で速度が速かった', '菱垣廻船', 'ひがきかいせん'),
  (683, '歴史', '第3章 近世の日本', '6. 産業・交通の発達と都市の繁栄', 350, 2, FALSE, '17世紀後半に河村瑞賢によって開かれた東北・北陸の米を大阪に運ぶ航路を何というか。', '江戸に運ぶ航路を東廻り航路という', '西廻り航路', 'にしまわりこうろ'),
  (684, '歴史', '第3章 近世の日本', '7. 元禄文化と学問', 354, 1, FALSE, '17世紀の終わり〜18世紀初めにかけて栄えた、上方の人を中心とする明るく活気のある文化を何というか。', '', '元禄文化', 'げんろくぶんか'),
  (685, '歴史', '第3章 近世の日本', '7. 元禄文化と学問', 355, 1, FALSE, '自分の内面を表現し、俳諧を芸術として大成した（　）は「奥の細道」を著した。', '', '松尾芭蕉', 'まつおばしょう'),
  (686, '歴史', '第3章 近世の日本', '7. 元禄文化と学問', 356, 1, FALSE, '大坂の町人出身で、「好色一代男」「世間胸算用」「日本永代蔵」などを著したのはだれか。', '', '井原西鶴', 'いはらさいかく'),
  (687, '歴史', '第3章 近世の日本', '7. 元禄文化と学問', 357, 1, FALSE, '義理と人情の葛藤を描いた「曽根崎心中」などの作品を著した脚本家の（　）が人気を集めた。', '', '近松門左衛門', 'ちかまつもんざえもん'),
  (688, '歴史', '第3章 近世の日本', '7. 元禄文化と学問', 358, 1, FALSE, '出雲の阿国が始めた芸能が発達し、庶民の間で人気を集めた演劇は何か。', '市川団十郎などの名優が現れた', '歌舞伎', 'かぶき'),
  (689, '歴史', '第3章 近世の日本', '7. 元禄文化と学問', 359, 1, FALSE, '庶民の風俗を描いた絵画を（　）といい、庶民の娯楽の一つとなった。', '', '浮世絵', 'うきよえ'),
  (690, '歴史', '第3章 近世の日本', '7. 元禄文化と学問', 361, 2, FALSE, '354の時代から始まった、町人の享楽的な生活や心情をありのままに描いた小説を（　）という。', '「好色一代男」から始まる', '浮世草子', 'うきよぞうし'),
  (691, '歴史', '第3章 近世の日本', '7. 元禄文化と学問', 362, 2, FALSE, '三味線を伴奏し、物語を語るのに合わせて人形を操る、民衆の人気を集めた舞台芸能を何というか。', '現在では文楽という', '人形浄瑠璃', 'にんぎょうじょうるり'),
  (692, '歴史', '第3章 近世の日本', '7. 元禄文化と学問', 363, 2, FALSE, '「風神雷神図屏風」など華やかな色彩と大胆な構図の装飾画を描いた画家はだれか。', '京都の富裕な町衆の出身', '俵屋宗達', 'たわらやそうたつ'),
  (693, '歴史', '第3章 近世の日本', '7. 元禄文化と学問', 364, 2, FALSE, '京都の商人出身で、「燕子花図屏風」のような絵画、「八橋蒔絵螺鈿硯箱」のような工芸品を生み出したのはだれか。', '', '尾形光琳', 'おがたこうりん'),
  (694, '歴史', '第3章 近世の日本', '7. 元禄文化と学問', 365, 2, FALSE, '君臣・長幼などの別をわきまえ、上下の秩序を重視するところが封建社会に合っていたため、幕府の御用学問となった儒学の一派は何か。', '', '朱子学', 'しゅしがく'),
  (695, '歴史', '第3章 近世の日本', '7. 元禄文化と学問', 366, 2, FALSE, '17世紀中ごろ、日本独自の数学である和算を始めた人物はだれか。', '筆算の創始、円の面積の計算など多くの功績を残した', '関孝和', 'せきたかかず'),
  (696, '歴史', '第3章 近世の日本', '8. 幕府政治の改革と社会の変化', 367, 1, FALSE, '第5代将軍（　）は儒学を奨励し、湯島に聖堂を建築し、幕府の学問所とした。', '儒学の一派である朱子学を幕府の官学とした', '徳川綱吉', 'とくがわつなよし'),
  (697, '歴史', '第3章 近世の日本', '8. 幕府政治の改革と社会の変化', 368, 1, FALSE, '第8代将軍が行った、質素・倹約をすすめる政治改革を何というか。', '江戸の三大改革の一つで1716〜45年にかけて行われた', '享保の改革', 'きょうほうのかいかく'),
  (698, '歴史', '第3章 近世の日本', '8. 幕府政治の改革と社会の変化', 369, 1, FALSE, '紀伊藩出身で、18世紀前半に368に取り組んだのはだれか。', '徳川家康の政治を理想とした', '徳川吉宗', 'とくがわよしむね'),
  (699, '歴史', '第3章 近世の日本', '8. 幕府政治の改革と社会の変化', 370, 1, FALSE, '裁判の基準を定めた法律である（　）を編集させた。', '上下二巻のうち、103条からなる下巻が現在の刑法にあたる', '公事方御定書', 'くじかたおさだめがき'),
  (700, '歴史', '第3章 近世の日本', '8. 幕府政治の改革と社会の変化', 371, 1, FALSE, '江戸時代の農民がおこした、年貢の軽減や不正を働いた代官の交代などを求める抵抗運動を何というか。', '', '百姓一揆', 'ひゃくしょういっき'),
  (701, '歴史', '第3章 近世の日本', '8. 幕府政治の改革と社会の変化', 372, 1, FALSE, '都市で、貧しい人々が豊かな商人や米問屋などを襲った暴動を何というか。', '371と同様、ききんのときに発生件数が増加した', '打ちこわし', ''),
  (702, '歴史', '第3章 近世の日本', '8. 幕府政治の改革と社会の変化', 373, 1, FALSE, '18世紀後半、株仲間の奨励や長崎貿易の拡大などの積極的な経済政策で、幕府財政を立て直そうとした老中はだれか。', '', '田沼意次', 'たぬまおきつぐ'),
  (703, '歴史', '第3章 近世の日本', '8. 幕府政治の改革と社会の変化', 374, 1, FALSE, '1787〜93年に行われた、厳しい質素・倹約による政治改革を何というか。', '厳しすぎたために、6年余りで失敗した', '寛政の改革', 'かんせいのかいかく'),
  (704, '歴史', '第3章 近世の日本', '8. 幕府政治の改革と社会の変化', 375, 1, FALSE, '374を行った（　）は、1782〜87年にかけておこったききんの際に藩内から餓死者を出さなかったことを評価され、老中となった。', '', '松平定信', 'まつだいらさだのぶ'),
  (705, '歴史', '第3章 近世の日本', '8. 幕府政治の改革と社会の変化', 376, 2, FALSE, '367が出した極端な動物愛護令を何というか。', '特に犬を殺傷することを禁じ、違反者は厳しい処罰を受けた', '生類憐みの令', 'しょうるいあわれみのれい'),
  (706, '歴史', '第3章 近世の日本', '8. 幕府政治の改革と社会の変化', 377, 2, FALSE, '367の死後、376の廃止などを行った朱子学者で、政治家はだれか。', '金銀の流出を防ぐため、長崎貿易を制限した', '新井白石', 'あらいはくせき'),
  (707, '歴史', '第3章 近世の日本', '8. 幕府政治の改革と社会の変化', 378, 2, FALSE, '369は、大名から1万石につき100石の割合で幕府に米を納めれば、参勤交代での江戸滞在期間を半年に短縮する（　）を行った。', '', '上米の制', 'あげまいのせい'),
  (708, '歴史', '第3章 近世の日本', '8. 幕府政治の改革と社会の変化', 379, 2, FALSE, '369は、庶民の意見を政治に反映させるために（　）を設置した。', '町火消の創設・小石川養生所の設置などが実現した', '目安箱', 'めやすばこ'),
  (709, '歴史', '第3章 近世の日本', '8. 幕府政治の改革と社会の変化', 380, 2, FALSE, '19世紀になると、大商人が自分で工場を建て、職人を集めて分業や協業によって商品を生産させる（　）が出現した。', '', '工場制手工業（マニュファクチュア）', 'こうじょうせいしゅこうぎょう'),
  (710, '歴史', '第3章 近世の日本', '8. 幕府政治の改革と社会の変化', 381, 2, FALSE, '長雨・冷夏・浅間山の噴火などを原因に、1782〜87年にかけておこったききんを何というか。', '江戸時代の三大ききんの一つ', '天明のききん', 'てんめいのききん'),
  (711, '歴史', '第3章 近世の日本', '9. 新しい学問と化政文化', 382, 1, FALSE, '「万葉集」や「古事記」などの日本の古典を研究し、日本古来の考え方を明らかにしようとする学問を何というか。', '幕末の尊王攘夷運動に影響を与えた', '国学', 'こくがく'),
  (712, '歴史', '第3章 近世の日本', '9. 新しい学問と化政文化', 383, 1, FALSE, '「古事記」の注釈書「古事記伝」を著し、382を大成した伊勢松阪出身の医者であり学者はだれか。', '', '本居宣長', 'もとおりのりなが'),
  (713, '歴史', '第3章 近世の日本', '9. 新しい学問と化政文化', 384, 1, FALSE, 'オランダ語を通じて西洋の学術や文化を学ぶ学問を何というか。', '徳川吉宗がキリスト教に関係のない漢訳洋書の輸入を認めたことにより発展した', '蘭学', 'らんがく'),
  (714, '歴史', '第3章 近世の日本', '9. 新しい学問と化政文化', 385, 1, FALSE, '前野良沢らは、オランダ語で書かれたドイツの医学書「ターヘル＝アナトミア」を翻訳し、（　）と名づけて出版した。', '', '解体新書', 'かいたいしんしょ'),
  (715, '歴史', '第3章 近世の日本', '9. 新しい学問と化政文化', 386, 1, FALSE, '「ターヘル＝アナトミア」を翻訳し、385として出版したのは（　）と前野良沢である。', '翻訳時の苦労を「蘭学事始」で述べている', '杉田玄白', 'すぎたげんぱく'),
  (716, '歴史', '第3章 近世の日本', '9. 新しい学問と化政文化', 387, 1, FALSE, '50歳で隠居後、天文学・測量術を学び、幕府の命によって全国の沿岸を測量し、正確な日本地図を作成したのはだれか。', '', '伊能忠敬', 'いのうただたか'),
  (717, '歴史', '第3章 近世の日本', '9. 新しい学問と化政文化', 388, 1, FALSE, '江戸時代、町人や農民の子どもに「読み・書き・そろばん」を教えた教育施設を何というか。', '', '寺子屋', 'てらこや'),
  (718, '歴史', '第3章 近世の日本', '9. 新しい学問と化政文化', 389, 1, FALSE, '18世紀末〜19世紀初めにかけて、江戸を中心として栄えた、皮肉や滑稽が好まれた庶民の文化を何というか。', '', '化政文化', 'かせいぶんか'),
  (719, '歴史', '第3章 近世の日本', '9. 新しい学問と化政文化', 390, 2, FALSE, '諸藩が藩士の子弟を育成するために設立した学校を何というか。', '旗本や御家人に子弟を教育するための教育機関を昌平坂学問所という', '藩校', 'はんこう'),
  (720, '歴史', '第3章 近世の日本', '9. 新しい学問と化政文化', 391, 2, FALSE, '長崎に鳴滝塾を開き、多くの日本人に西洋医学を教えたドイツ人の医師はだれか。', '帰国時に、日本地図をもち出そうとし、国外追放となった', 'シーボルト', ''),
  (721, '歴史', '第3章 近世の日本', '9. 新しい学問と化政文化', 392, 2, FALSE, '五・七・五・七・七の和歌の形を借りて、社会を皮肉るものを（　）という。', '五・七・五の俳諧の形を借りて皮肉るものを川柳という', '狂歌', 'きょうか'),
  (722, '歴史', '第3章 近世の日本', '9. 新しい学問と化政文化', 393, 2, FALSE, '浮世絵の技術が進み、多色刷りの美しい版画は（　）とよばれる。', '18世紀後半に鈴木春信が創始した', '錦絵', 'にしきえ'),
  (723, '歴史', '第3章 近世の日本', '9. 新しい学問と化政文化', 395, 2, FALSE, '（　）は、「東海道五十三次」などの風景画の浮世絵師として知られている。', '', '歌川広重', 'うたがわひろしげ'),
  (724, '歴史', '第3章 近世の日本', '10. 外国船の出現と天保の改革', 396, 1, FALSE, '1825年、幕府が出した、中国・オランダ以外の外国船を撃退することを命じた法令を何というか。', 'アヘン戦争での清の敗北で、方針を転換した', '異国船打払令', 'いこくせんうちはらいれい'),
  (725, '歴史', '第3章 近世の日本', '10. 外国船の出現と天保の改革', 397, 1, FALSE, 'もと大阪町奉行所の役人だった（　）は、天保のききんに際し、救済策をとらなかった幕府に憤り、1837年に同志とともに挙兵した。', '', '大塩平八郎', 'おおしおへいはちろう'),
  (726, '歴史', '第3章 近世の日本', '10. 外国船の出現と天保の改革', 398, 1, FALSE, '1841〜43年、江戸幕府は株仲間の解散や倹約令などの厳しい政策をとった（　）を行ったが、失敗に終わった。', '', '天保の改革', 'てんぽうのかいかく'),
  (727, '歴史', '第3章 近世の日本', '10. 外国船の出現と天保の改革', 399, 1, FALSE, '江戸の三大改革の一つである398に取り組んだが、厳しすぎる内容に反感を買い、失脚した老中はだれか。', '', '水野忠邦', 'みずのただくに'),
  (728, '歴史', '第3章 近世の日本', '10. 外国船の出現と天保の改革', 400, 2, FALSE, '1839年、モリソン号事件の幕府の対応を批判した蘭学者の渡辺華山・高野長英らが処罰される（　）がおこった。', '', '蛮社の獄', 'ばんしゃのごく'),
  (729, '歴史', '第4章 近代日本のあゆみと国際関係', '10. 外国船の出現と天保の改革', 401, 2, FALSE, '399が幕府の財政安定のために，江戸・大阪周辺の土地を幕府の直轄領（幕領）にしようとした法令を何というか。', '大名などの反対にあい実現せず', '上知令', 'あげちれい'),
  (730, '歴史', '第4章 近代日本のあゆみと国際関係', '1. 欧米諸国の発展とアジア侵略', 402, 1, FALSE, 'アメリカ独立戦争に際し，最高司令官として植民地軍を勝利に導き，初代アメリカ大統領に選出された人物はだれか。', '', 'ワシントン', ''),
  (731, '歴史', '第4章 近代日本のあゆみと国際関係', '1. 欧米諸国の発展とアジア侵略', 403, 1, FALSE, '『社会契約論』を著し，封建制度の打破と人民主権を説いたフランスの思想家はだれか。', 'ロックは「統治二論（市民政府二論）」，モンテスキューは「法の精神」を著した', 'ルソー', ''),
  (732, '歴史', '第4章 近代日本のあゆみと国際関係', '1. 欧米諸国の発展とアジア侵略', 405, 1, FALSE, '404に際し，国民議会が発表した，人民主権・自由・平等などを明らかにした宣言を何というか。', '403の思想やアメリカの独立宣言の影響を受けている', '人権宣言', ''),
  (733, '歴史', '第4章 近代日本のあゆみと国際関係', '1. 欧米諸国の発展とアジア侵略', 406, 1, FALSE, '混乱の続くフランスで，外国からの侵入軍を打ち破り，1804年に国民投票によって皇帝の位についたのはだれか。', '', 'ナポレオン', ''),
  (734, '歴史', '第4章 近代日本のあゆみと国際関係', '1. 欧米諸国の発展とアジア侵略', 407, 1, FALSE, '18世紀後半にイギリスで始まった，工場制機械工業への生産形態の変化と，それに伴う社会の大きな変革を何というか。', '', '産業革命', ''),
  (735, '歴史', '第4章 近代日本のあゆみと国際関係', '1. 欧米諸国の発展とアジア侵略', 408, 1, FALSE, '工場などの生産手段をもつ資本家が，労働者を雇って利益の拡大を目的に自由に生産活動を行う経済のしくみを（　）という。', '', '資本主義', ''),
  (736, '歴史', '第4章 近代日本のあゆみと国際関係', '1. 欧米諸国の発展とアジア侵略', 409, 1, FALSE, '南北戦争で北軍を指導して勝利に導き，1863年に奴隷解放宣言を出した大統領はだれか。', '1865年に暗殺された', 'リンカン', ''),
  (737, '歴史', '第4章 近代日本のあゆみと国際関係', '1. 欧米諸国の発展とアジア侵略', 410, 1, FALSE, '17世紀の前半，中国東北部で生活をしていた女真族（満州族）が建国した，中国最後の王朝を何というか。', '1912年に滅亡した', '清', 'しん'),
  (738, '歴史', '第4章 近代日本のあゆみと国際関係', '1. 欧米諸国の発展とアジア侵略', 411, 1, FALSE, '1840年，アヘンの密輸を禁止した410に対し，イギリスがおこした戦争を何というか。', '', 'アヘン戦争', ''),
  (739, '歴史', '第4章 近代日本のあゆみと国際関係', '1. 欧米諸国の発展とアジア侵略', 412, 2, FALSE, '1600年にイギリスのエリザベス1世が設立した，アジア全域の貿易を独占した貿易会社を何というか。', '', '東インド会社', ''),
  (740, '歴史', '第4章 近代日本のあゆみと国際関係', '1. 欧米諸国の発展とアジア侵略', 413, 2, FALSE, '17〜18世紀，商工業者を中心とする市民階級が絶対王政を倒したことを（　）という。', 'イギリス・アメリカ・フランスでおこった', '市民革命', ''),
  (741, '歴史', '第4章 近代日本のあゆみと国際関係', '1. 欧米諸国の発展とアジア侵略', 414, 2, FALSE, '17世紀半ば，イギリスで議会派が王政を倒し，共和政を実現したできごとを（　）という。', '', 'ピューリタン革命（清教徒革命）', 'せいきょうとかくめい'),
  (742, '歴史', '第4章 近代日本のあゆみと国際関係', '1. 欧米諸国の発展とアジア侵略', 415, 2, FALSE, '414に際し，議会派の中心として農民・市民を率いて国王派と戦い，勝利した人物はだれか。', '', 'クロムウェル', ''),
  (743, '歴史', '第4章 近代日本のあゆみと国際関係', '1. 欧米諸国の発展とアジア侵略', 416, 2, FALSE, '1688年，イギリスで国王を追放し，立憲君主政と議会政治を実現させたできごとを何というか。', '1689年に権利（の）章典が発布された', '名誉革命', 'めいよ'),
  (744, '歴史', '第4章 近代日本のあゆみと国際関係', '1. 欧米諸国の発展とアジア侵略', 417, 2, FALSE, '1776年，北アメリカのイギリス植民地の人々は本国に対し，ジェファーソンらが起草した（　）を発表した。', 'ロックの影響を受けている', '独立宣言', ''),
  (745, '歴史', '第4章 近代日本のあゆみと国際関係', '1. 欧米諸国の発展とアジア侵略', 418, 2, FALSE, '1861年，貿易や奴隷制をめぐってアメリカ国内を二分しておこった内戦を何というか。', '北部は商工業，南部は農業が主産業', '南北戦争', ''),
  (746, '歴史', '第4章 近代日本のあゆみと国際関係', '1. 欧米諸国の発展とアジア侵略', 419, 2, FALSE, 'オーストリア，フランスを戦争で破り，プロイセン国王を皇帝とするドイツ帝国を成立させた，鉄血宰相とよばれた人物はだれか。', '', 'ビスマルク', ''),
  (747, '歴史', '第4章 近代日本のあゆみと国際関係', '1. 欧米諸国の発展とアジア侵略', 420, 2, FALSE, '1857年，イギリスの412に雇われていたインド兵士が待遇の改善などを求めておこした反乱を何というか。', '', 'インド大反乱', ''),
  (748, '歴史', '第4章 近代日本のあゆみと国際関係', '1. 欧米諸国の発展とアジア侵略', 421, 2, FALSE, '411で敗北した410が，1842年，イギリスとの間に結んだ条約を何というか。', 'イギリスは410から賠償金や香港を手に入れるとともに，上海などの5港を開かせた', '南京条約', 'ナンキン'),
  (749, '歴史', '第4章 近代日本のあゆみと国際関係', '1. 欧米諸国の発展とアジア侵略', 422, 2, FALSE, '1851年，洪秀全が指導者となって，男女の平等，土地の均分などを掲げておこした反乱を何というか。', '', '太平天国の乱', 'たいへいてんごく'),
  (750, '歴史', '第4章 近代日本のあゆみと国際関係', '2. 開国と江戸幕府の滅亡', 423, 1, FALSE, '1853年，4隻の黒船を率い，アメリカ大統領の国書をもって，浦賀に来航した東インド艦隊司令長官はだれか。', '', 'ペリー', ''),
  (751, '歴史', '第4章 近代日本のあゆみと国際関係', '2. 開国と江戸幕府の滅亡', 424, 1, FALSE, '1854年，幕府と423の間で結ばれた，函館・下田の開港と燃料・食料・水などの供給，下田にアメリカの領事を置くことなどを定めた条約を何というか。', 'これによって鎖国政策は崩れ，日本は開国することになった', '日米和親条約', ''),
  (752, '歴史', '第4章 近代日本のあゆみと国際関係', '2. 開国と江戸幕府の滅亡', 426, 1, FALSE, '彦根藩主だった（　）は，江戸幕府の大老に就任し，アメリカ総領事との間で通商に関する条約を結んだ。', '', '井伊直弼', 'いいなおすけ'),
  (753, '歴史', '第4章 近代日本のあゆみと国際関係', '2. 開国と江戸幕府の滅亡', 427, 1, FALSE, '425で認めさせられた，外国人が日本で犯罪を犯したとき，その国の領事が自国の法律で裁判できる権利を何というか。', '', '領事裁判権（治外法権）', ''),
  (754, '歴史', '第4章 近代日本のあゆみと国際関係', '2. 開国と江戸幕府の滅亡', 428, 1, FALSE, '425で日本がもつことができなかった，輸入品にかける税率を自主的に決めることができる権利を何というか。', '', '関税自主権', ''),
  (755, '歴史', '第4章 近代日本のあゆみと国際関係', '2. 開国と江戸幕府の滅亡', 429, 1, FALSE, '426が，幕府の政策に批判的な大名や公家など多くの人々を処罰した弾圧事件を何というか。', '', '安政の大獄', 'あんせいのたいごく'),
  (756, '歴史', '第4章 近代日本のあゆみと国際関係', '2. 開国と江戸幕府の滅亡', 430, 1, FALSE, '（　）は倒幕運動の中心となった薩摩藩士で，江戸城を無血開城に導いた。「維新の三傑」といわれたが，征韓論で敗れて政府を去り，西南戦争をおこした。', '', '西郷隆盛', 'さいごうたかもり'),
  (757, '歴史', '第4章 近代日本のあゆみと国際関係', '2. 開国と江戸幕府の滅亡', 431, 1, FALSE, '（　）は倒幕運動の中心となった薩摩藩士で，新政府の中心となって改革を断行した。岩倉使節団の一員として欧米に渡り，帰国後，征韓論に反対した。', '', '大久保利通', 'おおくぼとしみち'),
  (758, '歴史', '第4章 近代日本のあゆみと国際関係', '2. 開国と江戸幕府の滅亡', 432, 1, FALSE, '1867年，土佐藩の前藩主山内容堂の進言によって，江戸幕府第15代将軍が大政を朝廷に返還したことを何というか。', '', '大政奉還', 'たいせいほうかん'),
  (759, '歴史', '第4章 近代日本のあゆみと国際関係', '2. 開国と江戸幕府の滅亡', 433, 1, FALSE, '432を決断した，水戸藩出身の江戸幕府第15代将軍はだれか。', '政治の主導権を維持しようとしたが，官位・領地を取り上げられた', '徳川慶喜', 'とくがわよしのぶ'),
  (760, '歴史', '第4章 近代日本のあゆみと国際関係', '2. 開国と江戸幕府の滅亡', 434, 1, FALSE, '1867年，朝廷の実権を握った倒幕派が発表した，幕府を廃止し，天皇中心の新しい政治体制づくりの宣言を何というか。', 'これにより，260年余り続いた江戸幕府は滅亡した', '王政復古の大号令', ''),
  (761, '歴史', '第4章 近代日本のあゆみと国際関係', '2. 開国と江戸幕府の滅亡', 435, 2, FALSE, '貿易に関する交渉を江戸幕府との間で行った，アメリカの初代駐日総領事はだれか。', '', 'ハリス', ''),
  (762, '歴史', '第4章 近代日本のあゆみと国際関係', '2. 開国と江戸幕府の滅亡', 436, 2, FALSE, 'おじが萩に開いた松下村塾を引き継ぎ，倒幕運動を進めた高杉晋作や，明治政府で活躍した伊藤博文など多くの人材を育てた人物はだれか。', '429で刑死した', '吉田松陰', 'よしだしょういん'),
  (763, '歴史', '第4章 近代日本のあゆみと国際関係', '2. 開国と江戸幕府の滅亡', 437, 2, FALSE, '429に憤慨した水戸藩の元藩士らが，江戸城の門外で426を暗殺した事件を（　）という。', '', '桜田門外の変', ''),
  (764, '歴史', '第4章 近代日本のあゆみと国際関係', '2. 開国と江戸幕府の滅亡', 438, 2, FALSE, '幕末，天皇中心の国家をめざし，外国勢力を排除しようとする（　）運動が高まった。', '', '尊王攘夷', 'そんのうじょうい'),
  (765, '歴史', '第4章 近代日本のあゆみと国際関係', '2. 開国と江戸幕府の滅亡', 439, 2, FALSE, '（　）は倒幕運動の中心となった長州藩士で，新政府の中心となって改革を断行した。430・431とともに「維新の三傑」とよばれた', '', '木戸孝允', 'きどたかよし'),
  (766, '歴史', '第4章 近代日本のあゆみと国際関係', '2. 開国と江戸幕府の滅亡', 441, 2, FALSE, '生麦事件の報復のため，鹿児島湾に来航したイギリス艦隊と薩摩藩の間でおこった戦争を何というか。', '薩摩藩はこれにより攘夷の無謀さを悟り，倒幕へと向かった', '薩英戦争', 'さつえい'),
  (767, '歴史', '第4章 近代日本のあゆみと国際関係', '2. 開国と江戸幕府の滅亡', 442, 2, FALSE, '440らの仲介によって結成された，倒幕運動を進める薩摩藩と長州藩が結んだ同盟を何というか。', '', '薩長同盟', ''),
  (768, '歴史', '第4章 近代日本のあゆみと国際関係', '2. 開国と江戸幕府の滅亡', 443, 2, FALSE, '（　）は幕臣で，1860年，咸臨丸の艦長として太平洋を横断し，アメリカに渡った。', '430とともに，江戸城を無血開城に導いた', '勝海舟', ''),
  (769, '歴史', '第4章 近代日本のあゆみと国際関係', '2. 開国と江戸幕府の滅亡', 444, 2, FALSE, '鳥羽・伏見の戦いに始まり，五稜郭の戦いで終わる，旧幕府軍と新政府軍との戦いを（　）という。', '', '戊辰戦争', 'ぼしん'),
  (770, '歴史', '第4章 近代日本のあゆみと国際関係', '3. 明治新政府の成立と諸改革の展開', 445, 1, FALSE, '1868年，明治天皇が神に誓う形で出された新政府の基本方針を何というか。', '世論に基づく政治を行うことなどが述べられている', '五箇条の御誓文', 'ごかじょう ごせいもん'),
  (771, '歴史', '第4章 近代日本のあゆみと国際関係', '3. 明治新政府の成立と諸改革の展開', 446, 1, FALSE, '1869年，薩摩・長州・土佐・肥前の4藩主に領地と領民を朝廷に返させ，他の大名もこれにならって返上したことを（　）という。', '', '版籍奉還', 'はんせきほうかん'),
  (772, '歴史', '第4章 近代日本のあゆみと国際関係', '3. 明治新政府の成立と諸改革の展開', 447, 1, FALSE, '1871年，藩を廃止して府県を置き，中央政府から府知事・県令を派遣し，中央集権化を図ったことを何というか。', '', '廃藩置県', ''),
  (773, '歴史', '第4章 近代日本のあゆみと国際関係', '3. 明治新政府の成立と諸改革の展開', 448, 1, FALSE, '（　）は，政府が欧米列強に対抗するために掲げたスローガンで，近代産業の育成と近代軍隊の創設をめざした。', '', '富国強兵', ''),
  (774, '歴史', '第4章 近代日本のあゆみと国際関係', '3. 明治新政府の成立と諸改革の展開', 449, 1, FALSE, '1873年，地価の3％を土地の所有者に現金で納めさせる税制改革を何というか。', '反対一揆が各地でおき，のち税率を2.5％に下げた', '地租改正', 'ちそ'),
  (775, '歴史', '第4章 近代日本のあゆみと国際関係', '3. 明治新政府の成立と諸改革の展開', 450, 1, FALSE, '1873年，満20歳以上の男子に3年間の兵役の義務を定めた（　）が出された。', 'さまざまな免除規定があり，実際に兵役についたのは農家の二男・三男が中心であった', '徴兵令', 'ちょうへいれい'),
  (776, '歴史', '第4章 近代日本のあゆみと国際関係', '3. 明治新政府の成立と諸改革の展開', 451, 1, FALSE, '1872年, 近代的な学校制度の基本を定めた法令を何というか。', '授業料・学校設立費など親の負担が大きく, 反対一揆がおきた', '学制', 'がくせい'),
  (777, '歴史', '第4章 近代日本のあゆみと国際関係', '3. 明治新政府の成立と諸改革の展開', 452, 1, FALSE, '外国から機械を導入したり, 外国人を招いたりして, 近代産業の早期の育成を図る明治政府の政策を( )という。', '', '殖産興業', 'しょくさんこうぎょう'),
  (778, '歴史', '第4章 近代日本のあゆみと国際関係', '3. 明治新政府の成立と諸改革の展開', 454, 2, FALSE, '445が出された翌日に庶民に対して示された5枚の立て札を( )という。', '一揆やキリスト教の禁止など旧来のままの政策であった', '五榜の掲示', 'ごぼうのけいじ'),
  (779, '歴史', '第4章 近代日本のあゆみと国際関係', '3. 明治新政府の成立と諸改革の展開', 455, 2, FALSE, '倒幕運動の中心となった薩摩・長州・土佐・肥前藩の出身者が実権を独占して行った政治を何というか。', '', '藩閥政治', 'はんばつせいじ'),
  (780, '歴史', '第4章 近代日本のあゆみと国際関係', '3. 明治新政府の成立と諸改革の展開', 456, 2, FALSE, '江戸時代の身分制度を改めようとした政策を( )という。', '皇族・華族・士族・平民という身分の違いは残された', '四民平等', 'しみんびょうどう'),
  (781, '歴史', '第4章 近代日本のあゆみと国際関係', '3. 明治新政府の成立と諸改革の展開', 457, 2, FALSE, '1871年, 厳しい差別を受けていた人々を平民と同じと定めた布告を何というか。', '就職・結婚・居住地などの面で差別は根強く残った', '解放令', 'かいほうれい'),
  (782, '歴史', '第4章 近代日本のあゆみと国際関係', '3. 明治新政府の成立と諸改革の展開', 458, 2, FALSE, '土地の所有者名・広さ・地価などが記された, 明治政府が土地所有者に発行した証書を何というか。', '証書に記された所有者が納税した', '地券', 'ちけん'),
  (783, '歴史', '第4章 近代日本のあゆみと国際関係', '3. 明治新政府の成立と諸改革の展開', 459, 2, FALSE, '452の政策のもとに, 近代産業育成のために政府が建設した直営工場を何というか。', '軍事工場が中心', '官営模範工場', 'かんえいもはんこうじょう'),
  (784, '歴史', '第4章 近代日本のあゆみと国際関係', '3. 明治新政府の成立と諸改革の展開', 460, 2, FALSE, '埼玉県出身の実業家で, 明治政府では大蔵省で活躍し, 退官後, 第一国立銀行を設立したのはだれか。', '王子製紙・大阪紡績会社など約500社の設立にかかわった', '渋沢栄一', 'しぶさわえいいち'),
  (785, '歴史', '第4章 近代日本のあゆみと国際関係', '4. 文明開化と領土の確定', 461, 1, FALSE, '西洋の思想や生活様式を積極的に取り入れた生活様式の変化の風潮を( )という。', '', '文明開化', 'ぶんめいかいか'),
  (786, '歴史', '第4章 近代日本のあゆみと国際関係', '4. 文明開化と領土の確定', 462, 1, FALSE, '欧米の思想を日本に紹介し, 万人の平等などをわかりやすく説いた啓蒙思想家であり教育家はだれか。', '慶応義塾を創設した', '福沢諭吉', 'ふくざわゆきち'),
  (787, '歴史', '第4章 近代日本のあゆみと国際関係', '4. 文明開化と領土の確定', 463, 1, FALSE, '「天は人の上に人をつくらず, 人の下に人をつくらず」という冒頭の文で知られる, 462が著した啓蒙書を何というか。', '', '学問のすゝめ', 'がくもんのすすめ'),
  (788, '歴史', '第4章 近代日本のあゆみと国際関係', '4. 文明開化と領土の確定', 465, 1, FALSE, '1875年, 日本とロシアの間の国境を定めた( )が結ばれた。', '樺太(サハリン)をロシア領, 国後島・択捉島・色丹島・歯舞群島に加え, 得撫島以北も日本領とした', '樺太・千島交換条約', 'からふと・ちしまこうかんじょうやく'),
  (789, '歴史', '第4章 近代日本のあゆみと国際関係', '4. 文明開化と領土の確定', 466, 1, FALSE, '鎖国政策をとっている朝鮮に対し, 武力を使ってでも開国させようという考えを( )という。', '西郷隆盛・板垣退助・江藤新平らが唱えた', '征韓論', 'せいかんろん'),
  (790, '歴史', '第4章 近代日本のあゆみと国際関係', '4. 文明開化と領土の確定', 467, 2, FALSE, '464の使節団に同行した最年少女子留学生はだれか。', '帰国後, 女子教育に力を注ぎ, 女子英学塾(現在の津田塾大学)を設立した', '津田梅子', 'つだうめこ'),
  (791, '歴史', '第4章 近代日本のあゆみと国際関係', '4. 文明開化と領土の確定', 468, 2, FALSE, '同志社英学校(現在の同志社大学)を設立した, 群馬県出身の人物はだれか。', '', '新島襄', 'にいじまじょう'),
  (792, '歴史', '第4章 近代日本のあゆみと国際関係', '4. 文明開化と領土の確定', 469, 2, FALSE, 'フランスで文学などを学び, ルソーの「社会契約論」を「民約訳解」として翻訳し, 「東洋のルソー」とよばれたのはだれか。', '', '中江兆民', 'なかえちょうみん'),
  (793, '歴史', '第4章 近代日本のあゆみと国際関係', '4. 文明開化と領土の確定', 470, 2, FALSE, '明治時代の初め, 北海道と樺太の開発・行政を行うために設置された役所を何というか。', '1882年に廃止された', '開拓使', 'かいたくし'),
  (794, '歴史', '第4章 近代日本のあゆみと国際関係', '4. 文明開化と領土の確定', 471, 2, FALSE, '北海道の開拓と北方の警備を目的に, 失業した士族や平民が( )として配備された。', '', '屯田兵', 'とんでんへい'),
  (795, '歴史', '第4章 近代日本のあゆみと国際関係', '4. 文明開化と領土の確定', 472, 2, FALSE, '1871年, 日本と清の間で結ばれた, 領事裁判権の相互承認などを定めた対等な条約を何というか。', '', '日清修好条規', 'にっしんしゅうこうじょうき'),
  (796, '歴史', '第4章 近代日本のあゆみと国際関係', '4. 文明開化と領土の確定', 473, 2, FALSE, '日本は, 1875年におこった( )を口実に朝鮮に軍事的な圧力をかけ, 翌年, 朝鮮にとって不平等な条約を結ばせた。', '', '江華島事件', 'こうかとうじけん'),
  (797, '歴史', '第4章 近代日本のあゆみと国際関係', '4. 文明開化と領土の確定', 474, 2, FALSE, '1876年, 473を理由に結ばれた, 朝鮮を開国させ, 日本の領事裁判権を認めさせるなど, 朝鮮にとって不平等な条約を何というか。', '', '日朝修好条規', 'にっちょうしゅうこうじょうき'),
  (798, '歴史', '第4章 近代日本のあゆみと国際関係', '5. 自由民権運動と議会の開設', 475, 1, FALSE, '1877年に九州南部でおきた, 西郷隆盛を中心とした不平士族の反乱を何というか。', '政府軍が勝ち, 徴兵によって組織された軍隊の実力が認められた', '西南戦争', 'せいなんせんそう'),
  (799, '歴史', '第4章 近代日本のあゆみと国際関係', '5. 自由民権運動と議会の開設', 476, 1, FALSE, '1874年, 薩摩・長州藩出身者による藩閥政治を批判し, 議会の開設を求める( )が政府に提出された。', '', '民撰議院設立の建白書', 'みんせんぎいんせつりつのけんぱくしょ'),
  (800, '歴史', '第4章 近代日本のあゆみと国際関係', '5. 自由民権運動と議会の開設', 477, 1, FALSE, '476の提出をきっかけにおこった, 藩閥政治打破, 国会開設などの民主的改革を求めた運動を何というか。', '', '自由民権運動', 'じゆうみんけんうんどう'),
  (801, '歴史', '第4章 近代日本のあゆみと国際関係', '5. 自由民権運動と議会の開設', 478, 1, FALSE, '西郷隆盛とともに明治政府を去った土佐藩出身の政治家で, 477の指導者として活躍した人物はだれか。', '', '板垣退助', 'いたがきたいすけ'),
  (802, '歴史', '第4章 近代日本のあゆみと国際関係', '5. 自由民権運動と議会の開設', 479, 1, FALSE, '478が中心となって結成した, フランスの影響を受けた, 急進的な政党を何というか。', '士族や農民が支持した', '自由党', 'じゆうとう'),
  (803, '歴史', '第4章 近代日本のあゆみと国際関係', '5. 自由民権運動と議会の開設', 480, 1, FALSE, '1885年, 太政官制を廃止し, ( )が創設された。', '国家の最高行政機関とした', '内閣制度', 'ないかくせいど'),
  (804, '歴史', '第4章 近代日本のあゆみと国際関係', '5. 自由民権運動と議会の開設', 483, 1, FALSE, '帝国議会のうち, 国民の選挙で選出された議員で構成された議院を( )といい, 選挙権は直接国税15円以上を納める満25歳以上の男子に限られていた。', '', '衆議院', 'しゅうぎいん'),
  (805, '歴史', '第4章 近代日本のあゆみと国際関係', '5. 自由民権運動と議会の開設', 484, 1, FALSE, '帝国議会のうち, 世襲の皇族議員・華族議員・多額納税者・天皇が任命した者で構成された議院を( )といい, 予算先議権がないほかは, 483とほぼ対等の権限をもった。', '', '貴族院', 'きぞくいん'),
  (806, '歴史', '第4章 近代日本のあゆみと国際関係', '5. 自由民権運動と議会の開設', 485, 2, TRUE, '大久保利通・木戸孝允らによって征韓論が退けられたため, 西郷隆盛・478ら征韓派が一斉に政府を去ったできごとを何というか。', '', '明治六年の政変', 'めいじろくねんのせいへん'),
  (807, '歴史', '第4章 近代日本のあゆみと国際関係', '5. 自由民権運動と議会の開設', 486, 2, FALSE, '明治政府で司法制度の整備に尽力したが, 485で政府を去り, のちに佐賀の乱をおこした人物はだれか。', '476の提出者の一人でもあった', '江藤新平', 'えとうしんぺい'),
  (808, '歴史', '第4章 近代日本のあゆみと国際関係', '5. 自由民権運動と議会の開設', 487, 2, FALSE, '1880年の愛国社第4回大会で結成された, 国会開設運動の中心となった組織を何というか。', '国会開設の請願書を政府に提出したが, 政府はこれを受けつけなかった', '国会期成同盟', 'こっかいきせいどうめい'),
  (809, '歴史', '第4章 近代日本のあゆみと国際関係', '5. 自由民権運動と議会の開設', 488, 2, FALSE, '1881年, 政府が国会開設の世論の高まりを受けて, 1890年までに国会を開くことを天皇の名で約束したものを( )という。', '', '国会開設の勅諭', 'こっかいかいせつのちょくゆ'),
  (810, '歴史', '第4章 近代日本のあゆみと国際関係', '5. 自由民権運動と議会の開設', 489, 2, FALSE, '開拓使官有物払い下げ事件を追及したことから政府を去った, 肥前藩出身の政治家はだれか。', '東京専門学校(現在の早稲田大学)を創設した', '大隈重信', 'おおくましげのぶ'),
  (811, '歴史', '第4章 近代日本のあゆみと国際関係', '5. 自由民権運動と議会の開設', 490, 2, FALSE, '489が中心となって結成した, イギリスの影響を受けた, 比較的穏健な政党を何というか。', '資本家や地主が支持した', '立憲改進党', 'りっけんかいしんとう'),
  (812, '歴史', '第4章 近代日本のあゆみと国際関係', '5. 自由民権運動と議会の開設', 491, 2, FALSE, '1884年, 埼玉県の農民らが困民党を結成して武装蜂起した( )では, これを鎮めるために政府は軍隊を出動させた。', '', '秩父事件', 'ちちぶじけん'),
  (813, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 492, 1, FALSE, '第2次伊藤博文内閣のとき, イギリスとの間で日英通商航海条約を結び, 領事裁判権の撤廃を実現した外務大臣はだれか。', '', '陸奥宗光', 'むつむねみつ'),
  (814, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 493, 1, FALSE, '1894年, 朝鮮半島で東学を信仰する農民が, 朝鮮半島の南部一帯で蜂起したできごとを何というか。', '東学党の乱ともいう', '甲午農民戦争', 'こうごのうみんせんそう'),
  (815, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 494, 1, FALSE, '493をきっかけに清と日本は朝鮮半島に出兵し( )がおこったが, 日本が勝利した。', '', '日清戦争', 'にっしんせんそう'),
  (816, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 495, 1, FALSE, '494の後, 伊藤博文・492が全権として出席した会議で結ばれた講和条約を何というか。', '', '下関条約', 'しものせきじょうやく'),
  (817, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 497, 1, FALSE, 'ロシアがドイツ・フランスを誘い, 496の返還を日本に要求してきたことを何というか。', '', '三国干渉', 'さんごくかんしょう'),
  (818, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 498, 1, FALSE, '「扶清滅洋」をスローガンに掲げる集団による, 北京の外国公使館攻撃に対し, 日本などを中心とする8か国の連合軍が鎮圧した事件を何というか。', '列強の進出に抵抗した中国民衆による排外運動', '義和団事件', 'ぎわだんじけん'),
  (819, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 499, 1, FALSE, 'ロシアの南下政策を警戒し, 日本は1902年にイギリスとの間に( )を結んだ。', '1921年のワシントン会議の四か国条約で破棄された', '日英同盟', 'にちえいどうめい'),
  (820, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 500, 1, FALSE, '1904～05年, 日本とロシアの間で行われた戦争を何というか。', '満州・朝鮮の支配をめぐって, 両国が対立した', '日露戦争', 'にちろせんそう'),
  (821, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 501, 1, FALSE, '500の終結に際して，1905年，アメリカの仲立ちで結ばれた講和条約を何というか。', '日本の全権は小村寿太郎', 'ポーツマス条約', ''),
  (822, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 502, 1, FALSE, '初代韓国統監の伊藤博文が暗殺された翌年に，韓国の国名を朝鮮と改め，植民地としたことを（　）という。', '', '韓国併合', 'かんこくへいごう'),
  (823, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 503, 1, FALSE, '清が滅亡し，アジアで最初の共和国である中華民国が成立することとなった革命を何というか。', '', '辛亥革命', 'しんがい'),
  (824, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 505, 1, FALSE, '504が唱えた，民族主義・民権主義・民生主義からなる中国革命の指導理念を何というか。', '', '三民主義', ''),
  (825, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 506, 2, FALSE, '条約改正を進めるにあたり，日本が近代国家であることを示すために，井上馨は（　）で舞踏会を開くなどの極端な欧化政策をとった。', '', '鹿鳴館', 'ろくめいかん'),
  (826, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 507, 2, FALSE, '和歌山県沖でイギリスの貨物船が沈没し，イギリス人船員は全員助かったが，日本人乗客は全員水死した（　）をきっかけに，領事裁判権の撤廃を求める世論が高まった。', '', 'ノルマントン号事件', ''),
  (827, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 508, 2, FALSE, '資本主義の発達した強国が，軍事力と経済力を背景に，植民地を獲得しようとする動きを何というか。', '', '帝国主義', 'ていこく'),
  (828, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 509, 2, TRUE, '清と11か国との間に結ばれた，498の講和に関する取り決めを何というか。', '', '北京議定書', 'ペキン'),
  (829, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 510, 2, FALSE, '札幌農学校に学び，非戦論を唱えて日本がロシアと戦争することに反対したキリスト教徒はだれか。', '', '内村鑑三', 'うちむらかんぞう'),
  (830, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 511, 2, FALSE, '日本海海戦を指揮し，ロシアのバルチック艦隊をほぼ壊滅させた連合艦隊司令長官はだれか。', '', '東郷平八郎', 'とうごうへいはちろう'),
  (831, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 512, 2, FALSE, '501で賠償金が得られなかったことを知った国民が，東京で行われた講和反対集会で暴徒化し，（　）がおきた。', '', '日比谷焼き打ち事件', 'ひびや'),
  (832, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 513, 2, FALSE, '501で得た南満州における鉄道や鉱山の経営を行うために設立された半官半民の会社を何というか。', '', '南満州鉄道株式会社(満鉄)', 'みなみまんしゅうてつどう'),
  (833, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 514, 2, FALSE, '満州のハルビンで韓国統監の伊藤博文を暗殺した朝鮮の独立運動家はだれか。', '', '安重根', 'あんじゅうこん'),
  (834, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 515, 2, FALSE, '502で朝鮮支配のために京城（現在のソウル）に設置した，軍事・行政のすべてを統轄する機関を何というか。', '', '朝鮮総督府', 'ちょうせんそうとくふ'),
  (835, '歴史', '第4章 近代日本のあゆみと国際関係', '6. 条約改正と日清・日露戦争', 516, 2, FALSE, '（　）は，中華民国の臨時大総統の地位を504から譲られ，清を滅ぼした後，大総統となり独裁政治を進めた。', '', '袁世凱', 'えんせいがい'),
  (836, '歴史', '第4章 近代日本のあゆみと国際関係', '7. 産業革命と近代文化の形成', 517, 1, FALSE, '日本での（　）は，日清戦争前後の19世紀末から製糸業・紡績業などの軽工業の分野から始まった。', '', '産業革命', ''),
  (837, '歴史', '第4章 近代日本のあゆみと国際関係', '7. 産業革命と近代文化の形成', 518, 1, FALSE, '下関条約で獲得した賠償金の一部で，福岡県に建設された近代的な製鉄所を何というか。', '1901年に操業を開始した', '八幡製鉄所', 'やはた'),
  (838, '歴史', '第4章 近代日本のあゆみと国際関係', '7. 産業革命と近代文化の形成', 519, 1, FALSE, '政府と深いつながりをもち，官営模範工場を払い下げられた三井・三菱などは，さまざまな分野の会社をもつ独占的企業集団である（　）に成長した。', '', '財閥', 'ざいばつ'),
  (839, '歴史', '第4章 近代日本のあゆみと国際関係', '7. 産業革命と近代文化の形成', 520, 1, FALSE, '1890年ごろ，栃木県の渡良瀬川流域で鉱山の廃水によって，農業や漁業に大きな被害が出る（　）がおきた。', '', '足尾銅山鉱毒事件', 'あしおどうざんこうどく'),
  (840, '歴史', '第4章 近代日本のあゆみと国際関係', '7. 産業革命と近代文化の形成', 521, 1, FALSE, '520を帝国議会で問題提起した，栃木県出身の衆議院議員はだれか。', '議員を辞職した後も，事件解決のために生涯をささげた', '田中正造', 'たなかしょうぞう'),
  (841, '歴史', '第4章 近代日本のあゆみと国際関係', '7. 産業革命と近代文化の形成', 522, 1, FALSE, '1910年，天皇暗殺を計画したとして社会主義者たちが逮捕され，翌年，処刑された事件を何というか。', '現在では，多くの人が無実だったとされる', '大逆事件', 'たいぎゃく'),
  (842, '歴史', '第4章 近代日本のあゆみと国際関係', '7. 産業革命と近代文化の形成', 523, 1, FALSE, '1890年に，学校教育と国民の道徳の基本方針として，忠君愛国の精神を示す（　）が発布された。', '', '教育勅語', 'ちょくご'),
  (843, '歴史', '第4章 近代日本のあゆみと国際関係', '7. 産業革命と近代文化の形成', 524, 1, FALSE, '日露戦争に際し，出兵した弟を思う「君死にたまふことなかれ」を発表し，戦争に疑問を投げかけた女流歌人はだれか。', '', '与謝野晶子', 'よさのあきこ'),
  (844, '歴史', '第4章 近代日本のあゆみと国際関係', '7. 産業革命と近代文化の形成', 525, 2, FALSE, '「平民新聞」で日露戦争の開戦に反対の立場をとり，522で処刑された社会主義者はだれか。', '522の首謀者とされた', '幸徳秋水', 'こうとくしゅうすい'),
  (845, '歴史', '第4章 近代日本のあゆみと国際関係', '7. 産業革命と近代文化の形成', 526, 2, FALSE, 'ドイツに留学し，コッホに学び，破傷風菌の血清療法を発見した細菌学者はだれか。', 'ドイツから帰国後，伝染病研究所を創設した', '北里柴三郎', 'きたさとしばさぶろう'),
  (846, '歴史', '第4章 近代日本のあゆみと国際関係', '7. 産業革命と近代文化の形成', 527, 2, FALSE, '526に学び，アメリカ留学後に，アフリカのガーナに渡り，黄熱病の研究中に自らも感染し，命を落とした細菌学者はだれか。', '', '野口英世', 'のぐちひでよ'),
  (847, '歴史', '第4章 近代日本のあゆみと国際関係', '7. 産業革命と近代文化の形成', 528, 2, FALSE, '代表作の「たけくらべ」で女性の人生の苦悩を描いた，明治時代の女性作家はだれか。', '', '樋口一葉', 'ひぐちいちよう'),
  (848, '歴史', '第4章 近代日本のあゆみと国際関係', '7. 産業革命と近代文化の形成', 529, 2, FALSE, '余裕のある態度で人生を静かに見つめ，人生の理想を描こうと努力し，「坊っちゃん」「吾輩は猫である」などを著した小説家はだれか。', '', '夏目漱石', 'なつめそうせき'),
  (849, '歴史', '第4章 近代日本のあゆみと国際関係', '7. 産業革命と近代文化の形成', 530, 2, FALSE, 'ドイツに留学し，ヨーロッパ文学の翻訳や歴史小説を著し，「舞姫」などの作品を残した軍医で小説家はだれか。', '', '森鴎外', 'もりおうがい'),
  (850, '歴史', '第4章 近代日本のあゆみと国際関係', '7. 産業革命と近代文化の形成', 531, 2, FALSE, 'いったん否定された日本美術の再評価を行い，東京美術学校の設立に尽力したアメリカ人哲学者はだれか。', '', 'フェノロサ', ''),
  (851, '歴史', '第4章 近代日本のあゆみと国際関係', '7. 産業革命と近代文化の形成', 532, 2, FALSE, '531とともに日本美術の再興に努め，横山大観らとともに日本美術院を設立した美術評論家はだれか。', '', '岡倉天心', 'おかくらてんしん'),
  (852, '歴史', '第5章 2つの世界大戦と日本', '1. 第一次世界大戦と戦後の世界', 534, 1, FALSE, '1914年，オーストリアの皇太子夫妻が暗殺された事件をきっかけに始まった，ヨーロッパを主戦場とする世界規模の戦争を何というか。', '飛行機・潜水艦・戦車・化学兵器などの新兵器が投入された', '第一次世界大戦', ''),
  (853, '歴史', '第5章 2つの世界大戦と日本', '1. 第一次世界大戦と戦後の世界', 535, 1, FALSE, '534の戦争中，日本が中国に突きつけた要求を何というか。', 'ドイツの山東省の権益の継承，旅順・大連の租借期限の延長などを要求した', '二十一か条の要求', ''),
  (854, '歴史', '第5章 2つの世界大戦と日本', '1. 第一次世界大戦と戦後の世界', 536, 1, FALSE, '1917年におこった三月革命と十一月革命をあわせて（　）という。', '十一月革命によって，世界で初めての社会主義政府が誕生した', 'ロシア革命', ''),
  (855, '歴史', '第5章 2つの世界大戦と日本', '1. 第一次世界大戦と戦後の世界', 537, 1, FALSE, '536の後，1922年に建国された，世界初の社会主義国を正式名称で何というか。', '1991年に解体した', 'ソビエト社会主義共和国連邦', 'れんぽう'),
  (856, '歴史', '第5章 2つの世界大戦と日本', '1. 第一次世界大戦と戦後の世界', 538, 1, FALSE, '1919年，パリ講和会議で調印された，ドイツと連合国の間で結ばれた講和条約を何というか。', 'ドイツの軍備制限などについて定めた', 'ベルサイユ条約', ''),
  (857, '歴史', '第5章 2つの世界大戦と日本', '1. 第一次世界大戦と戦後の世界', 539, 1, FALSE, '1920年につくられた，世界で最初の国際的な平和機構を何というか。', '本部はジュネーブ。日本は常任理事国となった', '国際連盟', ''),
  (858, '歴史', '第5章 2つの世界大戦と日本', '1. 第一次世界大戦と戦後の世界', 540, 1, FALSE, 'パリ講和会議で535がほとんど認められたことに抗議して，1919年に中国の北京で始まった反日・反帝国主義運動を（　）という。', '', '五・四運動', 'ご し'),
  (859, '歴史', '第5章 2つの世界大戦と日本', '1. 第一次世界大戦と戦後の世界', 541, 1, FALSE, '1919年に朝鮮の京城（現在のソウル）で始まった反日独立運動を（　）という。', '「独立万歳」をさけぶ運動が各地でおこった', '三・一独立運動', 'さん いち'),
  (860, '歴史', '第5章 2つの世界大戦と日本', '1. 第一次世界大戦と戦後の世界', 542, 2, FALSE, 'フランスに対抗するために，1882年にドイツ・オーストリア・イタリアの間で結ばれた軍事同盟を何というか。', '', '三国同盟', ''),
  (861, '歴史', '第5章 2つの世界大戦と日本', '1. 第一次世界大戦と戦後の世界', 543, 2, FALSE, 'イギリス・フランス・ロシアの三国間での協力関係を（　）という。', '露仏同盟，英仏協商，英露協商によって相互に提携し，ドイツに対抗した', '三国協商', ''),
  (862, '歴史', '第5章 2つの世界大戦と日本', '1. 第一次世界大戦と戦後の世界', 545, 2, FALSE, '1914年，バルカン半島を訪れていたオーストリア皇太子夫妻がセルビア人青年に暗殺された事件を何というか。', '', 'サラエボ事件', ''),
  (863, '歴史', '第5章 2つの世界大戦と日本', '1. 第一次世界大戦と戦後の世界', 546, 2, FALSE, '534で，ドイツ側に立って戦った国々を何というか。', 'ドイツ・オーストリア・オスマン帝国・ブルガリア。これらの国と対戦したのは，イギリス・フランス・ロシア・アメリカなどの連合国。日本は日英同盟を名目に連合国側で参戦', '同盟国', ''),
  (864, '歴史', '第5章 2つの世界大戦と日本', '1. 第一次世界大戦と戦後の世界', 547, 2, FALSE, '536のうち，十一月革命を指導し，ソビエトに権力の基盤を置く社会主義政府を樹立した人物はだれか。', '', 'レーニン', ''),
  (865, '歴史', '第5章 2つの世界大戦と日本', '1. 第一次世界大戦と戦後の世界', 548, 2, FALSE, '539の設立を提案した「十四か条の平和原則」を発表した，アメリカの大統領はだれか。', 'アメリカは議会の反対によって539に参加しなかった', 'ウィルソン', ''),
  (866, '歴史', '第5章 2つの世界大戦と日本', '1. 第一次世界大戦と戦後の世界', 549, 2, FALSE, '軍縮と日本の海外進出抑制を目的に，1921〜22年にアメリカで開かれた国際会議を何というか。', '四か国条約・海軍軍縮条約・九か国条約が締結された。四か国条約によって日英同盟が破棄された', 'ワシントン会議', ''),
  (867, '歴史', '第5章 2つの世界大戦と日本', '2. 大正デモクラシー', 551, 1, FALSE, '大正時代には民主主義を求める声が高まったが，当時のこのような風潮を何というか。', '', '大正デモクラシー', 'たいしょうでもくらしー'),
  (868, '歴史', '第5章 2つの世界大戦と日本', '2. 大正デモクラシー', 552, 1, FALSE, '普通選挙と政党内閣の必要性を説いた東大教授の政治学者はだれか。', '天皇主権の憲法のもとでの民衆の政治参加を主張した', '吉野作造', 'よしのさくぞう'),
  (869, '歴史', '第5章 2つの世界大戦と日本', '2. 大正デモクラシー', 553, 1, FALSE, '552が唱えた( )とは，政治の目的を民衆の福利に置き，政策の決定は民衆の意向によるべきであるとする民主主義思想である。', '', '民本主義', 'みんぽんしゅぎ'),
  (870, '歴史', '第5章 2つの世界大戦と日本', '2. 大正デモクラシー', 554, 1, FALSE, '第一次世界大戦中，ロシア革命の拡大を恐れた列強が1918年におこした，革命への干渉戦争を何というか。', '', 'シベリア出兵', 'しべりあしゅっぺい'),
  (871, '歴史', '第5章 2つの世界大戦と日本', '2. 大正デモクラシー', 555, 1, FALSE, '554を見越して米の買い占めがおこり，米価が高騰したため，富山県の漁村の主婦の暴動に端を発して全国で( )がおきた。', '', '米騒動', 'こめそうどう'),
  (872, '歴史', '第5章 2つの世界大戦と日本', '2. 大正デモクラシー', 557, 1, FALSE, '1925年に制定された，国体の変革や私有財産の否認を目的とする結社を禁止することを定めた法律を何というか。', '', '治安維持法', 'ちあんいじほう'),
  (873, '歴史', '第5章 2つの世界大戦と日本', '2. 大正デモクラシー', 558, 1, FALSE, '1925年に制定された，納税額に関係なく，満25歳以上のすべての男子に選挙権を与えることを定めた法律を何というか。', '', '普通選挙法', 'ふつうせんきょほう'),
  (874, '歴史', '第5章 2つの世界大戦と日本', '2. 大正デモクラシー', 559, 2, FALSE, '桂太郎内閣が議会を無視した政治を行っているのに対し，立憲政治の擁護を求め，桂太郎内閣を退陣に追い込んだ運動を何というか。', '', '第一次護憲運動', 'だいいちじごけんうんどう'),
  (875, '歴史', '第5章 2つの世界大戦と日本', '2. 大正デモクラシー', 560, 2, FALSE, '559の中心として活動し，「憲政の神様」とよばれた衆議院議員はだれか。', '衆議院議員に25回連続して当選した', '尾崎行雄', 'おざきゆきお'),
  (876, '歴史', '第5章 2つの世界大戦と日本', '2. 大正デモクラシー', 561, 2, FALSE, '第一次世界大戦の期間中におきた，日本の好景気を( )といい，日本は連合国に軍需品を供給するなど工業生産額も著しくのびた。', '', '大戦景気', 'たいせんけいき'),
  (877, '歴史', '第5章 2つの世界大戦と日本', '2. 大正デモクラシー', 562, 2, FALSE, '561によって，急に大金持ちになった( )が現れたが，大戦後，不景気になると没落する者が多かった。', '', '成金', 'なりきん'),
  (878, '歴史', '第5章 2つの世界大戦と日本', '2. 大正デモクラシー', 563, 2, FALSE, '議会の多数党が組織する内閣を( )といい，1918年，立憲政友会総裁の556が，日本初の本格的な( )を組織した。', '', '政党内閣', 'せいとうないかく'),
  (879, '歴史', '第5章 2つの世界大戦と日本', '2. 大正デモクラシー', 564, 2, FALSE, '1924年，貴族院中心の内閣が成立したことに対して，普通選挙の実現や貴族院の改革などを求めておこった運動を何というか。', '', '第二次護憲運動', 'だいにじごけんうんどう'),
  (880, '歴史', '第5章 2つの世界大戦と日本', '2. 大正デモクラシー', 565, 2, FALSE, '564の結果成立した内閣の首相となり，翌年，558を成立させたのはだれか。', '憲政会を中心とする連立内閣が組織された', '加藤高明', 'かとうたかあき'),
  (881, '歴史', '第5章 2つの世界大戦と日本', '3. 社会運動と大衆文化', 566, 1, FALSE, '労働時間や賃金などをめぐって，労働者と使用者との間でおこる争いを何というか。', 'ストライキなどの行動', '労働争議', 'ろうどうそうぎ'),
  (882, '歴史', '第5章 2つの世界大戦と日本', '3. 社会運動と大衆文化', 567, 1, FALSE, '農村では，地主に対して小作人が，小作料の引き下げを求めて( )をおこした。', '1922年に日本農民組合が結成された', '小作争議', 'こさくそうぎ'),
  (883, '歴史', '第5章 2つの世界大戦と日本', '3. 社会運動と大衆文化', 568, 1, FALSE, '1922年，京都で結成された( )は，部落差別からの解放をめざした全国組織である。', '', '全国水平社', 'ぜんこくすいへいしゃ'),
  (884, '歴史', '第5章 2つの世界大戦と日本', '3. 社会運動と大衆文化', 569, 1, FALSE, '1923年9月1日，関東地方を中心に襲った大地震による災害を( )という。', '流言によって多数の中国人や朝鮮人，社会主義者らが殺された', '関東大震災', 'かんとうだいしんさい'),
  (885, '歴史', '第5章 2つの世界大戦と日本', '3. 社会運動と大衆文化', 570, 1, FALSE, '( )は新思潮派に属する小説家で，古典から題材をとった短編が多い。『羅生門』『鼻』などを発表した。', '', '芥川龍之介', 'あくたがわりゅうのすけ'),
  (886, '歴史', '第5章 2つの世界大戦と日本', '3. 社会運動と大衆文化', 571, 1, FALSE, '1925年，( )が東京・大阪・名古屋で始まり，翌年に日本放送協会(NHK)が設立された。', '新聞とともに，重要な情報源となった', 'ラジオ放送', 'らじおほうそう'),
  (887, '歴史', '第5章 2つの世界大戦と日本', '3. 社会運動と大衆文化', 572, 2, FALSE, '1922年に，堺利彦や山川均などが結成した政党を何というか。', '取り締まりが厳しく，公然と活動することができなかった', '日本共産党', 'にほんきょうさんとう'),
  (888, '歴史', '第5章 2つの世界大戦と日本', '3. 社会運動と大衆文化', 574, 2, FALSE, '1920年，平塚らいてう・市川房枝らが設立した，女性の政治活動への参加などを求める団体を何というか。', '', '新婦人協会', 'しんふじんきょうかい'),
  (889, '歴史', '第5章 2つの世界大戦と日本', '3. 社会運動と大衆文化', 575, 2, FALSE, '( )は白樺派を代表する小説家で，『暗夜行路』『城の崎にて』などの小説を発表した。', '', '志賀直哉', 'しがなおや'),
  (890, '歴史', '第5章 2つの世界大戦と日本', '3. 社会運動と大衆文化', 576, 2, FALSE, '( )は新感覚派を代表する小説家で，1968年にノーベル文学賞を受賞した。『伊豆の踊子』『雪国』などを発表した。', '', '川端康成', 'かわばたやすなり'),
  (891, '歴史', '第5章 2つの世界大戦と日本', '3. 社会運動と大衆文化', 577, 2, FALSE, '労働者や農民の目から見た資本主義社会の矛盾を描いた文学を( )という。', '治安維持法などにより弾圧を受けた', 'プロレタリア文学', 'ぷろれたりあぶんがく'),
  (892, '歴史', '第5章 2つの世界大戦と日本', '3. 社会運動と大衆文化', 578, 2, FALSE, '( )は577の作家で，代表作に『蟹工船』がある。非合法活動中に逮捕され，拷問により死亡した。', '', '小林多喜二', 'こばやしたきじ'),
  (893, '歴史', '第5章 2つの世界大戦と日本', '4. 世界恐慌とファシズムの台頭', 579, 1, FALSE, '1929年，ニューヨークのウォール街で株の大暴落がおこったことをきっかけとして，( )が引きおこされた。', '', '世界恐慌', 'せかいきょうこう'),
  (894, '歴史', '第5章 2つの世界大戦と日本', '4. 世界恐慌とファシズムの台頭', 580, 1, FALSE, '579の際にアメリカで実行された，国内の産業に対する強力な経済統制策を何というか。', '「新規まき直し」という意味', 'ニューディール政策', 'にゅーでぃーるせいさく'),
  (895, '歴史', '第5章 2つの世界大戦と日本', '4. 世界恐慌とファシズムの台頭', 581, 1, FALSE, '579に際して，イギリスやフランスのとった排他的な保護貿易政策を何というか。', '自治領や植民地など，関係の深い国や地域との間だけで貿易を行い，それ以外の国々の商品には高い関税をかけ，輸入を減らした', 'ブロック経済', 'ぶろっくけいざい'),
  (896, '歴史', '第5章 2つの世界大戦と日本', '4. 世界恐慌とファシズムの台頭', 582, 1, FALSE, '国家の利益を優先し，個人の自由や民主主義を認めない全体主義的な政治のことを( )という。', '第二次世界大戦前のドイツやイタリアで見られた', 'ファシズム', 'ふぁしずむ'),
  (897, '歴史', '第5章 2つの世界大戦と日本', '4. 世界恐慌とファシズムの台頭', 584, 1, FALSE, '583が党首として，独裁体制を確立した政党を何というか。', '国民社会主義ドイツ労働者党の略称', 'ナチス', 'なちす'),
  (898, '歴史', '第5章 2つの世界大戦と日本', '4. 世界恐慌とファシズムの台頭', 586, 2, FALSE, 'ソ連はレーニンの死後，独裁体制をいた( )によって五か年計画が実行されていたため，579の影響を受けなかった。', '', 'スターリン', 'すたーりん'),
  (899, '歴史', '第5章 2つの世界大戦と日本', '4. 世界恐慌とファシズムの台頭', 587, 2, FALSE, 'イタリアの独裁政治家である( )は，一党独裁政権を樹立し，エチオピアを侵略し，併合した。', '', 'ムッソリーニ', 'むっそりーに'),
  (900, '歴史', '第5章 2つの世界大戦と日本', '4. 世界恐慌とファシズムの台頭', 588, 2, FALSE, 'イタリアでは，587が率いる( )が1922年に政権を握ったが，587の失脚によって解散した。', '', 'ファシスト党', 'ふぁしすととう'),
  (901, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 589, 1, FALSE, '日本の陸軍部隊が奉天(現在の瀋陽)郊外の南満州鉄道の線路を爆破した事件を( )という。', '', '柳条湖事件', 'りゅうじょうこじけん'),
  (902, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 590, 1, FALSE, '1931年，589をきっかけに，日本の陸軍部隊が中国東北部で引きおこした軍事行動を何というか。', '', '満州事変', 'まんしゅうじへん'),
  (903, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 591, 1, FALSE, '1932年，実質は日本人が政治・経済・軍事を支配する( )が中国東北部に建国され，首都は新京(現在の長春)に置かれた。', '', '満州国', 'まんしゅうこく'),
  (904, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 592, 1, FALSE, '1933年，国際連盟が派遣した調査団の報告に基づいて，国際連盟に591を認められなかった日本はどのような行動をとったか。', '', '国際連盟脱退', 'こくさいれんめいだったい'),
  (905, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 593, 1, FALSE, '1932年，海軍青年将校らが首相官邸で当時の首相を暗殺した事件を何というか。', 'この事件によって，政党内閣の時代が終わった', '五・一五事件', 'ごいちごじけん'),
  (906, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 594, 1, FALSE, '立憲政友会総裁の( )は，護憲運動の中心となった政治家で，1931年には内閣を組織し，591の建国に反対の立場をとり，593で暗殺された。', '', '犬養毅', 'いぬかいつよし'),
  (907, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 595, 1, FALSE, '1936年，陸軍青年将校が率いる部隊が首相官邸・警視庁・朝日新聞社などを襲撃したクーデター事件を何というか。', 'この事件以後，軍部は政治への発言力をいっそう強めた', '二・二六事件', 'ににろくじけん'),
  (908, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 596, 1, FALSE, '1949年に中華人民共和国を建国し，国家主席として社会主義国家を建設したのはだれか。', '', '毛沢東', 'もうたくとう'),
  (909, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 597, 1, FALSE, '1927年，南京に国民政府を樹立したが，第二次世界大戦後，内戦に敗れ，中華民国政府を台湾に移した人物はだれか。', '', '蒋介石', 'しょうかいせき'),
  (910, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 598, 1, FALSE, '1937年，中国の北京郊外でおこった日中両軍の軍事衝突事件を( )という。', '', '盧溝橋事件', 'ろこうきょうじけん'),
  (911, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 599, 1, FALSE, '598をきっかけに1937年に始まった戦争を何というか。', '戦場は中国全土に拡大した', '日中戦争', 'にっちゅうせんそう'),
  (912, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 600, 1, FALSE, '1938年，政府が議会の承認がなくても，戦争遂行に必要な人や物資を自由に徴用できることを可能にした法律を何というか。', '', '国家総動員法', 'こっかそうどういんほう'),
  (913, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 601, 2, FALSE, '満州（中国東北部）に1919年に設置された、南満州鉄道の警備などをになった日本陸軍部隊を何というか。', '', '関東軍', 'かんとうぐん'),
  (914, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 602, 2, FALSE, '清朝最後の皇帝であった（　）が、591に迎えられ、1932年に執政、1934年には皇帝の地位に就いた。', '', '溥儀', 'ふぎ'),
  (915, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 604, 2, FALSE, '1921年に中国で結成され、599が始まると、597が率いる党と協力し、日本に対抗した政党を何というか。', '1949年に中華人民共和国を建国した', '中国共産党', 'ちゅうごくきょうさんとう'),
  (916, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 605, 2, FALSE, '孫文が結成した中国同盟会などを改組して、1919年にできた政党を何というか。', '大衆政党として広く人々に支持された', '中国国民党', 'ちゅうごくこくみんとう'),
  (917, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 606, 2, FALSE, '日本に対抗するために、対立していた604と605が協力体制をとった組織を何というか。', '', '抗日民族統一戦線', 'こうにちみんぞくとういつせんせん'),
  (918, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 607, 2, FALSE, '（　）は3度にわたって首相となり、第1次内閣の1937年に599が始まり、1938年には600を制定して戦時体制を整えた。', '', '近衛文麿', 'このえふみまろ'),
  (919, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 608, 2, FALSE, '1940年に政党や団体を解散させ、国論を統一するために設立された組織を何というか。', '国民生活を統制し、戦争に協力させる役割を果たした', '大政翼賛会', 'たいせいよくさんかい'),
  (920, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 609, 2, FALSE, '戦争の長期化によって不足してきた食料や衣料などの物資を、必要度に応じて配分するために実施された制度を何というか。', '', '配給制', 'はいきゅうせい'),
  (921, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 610, 2, FALSE, '植民地であった朝鮮や台湾における、日本語の使用や神社への参拝の強要などによる日本人同化政策を（　）という。', '', '皇民化政策', 'こうみんかせいさく'),
  (922, '歴史', '第5章 2つの世界大戦と日本', '5. 日本の中国侵略', 611, 2, FALSE, '植民地の朝鮮で、1940年から実施された、朝鮮人の姓名を日本式に改めさせた政策を（　）という。', '', '創氏改名', 'そうしかいめい'),
  (923, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 612, 1, FALSE, '1939年、ドイツがポーランドに侵攻したことをきっかけに始まった、世界を二分した戦争を（　）という。', '', '第二次世界大戦', 'だいにじせかいたいせん'),
  (924, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 613, 1, FALSE, '1941年、アメリカのローズベルト大統領とイギリスのチャーチル首相が会談して発表した、ファシズム打倒をめざすことや戦後の平和構想を示した共同宣言を何というか。', '', '大西洋憲章', 'たいせいようけんしょう'),
  (925, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 614, 1, FALSE, '1940年に枢軸三国が調印した軍事同盟を何というか。', '第三国からの攻撃に対し、相互軍事援助が取り決められた', '日独伊三国同盟', 'にちどくいさんごくどうめい'),
  (926, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 615, 1, FALSE, '1941年、日本とソ連の間で結ばれた条約を何というか。', '日本は北方の安全を確保し、フランス領インドシナ南部へ侵攻するために結んだ', '日ソ中立条約', 'にっそちゅうりつじょうやく'),
  (927, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 616, 1, FALSE, '1941年に首相となり、戦後の極東国際軍事裁判でA級戦犯として戦争責任を追及され、死刑となった軍人・政治家はだれか。', '', '東条英機', 'とうじょうひでき'),
  (928, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 617, 1, FALSE, '（　）は1941年12月8日に始まり、当時の日本では「大東亜戦争」とよばれた。', '1941〜45年まで、日本がアメリカ・イギリスなどと戦った', '太平洋戦争', 'たいへいようせんそう'),
  (929, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 618, 1, FALSE, '617は、日本軍のマレー半島上陸とアメリカ軍基地があったハワイの（　）をきっかけに、アメリカ・イギリスに宣戦して始まった。', '', '真珠湾攻撃', 'しんじゅわんこうげき'),
  (930, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 619, 1, FALSE, '（　）とは、1945年3月26日にアメリカ軍の慶良間列島上陸によって始まった、日本軍とアメリカ軍との戦いをいう。', '', '沖縄戦', 'おきなわせん'),
  (931, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 620, 1, FALSE, '核分裂反応によって生まれる大量のエネルギーを破壊目的に利用した（　）が、1945年8月6日に広島に、8月9日に長崎に投下された。', '', '原子爆弾', 'げんしばくだん'),
  (932, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 621, 1, FALSE, '日本の無条件降伏を勧告する（　）が1945年7月に発表された。8月14日、日本はこれを受け入れ、翌15日に昭和天皇がラジオ放送で国民に発表した。', 'アメリカ・イギリス・中国の名で出された', 'ポツダム宣言', 'ぽつだむせんげん'),
  (933, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 622, 2, FALSE, '612で、日本・ドイツ・イタリア側に属した国々を、対戦したアメリカ・イギリスなどの連合国に対して（　）という。', '', '枢軸国', 'すうじくこく'),
  (934, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 623, 2, FALSE, '1939年、ドイツはイギリス・フランスとの戦いに備えて、ソ連との国境の安全確保を目的に、612の開戦前に（　）を結んだ。', '', '独ソ不可侵条約', 'どくそふかしんじょうやく'),
  (935, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 624, 2, FALSE, 'ドイツのナチスに迫害され、ポーランドに建設されたアウシュビッツ強制収容所などに収容され、殺害された人々を何というか。', '', 'ユダヤ人', 'ゆだやじん'),
  (936, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 625, 2, FALSE, 'ナチスに迫害されていた624に対し、日本通過を認めるビザ（査証）を大量に発行し、多くの624を救った日本人外交官はだれか。', '', '杉原千畝', 'すぎはらちうね'),
  (937, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 626, 2, FALSE, '1941年、フランス領インドシナ南部へ侵攻した日本に対して、アメリカ・イギリス・中国・オランダがとった経済封鎖を何というか。', '', 'ABCD包囲網（ABCD包囲陣）', 'えーびーしーでぃーほういもう（えーびーしーでぃーほういじん）'),
  (938, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 627, 2, FALSE, '日本は、東アジア・東南アジアを欧米の支配から解放し、（　）をつくることを説いた。', '日本を中心とする共存共栄の新秩序建設', '大東亜共栄圏', 'だいとうあきょうえいけん'),
  (939, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 628, 2, FALSE, '1942年6月、（　）で日本は主力航空母艦に壊滅的な打撃を受け、この海戦以後、戦局が大きく転換することになった。', '', 'ミッドウェー海戦', 'みっどうぇーかいせん'),
  (940, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 629, 2, FALSE, '1943年、これまで兵役を猶予されていた文科系の大学生も徴兵されて戦場に送られたことを何というか。', '', '学徒出陣', 'がくとしゅつじん'),
  (941, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 630, 2, FALSE, '労働力不足を補うために、中学生・女学生や未婚の女性を軍需工場で働かせたことを（　）という。', '1945年には国民学校高等科以上は授業停止', '勤労動員', 'きんろうどういん'),
  (942, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 631, 2, FALSE, '空襲の被害を避け、都会の小学生を学校単位などで地方の農村などに避難させたことを何というか。', '', '学童疎開（集団疎開）', 'がくどうそかい（しゅうだんそかい）'),
  (943, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 632, 2, FALSE, '1944年7月、アメリカ軍がサイパン島を占領すると、そこにつくられた基地からB29などの爆撃機が飛び立ち、（　）が頻繁に行われるようになった。', '', '本土空襲（空襲）', 'ほんどくうしゅう（くうしゅう）'),
  (944, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 633, 2, FALSE, '1945年3月10日、東京の下町を中心にB29爆撃機約300機による無差別攻撃が行われ、市街地の大部分が焼け野原となったことを何というか。', '', '東京大空襲', 'とうきょうだいくうしゅう'),
  (945, '歴史', '第5章 2つの世界大戦と日本', '6. 第二次世界大戦と太平洋戦争', 634, 2, FALSE, 'ドイツの戦後処理とソ連の対日参戦などを決定した、アメリカ・イギリス・ソ連の首脳会談を何というか。', '1945年2月に開かれた', 'ヤルタ会談', 'やるたかいだん'),
  (946, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 635, 1, FALSE, '連合国軍が日本占領のために東京に設けた総司令部を何というか。', '占領政策を日本に指令・勧告し、日本政府が実行するという間接統治を行った', '連合国軍最高司令官総司令部（GHQ）', 'れんごうこくぐんさいこうしれいかんそうしれいぶ（じーえいちきゅー）'),
  (947, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 637, 1, FALSE, '国が地主から一定面積以上の土地を強制的に買い上げ、小作人に優先的に安く売り渡す（　）が行われた。', '', '農地改革', 'のうちかいかく'),
  (948, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 638, 1, FALSE, '635は（　）を指示し、日本の帝国主義を支えてきた三井・三菱などに解散を命じた。', '1947年には、独占禁止法が制定された', '財閥解体', 'ざいばつかいたい'),
  (949, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 639, 1, FALSE, '1947年に制定された、9年間の義務教育、男女共学などを規定した、教育に関する法律を何というか。', '', '教育基本法', 'きょういくきほんほう'),
  (950, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 640, 1, FALSE, '第二次世界大戦後に始まった資本主義陣営と社会主義陣営の直接には戦火を交えない国際的緊張状態を何というか。', '', '冷たい戦争（冷戦）', 'つめたいせんそう（れいせん）'),
  (951, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 641, 1, FALSE, '1949年、内戦に勝利した中国共産党が建国した国を正式名称で何というか。', '毛沢東が国家主席、周恩来が首相に就任した', '中華人民共和国', 'ちゅうかじんみんきょうわこく'),
  (952, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 642, 1, FALSE, '1950年、北朝鮮が韓国に侵攻したことから（　）が始まった。', '1953年に休戦協定が結ばれた', '朝鮮戦争', 'ちょうせんせんそう'),
  (953, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 643, 1, FALSE, '642で、アメリカ軍への軍事物資供給によって日本でおきた好景気を何というか。', '日本の経済は戦前の水準にまで回復した', '特需景気', 'とくじゅけいき'),
  (954, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 644, 1, FALSE, '戦後、5度内閣を組織した人物で、サンフランシスコ講和会議に全権として出席し、平和条約を締結したのはだれか。', '', '吉田茂', 'よしだしげる'),
  (955, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 646, 1, FALSE, '645と同時に結ばれた日本とアメリカの条約を何というか。', '', '日米安全保障条約', 'にちべいあんぜんほしょうじょうやく'),
  (956, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 647, 1, FALSE, '635の指令のもとに、1950年に創設された防衛組織を何というか。', '1952年に保安隊、1954年に自衛隊に改組された', '警察予備隊', 'けいさつよびたい'),
  (957, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 648, 1, FALSE, '1956年、鳩山一郎首相が（　）に調印し、日本とソ連の国交回復が実現した。', 'これによって、日本の国際連合加盟が実現した', '日ソ共同宣言', 'にっそきょうどうせんげん'),
  (958, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 649, 1, FALSE, '保守合同によって自由民主党が結党し、自由民主党と日本社会党の2つの政党を軸とする（　）が約40年間続いた。', '1993年の細川護熙内閣の成立で崩壊した', '55年体制', 'ごじゅうごねんたいせい'),
  (959, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 650, 1, FALSE, '1950年代半ばから1970年代前半まで、経済成長率が年平均10％を超える、世界に例のない経済成長が続いたことを（　）という。', '', '高度経済成長', 'こうどけいざいせいちょう'),
  (960, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 651, 1, FALSE, '1973年, アラブ産油国が原油の輸出を制限し, 価格を大幅に値上げしたために起こった, 世界的な経済混乱を何というか。', '', '石油危機(オイルショック)', 'せきゆきき'),
  (961, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 652, 1, FALSE, '1965年に日本と韓国の間に結ばれた, 韓国を朝鮮半島における唯一の合法的な政府と認めた条約を何というか。', '', '日韓基本条約', 'にっかんきほんじょうやく'),
  (962, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 653, 1, FALSE, '1972年, それまでアメリカの統治下にあった( )の日本への返還が実現したが, 県内のアメリカ軍基地は残された。', '在日アメリカ軍基地の約70%がこの県に集中している', '沖縄', 'おきなわ'),
  (963, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 654, 1, FALSE, '1972年, ( )が調印され, 日本と中国との国交が正常化した。', '台湾(中華民国)との国交は断絶された', '日中共同声明', 'にっちゅうきょうどうせいめい'),
  (964, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 655, 1, FALSE, '1978年, 福田赳夫内閣のときに調印された, 中国との平和条約を何というか。', '覇権主義反対, 経済・文化交流の促進などを内容とする', '日中平和友好条約', 'にっちゅうへいわゆうこうじょうやく'),
  (965, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 656, 2, FALSE, 'A級戦犯に対して戦争責任を追及した連合国による裁判を何というか。', '東京裁判ともいう', '極東国際軍事裁判', 'きょくとうこくさいぐんじさいばん'),
  (966, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 657, 2, FALSE, '女性が政治に参加する権利のことを何というか。', '普通選挙法の改正(1945年)まで女性に選挙権はなかった', '女性参政権', 'じょせいさんせいけん'),
  (967, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 658, 2, FALSE, '637によって急激に増加した, 耕作する土地のほとんどを耕作人が所有している農家のことを何というか。', '', '自作農', 'じさくのう'),
  (968, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 659, 2, FALSE, 'アメリカを中心に, 1949年に結成された軍事同盟を何というか。', 'アメリカとヨーロッパ諸国の軍事同盟で, 2021年11月現在, 30か国が加盟している', '北大西洋条約機構(NATO)', 'きたたいせいようじょうやくきこう'),
  (969, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 660, 2, FALSE, 'ソ連を中心に, 1955年に結成された軍事同盟を何というか。', '1991年, ソ連の解体に伴い, この軍事同盟も解体した', 'ワルシャワ条約機構', 'わるしゃわじょうやくきこう'),
  (970, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 661, 2, TRUE, 'イギリスのチャーチルは, ソ連・東ヨーロッパ諸国が西ヨーロッパ諸国に対してとった秘密主義や閉鎖的態度を風刺して「( )」と表現した。', '', '鉄のカーテン', 'てつのカーテン'),
  (971, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 662, 2, FALSE, '1960年はアフリカで17の独立国が誕生したことから, 「( )」と表現される。', 'ナイジェリア・コートジボワール・チャドなどが独立を果たした', 'アフリカの年', 'あふりかのとし'),
  (972, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 663, 2, FALSE, '1955年, 欧米諸国から独立したアジア・アフリカの29か国の代表は, インドネシアで開催した( )で, 平和十原則を発表した。', '', 'アジア・アフリカ会議(バンドン会議)', 'あじあ・あふりかかいぎ'),
  (973, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 664, 2, FALSE, '第二次世界大戦後にユダヤ人がパレスチナに建国したイスラエルと周辺のアラブ諸国との間で4度にわたって行われた戦争を何というか。', '', '中東戦争', 'ちゅうとうせんそう'),
  (974, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 665, 2, FALSE, '南ベトナムでの政府軍と北ベトナムが支援する南ベトナム解放民族戦線の戦いにアメリカが軍事介入した戦争を( )という。', '', 'ベトナム戦争', 'べとなむせんそう'),
  (975, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 666, 2, FALSE, 'アメリカやソ連に対抗するために, ヨーロッパでEEC・ECSC・EURATOMが統合し, 発足した政治・経済統合組織を何というか。', '', 'ヨーロッパ共同体(EC)', 'よーろっぱきょうどうたい'),
  (976, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 667, 2, FALSE, 'キューバにソ連がミサイル基地を建設したことに抗議し, アメリカが海上封鎖を行い, 全面核戦争の緊張が高まったできごとを何というか。', '', 'キューバ危機', 'きゅーばきき'),
  (977, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 668, 2, FALSE, '1954年, 日本のマグロ漁船がアメリカのビキニ環礁での水爆実験で「死の灰」をあび, 乗組員が死亡した事件を何というか。', '', '第五福竜丸事件', 'だいごふくりゅうまるじけん'),
  (978, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 669, 2, FALSE, '668をきっかけに, 原水爆禁止運動が活発化し, 1955年, 第1回( )が広島で開催された。', '核兵器の禁止・被爆者の救済・世界平和の実現をめざす', '原水爆禁止世界大会', 'げんすいばくきんしせかいたいかい'),
  (979, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 670, 1, FALSE, '日米新安全保障条約に対し, 日本が戦争に巻き込まれる可能性があるとしておきた大規模な反対運動を何というか。', '', '安保闘争', 'あんぽとうそう'),
  (980, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 671, 1, FALSE, '1960年, 日米新安全保障条約に調印した首相はだれか。', '衆議院での条約批准を自民党単独で強行採決させると, 670は頂点に達した', '岸信介', 'きしのぶすけ'),
  (981, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 672, 1, FALSE, '国民所得を倍増させることを目標とする「所得倍増」をスローガンに掲げ, 650政策を推進した首相はだれか。', '', '池田勇人', 'いけだはやと'),
  (982, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 673, 1, FALSE, '1964年にアジアで初めて( )が開催され, これに合わせて東海道新幹線がつくられた。', '2021年に2度目の大会が開催された', '東京オリンピック・パラリンピック', ''),
  (983, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 674, 1, FALSE, '650の時期に各地で発生し, 深刻な問題となった公害に対処するために, 1971年に設置された行政機関を何というか。', '2001年, 中央省庁再編に伴い, 省に昇格した', '環境庁', 'かんきょうちょう'),
  (984, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 675, 1, FALSE, '1974年に非核三原則などの政策に対してノーベル平和賞を受賞した政治家はだれか。', '', '佐藤栄作', 'さとうえいさく'),
  (985, '歴史', '第6章 現代の日本と世界', '1. 日本の民主化と世界の動き', 676, 1, FALSE, '1972〜74年にかけて2度内閣を組織し, 中国との国交正常化を行った政治家はだれか。', '「日本列島改造論」を掲げた', '田中角栄', 'たなかかくえい'),
  (986, '歴史', '第6章 現代の日本と世界', '2. 世界の変化と日本の課題', 677, 1, FALSE, '( )はソ連の共産党書記長時代に, 政治・経済改革であるペレストロイカや情報公開のグラスノスチなどの改革を実行した。', '', 'ゴルバチョフ', ''),
  (987, '歴史', '第6章 現代の日本と世界', '2. 世界の変化と日本の課題', 679, 1, FALSE, '東ヨーロッパ諸国の民主化が進む中, 1989年11月, 東ドイツの共産党政権の崩壊をきっかけに, 冷戦の象徴でもあった( )が崩壊した。', '1961年, 東西に二分されたベルリン市内に, 東から西への亡命を阻止するために築かれた', 'ベルリンの壁', 'べるりんのかべ'),
  (988, '歴史', '第6章 現代の日本と世界', '2. 世界の変化と日本の課題', 680, 1, FALSE, '1989年, 679崩壊によって, 西への人口流入が急増して混乱がおきたが, 翌年, ( )が実現した。', '首都はベルリンと定められた', '東西ドイツ統一', 'とうざいどいつとういつ'),
  (989, '歴史', '第6章 現代の日本と世界', '2. 世界の変化と日本の課題', 681, 1, FALSE, '1991年, 保守派のクーデターが失敗に終わり, 政治の主導権がロシアを中心とする各共和国に移り, ( )は解体した。', '', 'ソ連', 'それん'),
  (990, '歴史', '第6章 現代の日本と世界', '2. 世界の変化と日本の課題', 682, 2, FALSE, 'イラクがクウェートに侵攻したことをきっかけに, 1991年, アメリカを中心とした多国籍軍がイラク軍と戦った戦争を何というか。', '', '湾岸戦争', 'わんがんせんそう'),
  (991, '歴史', '第6章 現代の日本と世界', '2. 世界の変化と日本の課題', 683, 2, FALSE, '2001年, 国際テロ組織アルカイダによって( )がおこされ, アメリカは首謀者の引き渡しをアフガニスタンに要求したが, 拒否されたため, アフガニスタンを攻撃した。', '', '同時多発テロ', 'どうじたはつてろ'),
  (992, '歴史', '第6章 現代の日本と世界', '2. 世界の変化と日本の課題', 684, 2, FALSE, '2003年, 大量破壊兵器を保有しているとして, アメリカがイギリスとともにフセイン政権を倒した戦争を何というか。', '', 'イラク戦争', 'いらくせんそう'),
  (993, '歴史', '第6章 現代の日本と世界', '2. 世界の変化と日本の課題', 685, 2, FALSE, '日本とアメリカの間で, 日本の貿易黒字が大きく, アメリカの産業に影響を与えたことによって( )が生じた。', '', '日米貿易摩擦', 'にちべいぼうえきまさつ'),
  (994, '公民', '第1章 現代社会とわたしたちの生活', '1. 現代社会の様子と文化', 1, 1, FALSE, '出生率の低下によって子どもの数が減少し, その一方で, 65歳以上の高齢者の人口に占める割合が高くなった社会を ( ) という。', '', '少子高齢社会', 'しょうしこうれいしゃかい'),
  (995, '公民', '第1章 現代社会とわたしたちの生活', '1. 現代社会の様子と文化', 2, 1, FALSE, '1990年代に急速に普及した, コンピューターを使った世界規模のネットワークを何というか。', '', 'インターネット', ''),
  (996, '公民', '第1章 現代社会とわたしたちの生活', '1. 現代社会の様子と文化', 3, 1, FALSE, '国境を越えた規模でヒト・モノ・カネなどの動きが活発化したことで国境のもつ意味が小さくなり, 世界の一体化が進んだ現象を ( ) という。', '', 'グローバル化 (グローバリゼーション)', ''),
  (997, '公民', '第1章 現代社会とわたしたちの生活', '1. 現代社会の様子と文化', 4, 2, FALSE, '一人の女性が一生に生む子どもの平均人数を ( ) という。', '2.07を下回れば, 人口は減少するとされる', '合計特殊出生率', 'とくしゅ'),
  (998, '公民', '第1章 現代社会とわたしたちの生活', '1. 現代社会の様子と文化', 5, 2, FALSE, 'コンピューターや2などを使った情報と通信に関する技術のことをアルファベット3字で何というか。', '', 'ICT', ''),
  (999, '公民', '第1章 現代社会とわたしたちの生活', '1. 現代社会の様子と文化', 6, 2, FALSE, 'コンピューターなどの情報技術を使いこなせる者と使いこなせない者との間に生じるさまざまな格差のことを何というか。', '', 'デジタルデバイド (情報格差)', ''),
  (1000, '公民', '第1章 現代社会とわたしたちの生活', '2. 現代社会をとらえる見方や考え方', 7, 1, FALSE, '1組の夫婦のみ, または夫婦と未婚の子ども, または一人親と子どもだけの家族のことを ( ) という。', '現在, 家族全体の約60%を占めている', '核家族', 'かく'),
  (1001, '公民', '第1章 現代社会とわたしたちの生活', '2. 現代社会をとらえる見方や考え方', 8, 1, FALSE, '人はそれぞれに尊く, それぞれ個人の価値を認め, 互いに尊重し合うことを何というか。', '個人の尊重ともいう', '個人の尊厳', 'そんげん'),
  (1002, '公民', '第1章 現代社会とわたしたちの生活', '2. 現代社会をとらえる見方や考え方', 9, 1, FALSE, '男性と女性とは, 肉体的・精神的な差はあるが, 人間としての価値に差はなく, ともに等しい人間の尊厳をもつということを何というか。', '', '両性の本質的平等', 'ほんしつてき'),
  (1003, '公民', '第1章 現代社会とわたしたちの生活', '2. 現代社会をとらえる見方や考え方', 10, 1, FALSE, '意見が分かれ, 話し合いによっても決着がつかない場合, 票決を行い, 多数の賛成を得たものを採用する方法を何というか。', '一定の時間で決定することができるが, 少数意見が反映されにくい', '多数決', ''),
  (1004, '公民', '第1章 現代社会とわたしたちの生活', '2. 現代社会をとらえる見方や考え方', 11, 2, FALSE, '日本国憲法の精神に基づいて, 家族関係などが根本的に改められた新しい ( ) が制定された。', '8と9の基本原則に基づく', '民法', ''),
  (1005, '公民', '第1章 現代社会とわたしたちの生活', '2. 現代社会をとらえる見方や考え方', 13, 2, FALSE, 'ある物事に対して, 当事者同士が互いに約束を取り交わすことを ( ) といい, 当事者同士の合意があって初めて成立する。', '', '契約', 'けいやく'),
  (1006, '公民', '第2章 わたしたちの生活と民主政治', '1. 人権のあゆみと憲法', 14, 1, FALSE, 'モンテスキューが「法の精神」で説いた, 国家権力を立法・行政・司法の3つに分け, 相互に抑制し合い, 均衡を保つしくみを ( ) という。', '', '三権分立 (権力分立)', ''),
  (1007, '公民', '第2章 わたしたちの生活と民主政治', '1. 人権のあゆみと憲法', 15, 1, FALSE, '伊藤博文らが起草し, 1889年に発布された, 君主権の強い欽定憲法を何というか。', '主権者は天皇で, 国民の権利は法律の範囲内に制限された', '大日本帝国憲法', 'ていこく'),
  (1008, '公民', '第2章 わたしたちの生活と民主政治', '1. 人権のあゆみと憲法', 16, 1, FALSE, 'ドイツ共和国が1919年に制定し, 社会権を初めて明記した, 当時最も民主的といわれた憲法を何というか。', 'ヒトラーによって無力化された', 'ワイマール憲法', ''),
  (1009, '公民', '第2章 わたしたちの生活と民主政治', '1. 人権のあゆみと憲法', 17, 2, FALSE, '国の最高法規であり, 国の政治の目標や組織の基本を定めたものを何というか。', '現行の日本のものは, 1946年11月3日に公布された', '憲法', ''),
  (1010, '公民', '第2章 わたしたちの生活と民主政治', '1. 人権のあゆみと憲法', 18, 2, FALSE, 'イギリスのジョン王の専制政治に対し, 国王のもつ課税権や逮捕権などを制限することを認めさせた文書を何というか。', '', 'マグナーカルタ (大憲章)', ''),
  (1011, '公民', '第2章 わたしたちの生活と民主政治', '1. 人権のあゆみと憲法', 19, 2, FALSE, 'イギリスの名誉革命のときに, 権利(の)宣言を法律化した ( ) を, 国王に認めさせた。', '議会の国王に対する優位性が示された', '権利 (の) 章典', ''),
  (1012, '公民', '第2章 わたしたちの生活と民主政治', '1. 人権のあゆみと憲法', 20, 2, FALSE, '日本国憲法は, 国民または国民の代表者によって制定された ( ) 憲法である。', '君主が制定した憲法を欽定憲法という', '民定', 'みんてい'),
  (1013, '公民', '第2章 わたしたちの生活と民主政治', '2. 日本国憲法の基本原則', 21, 1, FALSE, '日本国憲法の三大原則の一つで, 主権が国民にあるということを何というか。', '', '国民主権', ''),
  (1014, '公民', '第2章 わたしたちの生活と民主政治', '2. 日本国憲法の基本原則', 22, 1, FALSE, '日本国憲法の三大原則の一つで, 「侵すことのできない永久の権利」として保障されている権利を尊重することを ( ) という。', '', '基本的人権の尊重', ''),
  (1015, '公民', '第2章 わたしたちの生活と民主政治', '2. 日本国憲法の基本原則', 23, 1, FALSE, '大日本帝国憲法では主権者であった ( ) は, 日本国憲法第1条で, 日本国の象徴であり日本国民統合の象徴であると規定された。', '', '天皇', ''),
  (1016, '公民', '第2章 わたしたちの生活と民主政治', '2. 日本国憲法の基本原則', 24, 1, FALSE, '日本国憲法第 ( ) 条で, 日本国憲法の三大原則の一つである平和主義を具体的に規定している。', '', '9 (九)', ''),
  (1017, '公民', '第2章 わたしたちの生活と民主政治', '2. 日本国憲法の基本原則', 25, 1, FALSE, '日本政府は核兵器に対する方針として, 「もたず, つくらず, もちこませず」という ( ) の立場をとっている。', '', '非核三原則', 'ひかく'),
  (1018, '公民', '第2章 わたしたちの生活と民主政治', '2. 日本国憲法の基本原則', 26, 2, FALSE, '( ) には, 衆議院・参議院の各院において総議員の3分の2以上の賛成で国会が発議し, 国民投票で有効投票の過半数の賛成が必要である。', '', '憲法改正', ''),
  (1019, '公民', '第2章 わたしたちの生活と民主政治', '2. 日本国憲法の基本原則', 28, 2, FALSE, '日本国憲法前文と24の条文には, ( ), 戦力の不保持, 交戦権の否認が明記されている。', '武力による威嚇やその行使についても含む', '戦争放棄', 'ほうき'),
  (1020, '公民', '第2章 わたしたちの生活と民主政治', '2. 日本国憲法の基本原則', 29, 2, FALSE, '自国と密接な関係にある国が他国から攻撃された場合, 自国に対する攻撃とみなし, 共同して防衛にあたる権利を何というか。', '', '集団的自衛権', ''),
  (1021, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 30, 1, FALSE, '人間が人間らしく生活するために生まれながらにもっている, 侵すことのできない永久の権利を何というか。', '憲法第11条で規定されている', '基本的人権', ''),
  (1022, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 31, 1, FALSE, '個人が自由に行動することができ, 国家権力に不当に干渉されないことを保障した権利を何というか。', '', '自由権', ''),
  (1023, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 32, 1, FALSE, '国家から干渉されないことを保障し, 個人が自由にものを考え, 思想をもち, それを主張し表現する自由を何というか。', '', '精神の自由', ''),
  (1024, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 33, 1, FALSE, '民主主義の基盤をなす重要な自由で, 個人の考えや思想などを外部に発表できる自由を ( ) という。', '憲法第21条で規定されている', '表現の自由', ''),
  (1025, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 34, 1, FALSE, '正当な理由なしに身体を不当に拘束されない自由を ( ) という。', '31のうち最も基本的な権利とされる', '身体の自由', ''),
  (1026, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 35, 1, FALSE, '資本主義の発展を通じて確保されてきたもので, 個人や企業が自由に経済活動を行うことができる自由を何というか。', '公共の福祉により制限される場合がある', '経済活動の自由', ''),
  (1027, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 36, 1, FALSE, 'すべての国民が差別されず平等に扱われる権利を ( ) といい, 日本国憲法では第14条で法の下の平等が規定されている。', '', '平等権', ''),
  (1028, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 37, 1, FALSE, '女子差別撤廃条約を批准するために ( ) が制定され, 職場における募集・採用・退職などで, 男女の差別的な取り扱いが禁止された。', '', '男女雇用機会均等法', 'こよう'),
  (1029, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 38, 1, FALSE, '男女が対等な立場であらゆる社会活動に参加でき, それぞれが責任をになう社会をつくりあげるための理念・方向を定めた法律を何というか。', '', '男女共同参画社会基本法', 'さんかく'),
  (1030, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 39, 1, FALSE, '障がい者や高齢者が社会生活に参加するうえで生活の支障となる物理的な障害や, 精神的な障壁を取り除くための施策を何というか。', '', 'バリアフリー', ''),
  (1031, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 40, 1, FALSE, '高齢や障がいの有無, 国籍などにかかわらず, すべての人が使いやすいように, 製品などに意図的に施されたデザインを何というか。', '', 'ユニバーサルデザイン', ''),
  (1032, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 41, 1, FALSE, '( ) は, 20世紀になってから確立された, 国に対して人間らしい生活を求める権利である。', '', '社会権', ''),
  (1033, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 43, 1, FALSE, '労働者は一般に雇い主である使用者に対して弱い立場であるため, 憲法第28条で ( ) が認められている。', '労働三権ともいう', '労働基本権', ''),
  (1034, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 44, 1, FALSE, '基本的人権を守るための権利の一つで, 国民が直接または代表者を通じて政治に参加する権利を何というか。', '', '参政権', ''),
  (1035, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 45, 1, FALSE, '満18歳以上のすべての国民に与えられ, 首長, 国や地方公共団体の議員などを投票によって選出することができる権利を何というか。', '', '選挙権', ''),
  (1036, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 46, 1, FALSE, '首長, 国や地方公共団体の議員選挙に立候補することができる権利を ( ) という。', '', '被選挙権', ''),
  (1037, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 47, 1, FALSE, '最高裁判所裁判官が適任かどうかを投票によって審査する権利を何というか。', '投票により過半数が不適任とすると罷免される', '国民審査権', ''),
  (1038, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 48, 1, FALSE, '日本国憲法第12条で「常に ( ) のためにこれを利用する責任を負ふ」と規定している, 社会全体の利益・幸福のことを ( ) という。', '', '公共の福祉', ''),
  (1039, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 50, 1, FALSE, '社会や経済の進展に伴い, 新たに主張されるようになった人権を何というか。', '', '新しい人権', ''),
  (1040, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 51, 1, FALSE, '50の一つで，公害の深刻化とともに主張されるようになった，快適で人間らしい生活環境を求める権利を何というか。', '住宅の日当たりを確保する日照権など', '環境権', 'かんきょうけん'),
  (1041, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 52, 1, FALSE, '国民が，国などがもつ情報の公開を求め，必要な情報を自由に知ることができる権利を何というか。', '国は情報公開法を制定した', '知る権利', ''),
  (1042, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 54, 1, FALSE, '18歳未満の子どもの権利について，国連総会で1989年に採択された条約を何というか。', '', '子ども(児童)の権利条約', ''),
  (1043, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 55, 2, FALSE, '個人がいかなる考えでももつことができ，どのような判断をすることもできる自由を何というか。', '憲法第19条で規定されている', '思想及び良心の自由', 'およ'),
  (1044, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 56, 2, FALSE, 'だれからも強制されずに宗教を信仰できる自由，または宗教を信仰しない自由を何というか。', '憲法第20条で政教分離が規定されている', '信教の自由', ''),
  (1045, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 57, 2, FALSE, 'さまざまな学術研究をしたり，その結果を自由に発表したりする自由を何というか。', '', '学問の自由', ''),
  (1046, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 58, 2, FALSE, '48に反しない限り，だれもが自分が就きたい職業を選ぶことができる自由を何というか。', '', '職業選択の自由', 'せんたく'),
  (1047, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 59, 2, FALSE, '48に反しない限り，住む場所を自らの意思で決めたり，好きなところに移動したりすることができる自由を ( ) という。', '', '居住・移転の自由', ''),
  (1048, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 60, 2, FALSE, '財産の所有，およびそれを自由に利用でき，処分できる権利を国家などが侵害してはならないということを何というか。', '', '財産権の保障(財産権の不可侵)', 'ふかしん'),
  (1049, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 61, 2, FALSE, '( ) とは，被差別部落に住む人々に対する差別や偏見のことで，「解放令」が出された後も差別は解消されず，現在も多くの問題を残している。', '', '部落差別', ''),
  (1050, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 62, 2, FALSE, 'アイヌ民族を先住民族として初めて法的に位置づけ，独自の文化の維持・振興に向けて交付金を出すことを制度化した法律を何というか。', 'アイヌ施策推進法ともいう', 'アイヌ民族支援法', 'しえん'),
  (1051, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 63, 2, FALSE, '高齢者や障がい者を区別することなく，健常者と同じように生活できる社会を築いていこうとする考え方を ( ) という。', '', 'ノーマライゼーション', ''),
  (1052, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 64, 2, FALSE, 'すべての国民が，その能力に応じて，一定水準の知識や技術を身につけるため，( ) が規定されている。', '', '教育を受ける権利', ''),
  (1053, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 65, 2, FALSE, '( ) とは，働く意思と能力がある者が，国に対して労働の機会を要求することができる権利のことをいう。', '', '勤労の権利', ''),
  (1054, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 66, 2, FALSE, '43の一つで，労働者が労働組合を結成したり加入したりする権利を何というか。', '日本国憲法の制定で，労働組合が正式に認められた', '団結権', ''),
  (1055, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 67, 2, FALSE, '43の一つである ( ) は，労働組合が労働条件について使用者と対等な立場で交渉する権利である。', '', '団体交渉権', ''),
  (1056, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 68, 2, FALSE, '43の一つで，団体交渉で労働者と使用者の意見が一致しない場合，労働者がストライキなどの争議行為を行う権利を何というか。', '', '団体行動権(争議権)', ''),
  (1057, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 70, 2, FALSE, '国民が国や地方公共団体に対して，損害の救済や公務員の罷免，法律や命令の制定などについて要望を述べる権利を何というか。', '', '請願権', 'せいがんけん'),
  (1058, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 71, 2, FALSE, '( ) は，30を守るための権利の一つで，30が侵害されたとき，その救済を求める権利である。', '', '請求権', 'せいきゅうけん'),
  (1059, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 72, 2, FALSE, '71の一つで，不当に権利が侵害された場合，公正な裁判を受けることによって救済を求めることができる権利を何というか。', '', '裁判を受ける権利', ''),
  (1060, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 73, 2, FALSE, '71の一つで，公務員の違法行為による損害を受けたとき，その賠償を国や地方公共団体に請求することができる権利を何というか。', '', '国家賠償請求権', 'ばいしょう'),
  (1061, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 74, 2, FALSE, '71の一つで，刑事事件の裁判において無罪となった場合，抑留などに対する補償を国に対して請求することができる権利を何というか。', '', '刑事補償請求権', 'けいじほしょう'),
  (1062, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 75, 2, FALSE, '私生活をみだりに公開されず，他人にわずらわされることなく幸福を追求する権利を何というか。', '情報化の進展やマスメディアの発達で，個人情報が公開される危険がある', 'プライバシーの権利', ''),
  (1063, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 76, 2, FALSE, '情報として蓄えられた個人の秘密が悪用されることを防ぐために，行政機関や企業などに対して情報の適正な取り扱い方法などを義務づけた ( ) が2005年に施行された。', '', '個人情報保護法', ''),
  (1064, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 78, 2, FALSE, '自分の顔や姿(写真や絵画など)を勝手に他人に撮影されたり使用されたりしない権利を ( ) という。', '違法に侵害された場合には，損害賠償を請求することができる', '肖像権', 'しょうぞうけん'),
  (1065, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 79, 2, FALSE, '著作権・特許権などのように，形はないが経済的に大きな価値をもつものに対する権利のことを ( ) という。', '', '知的財産権', ''),
  (1066, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 80, 2, FALSE, 'さまざまな細胞への分化が可能な万能細胞で，再生医療や病気の解明，新薬の開発への応用が期待されている細胞を何というか。', '', 'iPS細胞(人工多能性幹細胞)', 'さいぼう'),
  (1067, '公民', '第2章 わたしたちの生活と民主政治', '3. 日本国憲法と基本的人権', 81, 2, FALSE, '53に拘束力をもたせ，その実現を義務づけるために，1966年の国連総会で採択された国際条約を何というか。', '53には法的拘束力がなかった', '国際人権規約', ''),
  (1068, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 82, 1, FALSE, '国民が自らの意思に従って権力を行使するという政治原理を ( ) (デモクラシー)という。', 'デモクラシーの語源はギリシャ語', '民主主義', ''),
  (1069, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 83, 1, FALSE, '国民が選挙によって代表者を選び，その代表者を通じて政治に参加する制度を ( ) という。', '代議制，議会制民主主義ともよばれる', '間接民主制', ''),
  (1070, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 84, 1, FALSE, '一定年齢に達したすべての人々に選挙権を与え，平等に行われる選挙のことを何というか。', '日本では満18歳以上の男女に選挙権がある', '普通選挙', ''),
  (1071, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 85, 1, FALSE, '選挙を公正に行うために，選挙権や被選挙権，選挙の方法などについて細かく定めた ( ) が1950年に制定された。', '', '公職選挙法', ''),
  (1072, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 86, 1, FALSE, '1選挙区から1名を選出する制度を何というか。', '選挙にかかる費用が少ないとされるが，死票が多くなるという欠点がある', '小選挙区制', ''),
  (1073, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 87, 1, FALSE, '( ) は，政党の得票数に応じて議席を配分する選挙方法である。', '民意を反映しやすいが，小党分立で政局が不安定になる短所がある', '比例代表制', ''),
  (1074, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 88, 1, FALSE, '衆議院議員選挙で導入されている選挙制度で，全国を86と87に分けて国会議員を選ぶしくみを ( ) という。', '', '小選挙区比例代表並立制', ''),
  (1075, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 89, 1, FALSE, '衆議院議員の4年の任期が満了したとき，または，任期の途中で衆議院が解散された場合に行われる選挙を何というか。', '', '衆議院議員選挙(総選挙)', ''),
  (1076, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 90, 1, FALSE, '政治に対して意見や行動を同じにする人々によって組織され，政権を獲得し，政策を実現することを目的に活動をする団体を ( ) という。', '', '政党', ''),
  (1077, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 91, 1, FALSE, '90が議会を通じて政権を握り，その政策を実施する政治のやり方を ( ) という。', '一般に多数の議席を占めた90の党首が内閣を組織する', '政党政治', ''),
  (1078, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 92, 1, FALSE, '議会で多数を占める議員が所属している90が，( ) として内閣をつくり政権を担当する。', '', '与党', 'よとう'),
  (1079, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 93, 1, FALSE, '92と対立する立場で，政府や政権党の政策に対して監視や批判を行う90のことを何というか。', '', '野党', ''),
  (1080, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 94, 1, FALSE, '複数の90が政策協定などを結んで組織する政権(内閣)を ( ) という。', '1党だけで議席の過半数が得られない場合など', '連立政権(連立内閣)', ''),
  (1081, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 95, 1, FALSE, '( ) とは，政治や社会などの問題について，多くの国民に共有されている意見や希望のことである。', '', '世論', 'よろん'),
  (1082, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 96, 2, FALSE, '代表者などを介さずに，すべての国民が直接政治に参加し，その意思を反映させる制度を何というか。', '古代ギリシャの都市国家(ポリス)で行われ，現在もスイスの一部の州で行われている', '直接民主制', ''),
  (1083, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 97, 2, FALSE, 'すべての有権者が，一人一票の投票をする方法で，選挙権をもつ者の一票の価値を平等に扱う選挙を何というか。', '', '平等選挙', ''),
  (1084, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 98, 2, FALSE, '日本の現行の選挙は，有権者が候補者を直接選ぶ ( ) が法律で規定されている。', '', '直接選挙', ''),
  (1085, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 99, 2, FALSE, '選挙の際に，だれがだれに投票したかわからないように，投票の秘密が守られる選挙を何というか。', '無記名投票によって行われる', '秘密選挙', ''),
  (1086, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 100, 2, FALSE, '選挙が公正に行われるように，選挙事務を管理し，これを監督するための独立した機関として，都道府県や市(区)町村に ( ) が置かれている。', '', '選挙管理委員会', ''),
  (1087, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 102, 2, FALSE, '1選挙区から2名以上の代表者を選出する制度を何というか。', '有権者の意見を反映しやすく死票が少ない半面，選挙費用がかかる欠点がある', '大選挙区制', ''),
  (1088, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 103, 2, FALSE, '議員一人あたりの一票の重みが，おもに都市部と農村部で差が生じている状態を何というか。', '3倍を超す格差は違憲であるという判決が出た', '一票の格差', ''),
  (1089, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 104, 2, FALSE, '仕事や旅行などの予定があって投票日に投票できない場合，投票日より前に投票することができる制度を何というか。', '', '期日前投票', ''),
  (1090, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 105, 2, FALSE, '2つの大政党が政権獲得を競い合う91のことを何というか。', 'アメリカ合衆国の共和党と民主党，イギリスの保守党と労働党など', '二党制 (二大政党制)', ''),
  (1091, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 106, 2, FALSE, '90の具体的な政策の数値目標や実施時期などを示し，その政策の実現を約束したものを何というか。', '', '政権公約 (マニフェスト)', ''),
  (1092, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 107, 2, FALSE, 'テレビ・ラジオ・新聞・雑誌などのように，大量の情報を多くの人に伝える伝達手段のことを何というか。', '', 'マスメディア', ''),
  (1093, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 108, 2, FALSE, '107によって，不特定多数の人へ大量の情報を伝達することを何というか。', '95の形成に大きな役割を果たしている', 'マスコミュニケーション (マスコミ)', ''),
  (1094, '公民', '第2章 わたしたちの生活と民主政治', '4. 民主政治と政治参加', 109, 2, FALSE, '自分たちの利益や目的を実現するために，政府や議会，議員に働きかけて影響力を行使しようとする社会集団を何というか。', '日本医師会などがあり，圧力団体ともいわれる', '利益団体', ''),
  (1095, '公民', '第2章 わたしたちの生活と民主政治', '5. 国民主権と国会', 110, 1, FALSE, '国会だけがもつことを規定されている，法を制定する権限を何というか。', '憲法第41条で規定され，国会だけが法律を制定できる', '立法 (権)', ''),
  (1096, '公民', '第2章 わたしたちの生活と民主政治', '5. 国民主権と国会', 111, 1, FALSE, '( )は，日本の国会を構成している2つの議院のうちの一つで，任期は4年，被選挙権は満25歳以上である。', '', '衆議院', ''),
  (1097, '公民', '第2章 わたしたちの生活と民主政治', '5. 国民主権と国会', 112, 1, FALSE, '国会を構成している2つの議院のうちの一つで，任期は6年で3年ごとに半数が改選される議院は( )である。', '', '参議院', ''),
  (1098, '公民', '第2章 わたしたちの生活と民主政治', '5. 国民主権と国会', 113, 1, FALSE, '( )は，次年度の予算審議を議題の中心とする，毎年1月中に召集される国会で，会期は150日間である。', '会期延長の場合もある', '常会 (通常国会)', ''),
  (1099, '公民', '第2章 わたしたちの生活と民主政治', '5. 国民主権と国会', 114, 1, FALSE, '内閣総理大臣の指名を議題の中心とする，111解散後の総選挙の日から30日以内に召集される国会を( )という。', '', '特別会 (特別国会)', ''),
  (1100, '公民', '第2章 わたしたちの生活と民主政治', '5. 国民主権と国会', 115, 1, FALSE, '内閣が必要と認めたときか，いずれかの議院の総議員の4分の1以上の要求があったときに開かれる国会を何というか。', '', '臨時会 (臨時国会)', ''),
  (1101, '公民', '第2章 わたしたちの生活と民主政治', '5. 国民主権と国会', 116, 1, FALSE, '両院の意見が一致しないときに，意見を調整するために開かれる協議会を何というか。', '予算の議決などで一致しないときは必ず開かれる', '両院協議会', ''),
  (1102, '公民', '第2章 わたしたちの生活と民主政治', '5. 国民主権と国会', 117, 1, FALSE, '111が112よりも強い権限を認められていることを何というか。', '任期が短く，解散もあるため，民意を強く反映すると考えられるから', '衆議院の優越', 'ゆうえつ'),
  (1103, '公民', '第2章 わたしたちの生活と民主政治', '5. 国民主権と国会', 118, 1, FALSE, '職務上の義務に違反したり，怠ったりした裁判官の処分を判定するために国会に設けられる裁判所を何というか。', '', '弾劾裁判所', 'だんがい'),
  (1104, '公民', '第2章 わたしたちの生活と民主政治', '5. 国民主権と国会', 119, 1, FALSE, '衆参各議院の総議員の3分の2以上の賛成で国会が( )をし，その後に行われる国民投票で有効投票の過半数の賛成があれば承認される。', '', '憲法改正の発議', 'はつぎ'),
  (1105, '公民', '第2章 わたしたちの生活と民主政治', '5. 国民主権と国会', 120, 2, FALSE, '日本の国会のように，議会が2つの議院で構成されている制度を何というか。', '議案を慎重に審議できる一方，審議に時間がかかるという欠点もある', '二院制 (両院制)', ''),
  (1106, '公民', '第2章 わたしたちの生活と民主政治', '5. 国民主権と国会', 121, 2, FALSE, '111の解散中，緊急の問題がおきたときに内閣の要求によって召集されるものを112の( )という。', '', '緊急集会', ''),
  (1107, '公民', '第2章 わたしたちの生活と民主政治', '5. 国民主権と国会', 122, 2, FALSE, '111または112で，それぞれの全所属議員の出席によって開かれる会議を何というか。', '原則として公開されることになっている', '本会議', ''),
  (1108, '公民', '第2章 わたしたちの生活と民主政治', '5. 国民主権と国会', 123, 2, FALSE, '122での審議に先立ち，議案について調査・審議するために少数の国会議員で構成される機関を何というか。', '', '委員会', ''),
  (1109, '公民', '第2章 わたしたちの生活と民主政治', '5. 国民主権と国会', 124, 2, FALSE, '123での審議の際，国民の関心が高い案件について，利害関係者や専門家を招いて意見を聞く会を何というか。', '予算審議などでは必ず開かれる', '公聴会', 'こうちょう'),
  (1110, '公民', '第2章 わたしたちの生活と民主政治', '5. 国民主権と国会', 125, 2, FALSE, '111が112よりも先に，予算を審議・議決することができる権限を( )という。', '117の一つ。憲法第60条で規定されている', '予算先議権', ''),
  (1111, '公民', '第2章 わたしたちの生活と民主政治', '5. 国民主権と国会', 129, 2, FALSE, '衆参両院にそれぞれ認められている，政治に関して調査することができる権限を( )という。', '必要に応じて，証人をよんだり，記録の提出を要求したりできる', '国政調査権', ''),
  (1112, '公民', '第2章 わたしたちの生活と民主政治', '6. 行政のはたらきと内閣', 130, 1, FALSE, '国会で決められた法律や予算に基づいて，国の政策を実際に進めることを何というか。', '', '行政', ''),
  (1113, '公民', '第2章 わたしたちの生活と民主政治', '6. 行政のはたらきと内閣', 131, 1, FALSE, '( )は，130の最高機関で，これと関連する機関を合わせて政府とよぶ。', '法律の執行，条約の締結，予算の作成などを行う', '内閣', ''),
  (1114, '公民', '第2章 わたしたちの生活と民主政治', '6. 行政のはたらきと内閣', 132, 1, FALSE, '131の首長で，国会議員の中から国会によって指名され，天皇によって任命される役職を何というか。', '', '内閣総理大臣 (首相)', 'しゅしょう'),
  (1115, '公民', '第2章 わたしたちの生活と民主政治', '6. 行政のはたらきと内閣', 133, 1, FALSE, '憲法や法律で決められたことを実施するために，131が制定する命令を( )という。', '原則的に罰則を設けることはできない', '政令', ''),
  (1116, '公民', '第2章 わたしたちの生活と民主政治', '6. 行政のはたらきと内閣', 134, 1, FALSE, '131が国会の信任に基づいてつくられ，国会に対して連帯して責任を負う制度を( )という。', '', '議院内閣制', ''),
  (1117, '公民', '第2章 わたしたちの生活と民主政治', '6. 行政のはたらきと内閣', 135, 1, FALSE, '134のもとでは，衆議院で( )が可決されると，131は10日以内に衆議院を解散するか，総辞職しなければならない。', '', '内閣不信任の決議', ''),
  (1118, '公民', '第2章 わたしたちの生活と民主政治', '6. 行政のはたらきと内閣', 136, 1, FALSE, '( )が行われた場合，40日以内に総選挙が行われ，総選挙後30日以内に召集される特別会で新しい132が指名されることになる。', '', '衆議院の解散', ''),
  (1119, '公民', '第2章 わたしたちの生活と民主政治', '6. 行政のはたらきと内閣', 137, 1, FALSE, '130の仕事を整理・縮小して，無駄のない効率的な130をめざして行われる改革を( )といい，地方分権などが進められている。', '', '行政改革', ''),
  (1120, '公民', '第2章 わたしたちの生活と民主政治', '6. 行政のはたらきと内閣', 138, 1, FALSE, '137の一環として進められている，民間に対する許認可権を見直して，経済活動の規制を緩め，市場に参入しやすくすることを( )という。', '', '規制緩和', 'かんわ'),
  (1121, '公民', '第2章 わたしたちの生活と民主政治', '6. 行政のはたらきと内閣', 139, 2, FALSE, '132が任免権をもっている，各省庁の長を何というか。', '過半数は国会議員から選ばれ，すべてが文民でなければならない', '国務大臣', ''),
  (1122, '公民', '第2章 わたしたちの生活と民主政治', '6. 行政のはたらきと内閣', 140, 2, FALSE, '非公開ですべての139が出席し，決定は全会一致とする，131の意思決定会議を( )という。', '', '閣議', ''),
  (1123, '公民', '第2章 わたしたちの生活と民主政治', '6. 行政のはたらきと内閣', 141, 2, TRUE, '国の行政機関が制定し，国民を拘束する法を総称して何というか。', '133や内閣府令・省令などがある', '命令', ''),
  (1124, '公民', '第2章 わたしたちの生活と民主政治', '6. 行政のはたらきと内閣', 142, 2, TRUE, '参議院において，政府や大臣の責任を問うための決議案を( )という。', '可決された場合でも政府や大臣に対する法的拘束力はない', '問責決議案', 'もんせき'),
  (1125, '公民', '第2章 わたしたちの生活と民主政治', '6. 行政のはたらきと内閣', 143, 2, FALSE, '特別会が召集されたときに，132とすべての139が辞職することを何というか。', '自らが政権を維持できないと判断した場合もある', '総辞職', ''),
  (1126, '公民', '第2章 わたしたちの生活と民主政治', '6. 行政のはたらきと内閣', 144, 2, FALSE, '( )は，役所の職員や警察官など行政機関で働く職員で，国民全体に奉仕しなければならないとされている。', '', '公務員', ''),
  (1127, '公民', '第2章 わたしたちの生活と民主政治', '6. 行政のはたらきと内閣', 145, 2, FALSE, '130の仕事が増えて，内容も複雑になり，130にかかわる権限が大きくなっていることを何というか。', '', '行政権の拡大', ''),
  (1128, '公民', '第2章 わたしたちの生活と民主政治', '6. 行政のはたらきと内閣', 146, 2, TRUE, '国が管理・運営していた大学・博物館・病院などの事業を分離して法人化した機関を( )という。', '', '独立行政法人', ''),
  (1129, '公民', '第2章 わたしたちの生活と民主政治', '6. 行政のはたらきと内閣', 147, 2, FALSE, '国家のはたらきを，社会秩序を守るための治安維持と国防に限定するなど，最小限にとどめた政府のことを何というか。', '社会保障費の削減などにつながる', '小さな政府', ''),
  (1130, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 148, 1, FALSE, '社会生活から生まれる争いごとを，法律を適用して判断を下し解決することを何というか。', '', '司法', ''),
  (1131, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 149, 1, FALSE, '国会が制定した法律や，命令・規則・処分などが憲法に違反していないかどうかを，裁判所が判断する権限を( )という。', '憲法第81条で規定されている。法令審査権ともいう', '違憲立法審査権 (違憲審査権)', 'いけんしんさ'),
  (1132, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 150, 1, FALSE, '( )は，最も上位に位置する裁判所で，長官と14名の裁判官により構成される。', '憲法の番人ともいわれる', '最高裁判所', ''),
  (1133, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 151, 1, FALSE, 'おもに第二審の裁判を行う裁判所で、東京・大阪・名古屋・広島・福岡・仙台・札幌・高松の8か所に設置されているのは ( ) である。', '', '高等裁判所', ''),
  (1134, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 152, 1, FALSE, '裁判を慎重・公正に行うため、国民は、一つの事件につき原則として3回まで裁判を受けられる制度を ( ) という。', '', '三審制', 'さんしんせい'),
  (1135, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 153, 1, FALSE, '裁判において、第一審の判決に不服のある場合に第二審を求めることを ( ) という。', '', '控訴', 'こうそ'),
  (1136, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 154, 1, FALSE, '裁判において、第二審の判決に不服がある場合に第三審を求めることを ( ) という。', '', '上告', 'じょうこく'),
  (1137, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 155, 1, FALSE, '他人の生命などの権利を侵した者を調べて、法律の定める刑罰を科す裁判を ( ) という。', '', '刑事裁判', 'けいじさいばん'),
  (1138, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 156, 1, FALSE, '被疑者を調べて、裁判所に対して裁判を提起するかどうかを決定する国家公務員を何というか。', '', '検察官', ''),
  (1139, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 157, 1, FALSE, '155において、犯罪を犯した疑いのある人を156が裁判所に裁判を提起することを ( ) という。', '', '起訴', ''),
  (1140, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 158, 1, FALSE, 'くじで選ばれた国民が重大な刑事事件の裁判に参加し、裁判官とともに裁判をする制度を何というか。', '', '裁判員制度', ''),
  (1141, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 159, 2, FALSE, '原則的に第一審と、民事事件の簡易裁判所の判決に対する第二審を行う裁判所を何というか。', '各都府県に1か所、北海道に4か所設置', '地方裁判所', ''),
  (1142, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 160, 2, FALSE, '家庭事件の調停・審判や少年事件などを扱う裁判所を何というか。', '159と同じ所に設置されている', '家庭裁判所', ''),
  (1143, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 162, 2, FALSE, '161において、訴えをおこした人を何というか。', '', '原告', ''),
  (1144, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 163, 2, FALSE, '161において、訴えをおこされた人を何というか。', '', '被告', 'ひこく'),
  (1145, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 164, 2, FALSE, '行政機関の行為によって不当に権利が侵害された場合、国や地方公共団体を相手どって裁判を行い、被害の救済を求める裁判を何というか。', '', '行政裁判', ''),
  (1146, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 165, 2, FALSE, '155において、罪を犯した疑いがあるとして157された者を何というか。', '有罪判決が出るまでは無罪と推定される', '被告人', ''),
  (1147, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 166, 2, FALSE, '162や163、その関係者などの依頼によって訴訟に関する活動を行う、国家資格をもつ法律の専門家を何というか。', '', '弁護士', ''),
  (1148, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 167, 2, FALSE, '警察官・156による取り調べや裁判の際に、自分に不利な供述をしなくてもよい権利を何というか。', '', '黙秘権', 'もくひけん'),
  (1149, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 168, 2, FALSE, '155で罪を犯していないのに、疑われたり刑罰を受けたりすることを何というか。', '', '冤罪', 'えんざい'),
  (1150, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 169, 2, FALSE, '判決が確定した後に新しい証拠が出るなどして、裁判に重大な誤りがあったと判断された場合に、裁判をやり直す制度を何というか。', '', '再審制度', ''),
  (1151, '公民', '第2章 わたしたちの生活と民主政治', '7. 司法権の独立と裁判所', 170, 2, FALSE, '民事・刑事に関するトラブルを解決するために必要な法的な情報・サービスの提供などを行う日本司法支援センターを愛称で何というか。', '', '法テラス', ''),
  (1152, '公民', '第2章 わたしたちの生活と民主政治', '8. 地方自治', 171, 1, FALSE, '( ) とは、地域の住民が自らの意思によって、地域の実情に合った政治を自主的に行うことである。', '「民主主義の学校」といわれる', '地方自治', ''),
  (1153, '公民', '第2章 わたしたちの生活と民主政治', '8. 地方自治', 172, 1, FALSE, '国がもつ権限の多くを地方に移すことを ( ) といい、国との関係を「上下関係」から「対等・協力関係」に改めようとしている。', '', '地方分権', ''),
  (1154, '公民', '第2章 わたしたちの生活と民主政治', '8. 地方自治', 173, 1, FALSE, '171が行われる個々の地域社会を単位とする、国から一定の範囲の自治権を与えられて行政を行う団体を ( ) という。', '都道府県や市(区)町村など', '地方公共団体（地方自治体）', ''),
  (1155, '公民', '第2章 わたしたちの生活と民主政治', '8. 地方自治', 174, 1, FALSE, '法律の範囲内で地方議会が制定することができる、その地域内に適用される法を ( ) という。', '', '条例', ''),
  (1156, '公民', '第2章 わたしたちの生活と民主政治', '8. 地方自治', 177, 1, FALSE, '一定の署名数を集めることで、住民が地方の政治に直接参加できる権利を何というか。', '', '直接請求権', ''),
  (1157, '公民', '第2章 わたしたちの生活と民主政治', '8. 地方自治', 178, 1, FALSE, '地方議会の解散や首長の解職、特別法の制定などについて、住民の意思を問うために行われる投票を何というか。', 'レファレンダム', '住民投票', ''),
  (1158, '公民', '第2章 わたしたちの生活と民主政治', '8. 地方自治', 179, 2, FALSE, '173の行政の最高責任者で、執行機関の長を何というか。', '任期は4年で、被選挙権は都道府県知事が満30歳以上、市(区)町村長は満25歳以上', '首長', ''),
  (1159, '公民', '第2章 わたしたちの生活と民主政治', '8. 地方自治', 180, 2, FALSE, '179・地方議員という2種類の代表を住民の直接選挙で選ぶ制度を ( ) という。', '', '二元代表制', ''),
  (1160, '公民', '第2章 わたしたちの生活と民主政治', '8. 地方自治', 181, 2, FALSE, '一院制の173の議決機関を何というか。', '議員は住民の直接選挙で選出され、任期は4年、被選挙権は満25歳以上である', '地方議会', ''),
  (1161, '公民', '第2章 わたしたちの生活と民主政治', '8. 地方自治', 182, 2, FALSE, '174の制定・改廃の請求は、有権者の ( ) 以上の署名によって179に請求し、179が議会にかけ、その結果を公表する。', '', '50分の1', ''),
  (1162, '公民', '第2章 わたしたちの生活と民主政治', '8. 地方自治', 183, 2, FALSE, '179・議員の ( ) は、有権者の3分の1以上*の署名が必要である。', 'リコール (*有権者数が40万人以下の場合)', '解職請求', ''),
  (1163, '公民', '第2章 わたしたちの生活と民主政治', '8. 地方自治', 184, 2, FALSE, '( ) とは、行政に対する苦情を、中立的な立場から調査し、行政を監視する制度である。', 'スウェーデンで始まった制度。日本では1990年に神奈川県川崎市で初めて導入された', 'オンブズマン制度', ''),
  (1164, '公民', '第3章 わたしたちの生活と経済', '1. 生活と経済', 185, 1, FALSE, '家庭を維持するために収入と支出を運営する経済活動を何というか。', '収入を得て財やサービスを購入し、消費生活を行うことで成り立つ', '家計', ''),
  (1165, '公民', '第3章 わたしたちの生活と経済', '1. 生活と経済', 186, 1, FALSE, '財やサービスの量が、求められている量に対して不足している状態を ( ) があるという。', '', '希少性', ''),
  (1166, '公民', '第3章 わたしたちの生活と経済', '1. 生活と経済', 187, 1, FALSE, '将来の生活設計や予定外の支出に備えて、収入の一部を銀行などに預けることを何というか。', '銀行預金、生命保険料などがある', '貯蓄', ''),
  (1167, '公民', '第3章 わたしたちの生活と経済', '1. 生活と経済', 189, 1, FALSE, '製造物の欠陥が原因で消費者が被害を受けた場合、製造者に過失がなくても、損害賠償の責任を負うものとする法律を何というか。', '1995年から施行された。PL法ともいう', '製造物責任法', ''),
  (1168, '公民', '第3章 わたしたちの生活と経済', '1. 生活と経済', 190, 1, FALSE, '消費者保護基本法を改正して成立した法律を何というか。', '消費者被害を防ぎ、消費者の自立を支援することなどを規定', '消費者基本法', ''),
  (1169, '公民', '第3章 わたしたちの生活と経済', '1. 生活と経済', 191, 1, FALSE, '商品を購入する契約を結んでも、一定期間以内であれば、書面によって無条件で契約を取り消すことができる制度を ( ) という。', '', 'クーリング・オフ', ''),
  (1170, '公民', '第3章 わたしたちの生活と経済', '1. 生活と経済', 192, 1, FALSE, '生産された商品が、多くの人手を経て次々と流れていき、消費者に届くまでの流れのことを何というか。', '', '流通', ''),
  (1171, '公民', '第3章 わたしたちの生活と経済', '1. 生活と経済', 193, 1, FALSE, '生産者から商品を大量に仕入れ、それを小売業者などに販売する事業のことを ( ) という。', '', '卸売業', 'おろしうりぎょう'),
  (1172, '公民', '第3章 わたしたちの生活と経済', '1. 生活と経済', 194, 2, FALSE, '( ) とは、人間が生活するうえで不可欠、または人間に満足を与えるもので、形のある商品のことをいう。', '', '財', ''),
  (1173, '公民', '第3章 わたしたちの生活と経済', '1. 生活と経済', 195, 2, FALSE, '会社などに勤め、労働を提供することによって受け取る賃金や給料のことを ( ) という。', '勤労所得ともいう', '給与所得', ''),
  (1174, '公民', '第3章 わたしたちの生活と経済', '1. 生活と経済', 196, 2, FALSE, '自分がもっている財産を利用することによって得る収入のことを何というか。', '地代・家賃・利子・配当などがこれにあたる', '財産所得', ''),
  (1175, '公民', '第3章 わたしたちの生活と経済', '1. 生活と経済', 197, 2, FALSE, '毎日の生活をするために、実際に消費に使う支出のことを何というか。', '食料費や住居費などがあてはまり、185の支出の中心になる部分である', '消費支出', ''),
  (1176, '公民', '第3章 わたしたちの生活と経済', '1. 生活と経済', 198, 2, FALSE, '個人所得から税金や社会保険料を差し引いたものを ( ) という。', '個人が自由に使うことができるお金', '可処分所得', ''),
  (1177, '公民', '第3章 わたしたちの生活と経済', '1. 生活と経済', 199, 2, FALSE, '2001年に施行された、虚偽の説明による契約などを対象とした ( ) は、虚偽だと気づいてから6か月以内ならば契約を取り消すことができると規定している。', '', '消費者契約法', ''),
  (1178, '公民', '第3章 わたしたちの生活と経済', '1. 生活と経済', 200, 2, FALSE, '消費者行政を一元化し、消費者の視点から政策全般を監視するため、2009年に設置された国の行政機関を何というか。', '', '消費者庁', ''),
  (1179, '公民', '第3章 わたしたちの生活と経済', '1. 生活と経済', 201, 2, FALSE, '消費者が自分の意思と判断で商品を購入し，消費者によって企業の生産のあり方が決められるという考え方を何というか。', '', '消費者主権', ''),
  (1180, '公民', '第3章 わたしたちの生活と経済', '1. 生活と経済', 202, 2, FALSE, 'アメリカ合衆国のケネディ大統領が唱えた( )とは，「安全を求める権利」「知らされる権利」「選択する権利」「意見を反映させる権利」の4つである。', '', '消費者の4つの権利', ''),
  (1181, '公民', '第3章 わたしたちの生活と経済', '2. 生産のしくみと企業', 203, 1, FALSE, '企業が生産を行う際に，原材料や機械などを整えるための元手となる資金のことを何というか。', '機械などの生産用具のことを資本財ともいう', '資本', ''),
  (1182, '公民', '第3章 わたしたちの生活と経済', '2. 生産のしくみと企業', 204, 1, FALSE, '商品の売り上げから，生産にかかった原材料費や賃金などの経費を差し引いた残りを( )という。', '', '利潤', 'りじゅん'),
  (1183, '公民', '第3章 わたしたちの生活と経済', '2. 生産のしくみと企業', 205, 1, FALSE, '公共の利益のために，国や地方公共団体などが経営する企業を何というか。', '国営企業，地方公営企業，独立行政法人などがある', '公企業', 'こうきぎょう'),
  (1184, '公民', '第3章 わたしたちの生活と経済', '2. 生産のしくみと企業', 206, 1, FALSE, '民間が204を得ることを最大の目的に経営する企業を何というか。', '日本の企業の大部分を占めている', '私企業', 'しきぎょう'),
  (1185, '公民', '第3章 わたしたちの生活と経済', '2. 生産のしくみと企業', 207, 1, FALSE, '203を少額の株式に分けて発行し，株式を購入する出資者を広く集めて組織した会社を( )という。', '大企業のほとんどが207である', '株式会社', ''),
  (1186, '公民', '第3章 わたしたちの生活と経済', '2. 生産のしくみと企業', 208, 1, FALSE, '株式を購入し，207に資金を提供した個人・法人を( )という。', '会社が倒産した場合，出資額の範囲内でその損失を負担する', '株主', ''),
  (1187, '公民', '第3章 わたしたちの生活と経済', '2. 生産のしくみと企業', 209, 1, FALSE, '207が利益をあげた場合に，出資者へその一部を分配するものを何というか。', '出資者は，その出資額に応じた金額を受け取る', '配当', 'はいとう'),
  (1188, '公民', '第3章 わたしたちの生活と経済', '2. 生産のしくみと企業', 210, 2, FALSE, '資本家が労働者を雇い，204をあげることを目的に商品を生産する経済体制を何というか。', '', '資本主義経済', ''),
  (1189, '公民', '第3章 わたしたちの生活と経済', '2. 生産のしくみと企業', 211, 2, FALSE, '生産を行うために必要な，土地・労働力・203・原材料などのことを何というか。', '土地・労働力・203を生産の三要素という。近年，特許などの知的資源も重要視されている', '生産要素', ''),
  (1190, '公民', '第3章 わたしたちの生活と経済', '2. 生産のしくみと企業', 212, 2, FALSE, '回収した204の一部を再投資などにあて，より大きな規模で生産を繰り返すことを( )という。', '', '拡大再生産', ''),
  (1191, '公民', '第3章 わたしたちの生活と経済', '2. 生産のしくみと企業', 213, 2, FALSE, 'すべての208で構成され，経営方針の決定や取締役の選任などを行う207の最高議決機関を何というか。', '株式1単元につき1票の議決権があるので，株式を多く所有する208の意向が強くなる', '株主総会', ''),
  (1192, '公民', '第3章 わたしたちの生活と経済', '2. 生産のしくみと企業', 215, 2, FALSE, '豊富な資金と大規模な設備を使い，多くの労働者を雇って生産活動を行っている企業を何というか。', '', '大企業', ''),
  (1193, '公民', '第3章 わたしたちの生活と経済', '2. 生産のしくみと企業', 216, 2, FALSE, '日本の企業の約99%を占めている( )は，生産性・賃金・資本金などの面で215との間に大きな格差がある。', '下請け企業が多い', '中小企業', ''),
  (1194, '公民', '第3章 わたしたちの生活と経済', '2. 生産のしくみと企業', 217, 2, FALSE, '高度な専門知識や新しい技術をもとに，創造的・冒険的な新規事業に取り組む革新的な企業を( )という。', '新しく会社をおこすことを起業という', 'ベンチャー企業', ''),
  (1195, '公民', '第3章 わたしたちの生活と経済', '2. 生産のしくみと企業', 218, 2, FALSE, '企業が新しい商品を開発・生産したり，技術を開発したりすることを( )という。', '新市場の開拓や生産方式・経営方式の改革なども含まれる', '技術革新(イノベーション)', ''),
  (1196, '公民', '第3章 わたしたちの生活と経済', '2. 生産のしくみと企業', 219, 2, FALSE, '企業が社会の一員として，社会的貢献を果たさなければならない責任を負っていることを，アルファベット3字で何というか。', '企業は204の追求ばかりでなく，社会の一員としてふさわしい行動をとることが求められる', 'CSR', ''),
  (1197, '公民', '第3章 わたしたちの生活と経済', '3. 働くことの意義と労働者の権利', 221, 1, FALSE, '労働者に対する，労働条件の最低の基準を定めた法律を何というか。', '1日8時間労働，満15歳未満の児童の労働禁止などを規定している', '労働基準法', ''),
  (1198, '公民', '第3章 わたしたちの生活と経済', '3. 働くことの意義と労働者の権利', 222, 1, FALSE, '労働者の団結権や団体交渉など，労働組合の活動について規定した法律を何というか。', '公務員などには労働三権の一部が禁止されているものもある', '労働組合法', ''),
  (1199, '公民', '第3章 わたしたちの生活と経済', '3. 働くことの意義と労働者の権利', 223, 1, FALSE, '労働者が自主的につくり，労働条件の改善や労働者の経済的・社会的な地位の向上をめざす団体を何というか。', '日本では企業別の組織が多い', '労働組合', ''),
  (1200, '公民', '第3章 わたしたちの生活と経済', '3. 働くことの意義と労働者の権利', 224, 1, FALSE, '労働争議の予防や早期解決を目的として制定された法律を( )という。', '争議の斡旋・調停・仲裁の方法などを規定している', '労働関係調整法', ''),
  (1201, '公民', '第3章 わたしたちの生活と経済', '3. 働くことの意義と労働者の権利', 225, 1, FALSE, '一度採用したら定年まで雇い続ける日本の雇用制度の特徴の一つを( )という。', 'リストラや非正規労働者などの増加により崩れつつある', '終身雇用', 'しゅうしんこよう'),
  (1202, '公民', '第3章 わたしたちの生活と経済', '3. 働くことの意義と労働者の権利', 226, 1, FALSE, '仕事と育児・介護の両立を支援するため，1995年に制定された法律を何というか。', '', '育児・介護休業法', 'いくじ・かいごきゅうぎょうほう'),
  (1203, '公民', '第3章 わたしたちの生活と経済', '3. 働くことの意義と労働者の権利', 227, 1, FALSE, '( )とは，「仕事と生活の調和」と訳されることばで，仕事と，家庭や地域での生活がバランスよく調和していることをいう。', '', 'ワーク・ライフ・バランス', ''),
  (1204, '公民', '第3章 わたしたちの生活と経済', '3. 働くことの意義と労働者の権利', 228, 2, FALSE, '日本の雇用制度の特徴の一つで，勤続年数により賃金や地位が上がっていく制度を何というか。', '年俸制の導入などにより崩れつつある', '年功序列', ''),
  (1205, '公民', '第3章 わたしたちの生活と経済', '3. 働くことの意義と労働者の権利', 229, 2, FALSE, 'バブル崩壊後から導入が進んだ，仕事の成果に応じて賃金を支払ったり，昇格を決めたりする方法を何というか。', '', '成果主義', ''),
  (1206, '公民', '第3章 わたしたちの生活と経済', '3. 働くことの意義と労働者の権利', 230, 2, FALSE, 'パートタイム労働者や派遣労働者，契約労働者などの正社員ではない労働者を何というか。', '2020年の統計では，全労働者の約4割を占めている', '非正規労働者', ''),
  (1207, '公民', '第3章 わたしたちの生活と経済', '3. 働くことの意義と労働者の権利', 231, 2, FALSE, '不況による人員整理や希望退職の募集，解雇を意味することが多いことばは何か。', '本来は事業の再構築という意味である', 'リストラ', ''),
  (1208, '公民', '第3章 わたしたちの生活と経済', '3. 働くことの意義と労働者の権利', 232, 2, FALSE, '正式名称を公共職業安定所といい，求職者に無料で職業を紹介したり，雇用保険に関する事務なども行っている行政機関を何というか。', '', 'ハローワーク', ''),
  (1209, '公民', '第3章 わたしたちの生活と経済', '3. 働くことの意義と労働者の権利', 233, 2, FALSE, '雇用を確保し，失業者を減らすため，1人あたりの労働時間を減らして，仕事を多くの人で分かち合うことを何というか。', '', 'ワークシェアリング', ''),
  (1210, '公民', '第3章 わたしたちの生活と経済', '3. 働くことの意義と労働者の権利', 234, 2, FALSE, '男女を問わず，性的いやがらせによって，仕事上の不利益を与えたり，職場環境を悪化させたりすることを何というか。', '', 'セクシュアルハラスメント', ''),
  (1211, '公民', '第3章 わたしたちの生活と経済', '3. 働くことの意義と労働者の権利', 235, 2, FALSE, '情報通信技術(ICT)を活用し，自宅や共有オフィスなどで仕事をする勤務形態を( )という。', '', 'テレワーク', ''),
  (1212, '公民', '第3章 わたしたちの生活と経済', '4. 市場経済と価格のはたらき', 236, 1, FALSE, '売り手と買い手がいて，商品やサービスの取り引きが行われる場を何というか。', '', '市場', 'しじょう'),
  (1213, '公民', '第3章 わたしたちの生活と経済', '4. 市場経済と価格のはたらき', 237, 1, FALSE, 'ある商品を買う買い手が一定の価格で買おうとする量を( )といい，価格が上がれば減少し，価格が下がれば増加する。', '', '需要量', 'じゅようりょう'),
  (1214, '公民', '第3章 わたしたちの生活と経済', '4. 市場経済と価格のはたらき', 238, 1, FALSE, 'ある商品を売り手が一定の価格で売ろうとする量を何というか。', '価格が上がれば増加し，価格が下がれば減少する', '供給量', 'きょうきゅうりょう'),
  (1215, '公民', '第3章 わたしたちの生活と経済', '4. 市場経済と価格のはたらき', 239, 1, FALSE, '236において，237と238の関係で変化する価格を何というか。', '237が238を上回れば価格は上がり，反対の場合には価格は下がる', '市場価格', ''),
  (1216, '公民', '第3章 わたしたちの生活と経済', '4. 市場経済と価格のはたらき', 241, 1, FALSE, '企業の自由競争を維持し，消費者の利益を守ることを目的に制定された法律を何というか。', '', '独占禁止法', 'どくせんきんしほう'),
  (1217, '公民', '第3章 わたしたちの生活と経済', '4. 市場経済と価格のはたらき', 242, 1, FALSE, '日常生活に欠かせないもので，その値上がりが家庭や企業に大きな影響をおよぼす財やサービスの価格を何というか。', '電気・ガス料金など', '公共料金', ''),
  (1218, '公民', '第3章 わたしたちの生活と経済', '4. 市場経済と価格のはたらき', 243, 2, FALSE, '財やサービスの価格が，236での自由な取り引きによって決定し，その価格に応じて生産量や購入量が決定する経済のしくみを何というか。', '', '市場経済', ''),
  (1219, '公民', '第3章 わたしたちの生活と経済', '4. 市場経済と価格のはたらき', 244, 2, FALSE, '商品と交換される貨幣の分量をその商品の( )という。', '一つ一つの商品につけられている値段のこと', '価格', ''),
  (1220, '公民', '第3章 わたしたちの生活と経済', '4. 市場経済と価格のはたらき', 245, 2, FALSE, '個人あるいは一つの企業が，商品の生産や販売市場を支配している状態を( )という。', '', '独占', ''),
  (1221, '公民', '第3章 わたしたちの生活と経済', '4. 市場経済と価格のはたらき', 246, 2, FALSE, '売り手が245の状態にあるとき，売り手が自らの判断で決定する価格を( )という。', '', '独占価格', ''),
  (1222, '公民', '第3章 わたしたちの生活と経済', '4. 市場経済と価格のはたらき', 247, 2, FALSE, '( )は，241を運用するために設けられた行政委員会で，1947年に発足した。', '', '公正取引委員会', ''),
  (1223, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 248, 1, FALSE, '資金に余裕のあるところから，資金を必要とするところに対して，資金を融通することを何というか。', '', '金融', 'きんゆう'),
  (1224, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 249, 1, FALSE, '日本の中央銀行で，国の金融制度の中心機関として，通貨量を調節して景気の調整を図るなどの働きをしている銀行を何というか。', '', '日本銀行', ''),
  (1225, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 250, 1, FALSE, '日本では，249が唯一の( )で，日本銀行券を発行している。また，戻ってきた銀行券のうち，流通に適さない銀行券を廃棄する。', '', '発券銀行', ''),
  (1226, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 251, 1, FALSE, '一般の金融機関を相手に，預金や資金の貸し出しを行っていることから，249は何とよばれているか。', '', '銀行の銀行', ''),
  (1227, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 252, 1, FALSE, '249は，政府の資金の出し入れや，政府への貸し出しなどを行っていることから，( )ともよばれている。', '', '政府の銀行', ''),
  (1228, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 253, 1, FALSE, '経済活動が活発に行われている状態を( )といい，商品の売れ行きがよいため，企業は生産を増大させ，労働者も増やす。', '', '好景気(好況)', 'こうきょう'),
  (1229, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 254, 1, FALSE, '通貨量が増えて貨幣価値が下がり，物価が継続的に上昇していく現象を何というか。', '通貨量の増加によって購買力が高まり，物価が上がる', 'インフレーション(インフレ)', ''),
  (1230, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 255, 1, FALSE, '通貨量が減り，物価が継続的に下落して生産活動が不活発になる現象を( )という。', '商品の売り上げが落ち込み，企業の倒産も出る', 'デフレーション(デフレ)', ''),
  (1231, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 256, 1, FALSE, '249が経済情勢に応じて通貨の流通量を調整し，景気や物価の安定を図るために行う政策を何というか。', '公開市場操作が中心となる', '金融政策', 'きんゆうせいさく'),
  (1232, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 257, 1, FALSE, '外国通貨に対して円の価値が上がる( )では，輸入が増加し，輸出が減少する状況が生じる。', '1ドル100円が80円になるような場合', '円高', 'えんだか'),
  (1233, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 258, 1, FALSE, '257とは逆の現象で，日本からの輸出品は外国では割安になるので輸出は増加するが，輸入品の価格は高くなるような状況を( )という。', '', '円安', 'えんやす'),
  (1234, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 259, 2, FALSE, '通貨量をその国の政府と中央銀行で管理する制度を何というか。', '日本をはじめ，ほとんどの国がこの制度を採用している', '管理通貨制度', 'かんりつうかせいど'),
  (1235, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 260, 2, FALSE, '企業が株式や社債を発行して，個人や投資家から直接資金を調達することを何というか。', '', '直接金融', 'ちょくせつきんゆう'),
  (1236, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 261, 2, FALSE, '株式会社と投資家の仲立ちをし，有価証券の売買などの業務を行う金融機関の一つを何というか。', '株式の売買がおもな業務である', '証券会社', 'しょうけんがいしゃ'),
  (1237, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 262, 2, FALSE, '資金調達の難しい個人・団体が，インターネットを通じて実現したい企画や事業を公表し，広く資金提供をよびかけるしくみを何というか。', '', 'クラウドファンディング', ''),
  (1238, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 263, 2, FALSE, 'それぞれの国の金融制度の中心となっている銀行を何というか。', 'アメリカ合衆国の連邦準備制度理事会，イギリスのイングランド銀行など', '中央銀行', 'ちゅうおうぎんこう'),
  (1239, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 264, 2, FALSE, '金融機関が破綻したときに，預金者に預金の元本とその利息分までを保証することを何というか。', '1人につき元本1千万円とその利息分までを保証する', 'ペイオフ', ''),
  (1240, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 265, 2, FALSE, '( )は，金融(Finance)と技術(Technology)を組み合わせた造語で，情報通信技術(ICT)を活用したお金のやり取りのことをいう。', '', 'フィンテック', ''),
  (1241, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 266, 2, FALSE, '1年間に国内で生産された財・サービスの付加価値の合計を( )という。', '1990年代から国民総生産(GNP)に代わって使用されるようになった', '国内総生産(GDP)', 'こくないそうせいさん'),
  (1242, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 267, 2, FALSE, '一定範囲におけるさまざまな商品・サービスの平均価格のことを何というか。', '', '物価', 'ぶっか'),
  (1243, '公民', '第3章 わたしたちの生活と経済', '5. 貨幣と金融のしくみ', 268, 2, FALSE, '外国為替手形の売買を通じて決定される，自国通貨と外国通貨との交換比率を何というか。', '為替レートともいい，常に変動している', '為替相場', 'かわせそうば'),
  (1244, '公民', '第3章 わたしたちの生活と経済', '6. 財政のはたらき', 269, 1, FALSE, '税金などの収入を資金として，国や地方公共団体が行う経済活動のことを何というか。', '国や地方公共団体の収入・支出のこと', '財政', 'ざいせい'),
  (1245, '公民', '第3章 わたしたちの生活と経済', '6. 財政のはたらき', 270, 1, FALSE, '( )とは，国民生活の向上や国民経済の発展，国土保全のために必要な公共施設のことで，道路・鉄道・上下水道・公園・学校・図書館などが当てはまる。', 'インフラストラクチャー(インフラ)ともいう', '社会資本', 'しゃかいしほん'),
  (1246, '公民', '第3章 わたしたちの生活と経済', '6. 財政のはたらき', 272, 1, FALSE, '国や地方公共団体が，道路や鉄道などの270の整備などを行うための事業を何というか。', '', '公共事業', 'こうきょうじぎょう'),
  (1247, '公民', '第3章 わたしたちの生活と経済', '6. 財政のはたらき', 273, 1, FALSE, '新しい会計年度が始まる前にたてる，その1年間の収支の見積もりを何というか。', '国会や地方議会での議決を経て成立する', '予算', 'よさん'),
  (1248, '公民', '第3章 わたしたちの生活と経済', '6. 財政のはたらき', 274, 1, FALSE, '国や地方公共団体の一会計年度中のすべての支出を何というか。', '国の274では，社会保障関係費や国債費の占める割合が特に高い', '歳出', 'さいしゅつ'),
  (1249, '公民', '第3章 わたしたちの生活と経済', '6. 財政のはたらき', 275, 1, FALSE, '国や地方公共団体の一会計年度中のすべての収入を( )といい，租税収入が最も大きな財源となっている。', '', '歳入', 'さいにゅう'),
  (1250, '公民', '第3章 わたしたちの生活と経済', '6. 財政のはたらき', 276, 1, FALSE, '税金を納める義務のある納税者と，税金を実際に負担する人が同じ税を( )という。', '', '直接税', 'ちょくせつぜい'),
  (1251, '公民', '第3章 わたしたちの生活と経済', '6. 財政のはたらき', 277, 1, FALSE, '税金を納める義務のある納税者と，税金を実際に負担する人が異なる税を何というか。', '消費者が負担し，生産者や販売者が納める', '間接税', 'かんせつぜい'),
  (1252, '公民', '第3章 わたしたちの生活と経済', '6. 財政のはたらき', 278, 1, FALSE, '給与所得・個人事業所得・財産所得などの個人の所得に応じて課せられる税を何というか。', '', '所得税', 'しょとくぜい'),
  (1253, '公民', '第3章 わたしたちの生活と経済', '6. 財政のはたらき', 279, 1, FALSE, '課税の対象となる所得や財産が大きくなるにつれて，税率を高くする課税方法を( )という。', '278や相続税などに適用される', '累進課税', 'るいしんかぜい'),
  (1254, '公民', '第3章 わたしたちの生活と経済', '6. 財政のはたらき', 280, 1, FALSE, '国内で，商品やサービスを購入したときに課せられる税を何というか。', '消費者が負担し，納税するのは個人や法人の事業者である', '消費税', 'しょうひぜい'),
  (1255, '公民', '第3章 わたしたちの生活と経済', '6. 財政のはたらき', 281, 2, FALSE, '国が課税し徴収するもので，最終負担者が納税義務者を通じて国に納付する税を( )という。', '278などがある', '国税', 'こくぜい'),
  (1256, '公民', '第3章 わたしたちの生活と経済', '6. 財政のはたらき', 282, 2, FALSE, '地方公共団体が課税し徴収する税で，(都)道府県税と市(区)町村税に分けられる税を何というか。', '住民税・固定資産税・自動車税などがある', '地方税', 'ちほうぜい'),
  (1257, '公民', '第3章 わたしたちの生活と経済', '6. 財政のはたらき', 283, 2, FALSE, '会社などの法人の所得に対して課せられる税で，278とともにその額が多い税を何というか。', '', '法人税', 'ほうじんぜい'),
  (1258, '公民', '第3章 わたしたちの生活と経済', '6. 財政のはたらき', 284, 2, FALSE, '死亡した人の財産を相続したときに，その相続分に課せられる税を何というか。', '', '相続税', 'そうぞくぜい'),
  (1259, '公民', '第3章 わたしたちの生活と経済', '6. 財政のはたらき', 285, 2, FALSE, '280は，所得に関係なく一律に課税されるため，所得の少ない人ほど，所得に占める税金の割合が高くなるという( )がある。', '', '逆進性', 'ぎゃくしんせい'),
  (1260, '公民', '第3章 わたしたちの生活と経済', '6. 財政のはたらき', 286, 2, FALSE, '財政収入の不足を補うために国が発行する債券を( )という。', '財政収入に占める286の依存率は非常に高くなっている', '国債', 'こくさい'),
  (1261, '公民', '第3章 わたしたちの生活と経済', '7. 社会保障と環境保全', 287, 1, FALSE, 'すべての国民が健康で文化的な最低限度の生活ができるように，社会全体で保障しようとするしくみを何というか。', '', '社会保障', 'しゃかいほしょう'),
  (1262, '公民', '第3章 わたしたちの生活と経済', '7. 社会保障と環境保全', 288, 1, FALSE, '病気や老後に備えて，加入者が掛け金を積み立てておき，必要が生じたときに給付金を受け取る制度を何というか。', '', '社会保険', 'しゃかいほけん'),
  (1263, '公民', '第3章 わたしたちの生活と経済', '7. 社会保障と環境保全', 289, 1, FALSE, '介護を必要とする人に，介護サービスを受けるのに必要な費用を支援する制度を何というか。', '40歳以上の人が保険料を納めるようになっている', '介護保険制度', 'かいごほけんせいど'),
  (1264, '公民', '第3章 わたしたちの生活と経済', '7. 社会保障と環境保全', 290, 1, FALSE, '自分だけでは生活するのが困難になった人に，最低限の生活を保障する制度を( )という。', '福祉事務所が行う生活保護が中心', '公的扶助', 'こうてきふじょ'),
  (1265, '公民', '第3章 わたしたちの生活と経済', '7. 社会保障と環境保全', 291, 1, FALSE, '高齢者・障がい者などの社会的弱者に対し，福祉施設の設置や福祉サービスを行って自立を援助する制度を何というか。', '老人ホームなどがある', '社会福祉', 'しゃかいふくし'),
  (1266, '公民', '第3章 わたしたちの生活と経済', '7. 社会保障と環境保全', 292, 1, FALSE, '保健所を中心に，国民の健康を増進して病気を予防するために，生活環境や医療などを整備することを( )という。', '', '公衆衛生', 'こうしゅうえいせい'),
  (1267, '公民', '第3章 わたしたちの生活と経済', '7. 社会保障と環境保全', 293, 1, FALSE, '1993年，公害対策基本法を発展させて，あらゆる環境問題に対応するために定められた法律を何というか。', '', '環境基本法', 'かんきょうきほんほう'),
  (1268, '公民', '第3章 わたしたちの生活と経済', '7. 社会保障と環境保全', 294, 2, FALSE, '事故や災害などの不測の事態や失業などの経済的不安に備えたしくみや制度のことを何というか。', '', 'セーフティネット', ''),
  (1269, '公民', '第3章 わたしたちの生活と経済', '7. 社会保障と環境保全', 295, 2, FALSE, '加入者の積み立て金から，病気やけがをした人の治療費を支払うしくみを何というか。', '国民は必ず加入しなければならない(国民皆保険)', '医療保険', 'いりょうほけん'),
  (1270, '公民', '第3章 わたしたちの生活と経済', '7. 社会保障と環境保全', 296, 2, FALSE, '老齢やけがや病気によって体に障がいを負ったときに給付金が支給される制度を( )という。', '20歳以上60歳未満のすべての人に加入義務がある', '年金保険', 'ねんきんほけん'),
  (1271, '公民', '第3章 わたしたちの生活と経済', '7. 社会保障と環境保全', 298, 2, FALSE, '地域開発などを行う場合，その開発が自然環境にどのような影響をおよぼすかを事前に調査・予想・評価することを何というか。', '', '環境影響評価(環境アセスメント)', 'かんきょうえいきょうひょうか'),
  (1272, '公民', '第3章 わたしたちの生活と経済', '7. 社会保障と環境保全', 299, 2, FALSE, '「3つのR」のうち，ごみを再生して使うことを何というか。', 'リデュース＝ごみの発生をおさえる，リユース＝繰り返し使う', 'リサイクル', ''),
  (1273, '公民', '第3章 わたしたちの生活と経済', '8. 日本経済の課題', 300, 1, FALSE, '1980年代の，実態を伴わない地価・株価の急激な上昇による( )は，政府の金融引き締め政策により地価・株価が暴落し，1991年に崩壊した。', '', 'バブル経済', 'バブルけいざい'),
  (1274, '公民', '第4章 国際社会とわたしたち', '1. 国際社会と主権国家', 303, 1, FALSE, '一定の領土と国民をもち、他国から干渉・支配されず、自国の政治や外交について自ら決定する権利をもつ独立した国家を何というか。', '', '主権国家', ''),
  (1275, '公民', '第4章 国際社会とわたしたち', '1. 国際社会と主権国家', 304, 1, FALSE, '国際社会において、その秩序を守るための決まりで、国家における法律にあたるものを何というか。', '国際慣習法など', '国際法', ''),
  (1276, '公民', '第4章 国際社会とわたしたち', '1. 国際社会と主権国家', 305, 2, FALSE, '国家間の話し合いで決められた約束を文書にしたものを何というか。', '協定・協約・宣言・規約・憲章なども含まれる', '条約', ''),
  (1277, '公民', '第4章 国際社会とわたしたち', '1. 国際社会と主権国家', 306, 2, FALSE, '国際社会において、すべての国は、他国の国内問題には介入してはならないという原則を何というか。', '', '内政不干渉の原則', 'ないせいふかんしょうのげんそく'),
  (1278, '公民', '第4章 国際社会とわたしたち', '1. 国際社会と主権国家', 307, 2, FALSE, 'それぞれの民族は他の民族や国家の支配を受けることなく、自らの意思で政治体制やその帰属を決めることができるという原則を何というか。', '', '民族自決の原則', ''),
  (1279, '公民', '第4章 国際社会とわたしたち', '2. 国際連合のしくみとはたらき', 308, 1, FALSE, '世界の平和と安全の維持、国際協力の促進などを目的に、1945年に発足した機関を何というか。', '原加盟国は51か国で、本部はニューヨーク', '国際連合', ''),
  (1280, '公民', '第4章 国際社会とわたしたち', '2. 国際連合のしくみとはたらき', 309, 1, FALSE, 'すべての加盟国で構成される全体会議で、308の最高審議機関を何というか。', 'すべての加盟国が1票の投票権をもち、同等の発言力をもつ', '国連総会 (総会)', ''),
  (1281, '公民', '第4章 国際社会とわたしたち', '2. 国際連合のしくみとはたらき', 311, 1, FALSE, '310を構成する ( ) は、アメリカ合衆国・イギリス・フランス・ロシア連邦・中国の5か国である。', '', '常任理事国', ''),
  (1282, '公民', '第4章 国際社会とわたしたち', '2. 国際連合のしくみとはたらき', 312, 1, FALSE, '重要議題については、310の311が1国でも反対すると決定されないため、この権限を ( ) という。', '五大国一致の原則に基づいている', '拒否権', ''),
  (1283, '公民', '第4章 国際社会とわたしたち', '2. 国際連合のしくみとはたらき', 313, 1, FALSE, '本部がハーグにあり、国家間の紛争を裁く308の主要機関の一つを何というか。', '当事国双方の同意がなければ裁判を始められない', '国際司法裁判所', ''),
  (1284, '公民', '第4章 国際社会とわたしたち', '2. 国際連合のしくみとはたらき', 314, 1, FALSE, '308が地域紛争の鎮静化や拡大防止、平和維持を目的に行う活動を何というか。', '日本は、1992年に初めてカンボジアに自衛隊を派遣した', '平和維持活動 (PKO)', 'へいわいじかつどう'),
  (1285, '公民', '第4章 国際社会とわたしたち', '2. 国際連合のしくみとはたらき', 315, 1, FALSE, '1992年に制定された、自衛隊の海外派遣の根拠となる法律を何というか。', '湾岸戦争の際、経済援助中心の日本の姿勢を批判する声の高まりを背景に制定', '国連平和維持活動協力法 (PKO協力法)', ''),
  (1286, '公民', '第4章 国際社会とわたしたち', '2. 国際連合のしくみとはたらき', 316, 2, FALSE, '1945年6月のサンフランシスコ会議に参加した50か国が署名し、308の目的・組織・活動の原則などを定めた文書を何というか。', '', '国際連合憲章 (国連憲章)', ''),
  (1287, '公民', '第4章 国際社会とわたしたち', '2. 国際連合のしくみとはたらき', 317, 2, FALSE, '310を構成する理事国のうち、任期が2年の10か国を何というか。', '毎年半数の5か国が改選される', '非常任理事国', ''),
  (1288, '公民', '第4章 国際社会とわたしたち', '2. 国際連合のしくみとはたらき', 318, 2, FALSE, '経済社会理事会を通じて308と協定を結び、経済的・社会的・文化的分野で活動している国際機構を何というか。', '', '専門機関', ''),
  (1289, '公民', '第4章 国際社会とわたしたち', '2. 国際連合のしくみとはたらき', 319, 2, FALSE, '( ) は、世界の国々の教育・科学・文化の向上を図り、世界平和に貢献することを目的に活動している。', '略称はUNESCO', '国連教育科学文化機関', ''),
  (1290, '公民', '第4章 国際社会とわたしたち', '2. 国際連合のしくみとはたらき', 320, 2, FALSE, '世界の人々の健康の向上を図り、感染症の撲滅、各国の保健システムの強化などを行っている308の機関を何というか。', '略称はWHO', '世界保健機関', ''),
  (1291, '公民', '第4章 国際社会とわたしたち', '2. 国際連合のしくみとはたらき', 321, 2, FALSE, 'おもに発展途上国の子どもたちに対し、予防接種の普及、食料・医薬品の提供などを行っている308の補助機関を何というか。', '略称はUNICEF', '国連児童基金', ''),
  (1292, '公民', '第4章 国際社会とわたしたち', '3. 国際政治・国際経済の動きと地域主義', 322, 1, FALSE, '宗教対立や民族対立、資源の争奪などを要因に、一つの国、または複数の国家にまたがる特定の地域でおこる紛争を何というか。', '', '地域紛争', ''),
  (1293, '公民', '第4章 国際社会とわたしたち', '3. 国際政治・国際経済の動きと地域主義', 323, 1, FALSE, '政治的目的を実現するためには暴力も否定しないという考え方を何というか。', '', 'テロリズム (テロ)', ''),
  (1294, '公民', '第4章 国際社会とわたしたち', '3. 国際政治・国際経済の動きと地域主義', 325, 1, FALSE, '人種や宗教、国籍、政治的意見などを理由に、自国にいると迫害を受けるおそれがあるため、他国に逃れた人々のことを ( ) という。', '', '難民', ''),
  (1295, '公民', '第4章 国際社会とわたしたち', '3. 国際政治・国際経済の動きと地域主義', 326, 1, FALSE, '325となった人々の本国への帰還や第三国への定住を援助している国際連合の補助機関を何というか。', '略称はUNHCR。本部はジュネーブ', '国連難民高等弁務官事務所', ''),
  (1296, '公民', '第4章 国際社会とわたしたち', '3. 国際政治・国際経済の動きと地域主義', 327, 1, FALSE, 'ヨーロッパ連合(EU)や東南アジア諸国連合(ASEAN)のように、地域的に近い複数の国家が結びつきを強化していく動きのことを何というか。', '', '地域主義 (リージョナリズム)', ''),
  (1297, '公民', '第4章 国際社会とわたしたち', '3. 国際政治・国際経済の動きと地域主義', 328, 1, FALSE, 'ヨーロッパや北アメリカ諸国・日本・オーストラリアなど、工業化が進み、経済が発展した国を何というか。', '', '先進工業国 (先進国)', ''),
  (1298, '公民', '第4章 国際社会とわたしたち', '3. 国際政治・国際経済の動きと地域主義', 329, 1, FALSE, '328に対し、経済が発達の途上にある国を ( ) という。', '国民1人あたりの所得水準が低く、一次産品に依存している国が多い', '発展途上国', ''),
  (1299, '公民', '第4章 国際社会とわたしたち', '3. 国際政治・国際経済の動きと地域主義', 330, 1, FALSE, '328と329との間に見られる経済格差と、それから生じる政治的・社会的な問題を ( ) という。', '', '南北問題', ''),
  (1300, '公民', '第4章 国際社会とわたしたち', '3. 国際政治・国際経済の動きと地域主義', 331, 1, FALSE, '329の中でも産油国や経済発展を遂げている国と、そうでない国との間の経済格差と、それから生じるさまざまな問題を ( ) という。', '', '南南問題', ''),
  (1301, '公民', '第4章 国際社会とわたしたち', '3. 国際政治・国際経済の動きと地域主義', 332, 1, FALSE, '2000年代以降、経済発展が著しい、ブラジル・ロシア連邦・インド・中国・南アフリカ共和国の5か国を合わせたよび方を何というか。', '', 'BRICS', 'ブリックス'),
  (1302, '公民', '第4章 国際社会とわたしたち', '3. 国際政治・国際経済の動きと地域主義', 333, 2, FALSE, '複数の民族が宗教などの違いから対立し、それが原因となって異なる民族の間でおこる紛争を何というか。', '', '民族紛争', ''),
  (1303, '公民', '第4章 国際社会とわたしたち', '3. 国際政治・国際経済の動きと地域主義', 334, 2, FALSE, 'GATTを継承し、すべての貿易障壁を取り除いて自由な国際貿易の発展を目的に設立された ( ) は知的財産権なども取り扱っている。', '', '世界貿易機関 (WTO)', ''),
  (1304, '公民', '第4章 国際社会とわたしたち', '3. 国際政治・国際経済の動きと地域主義', 335, 2, FALSE, '主要8か国(G8)にヨーロッパ連合(EU)の欧州委員会委員長が加わって、経済・政治・環境問題などを議題として開かれる国際会議を何というか。', '2014年以降、ロシア連邦は参加資格を停止され、G7と称されている', '主要国首脳会議 (サミット)', ''),
  (1305, '公民', '第4章 国際社会とわたしたち', '3. 国際政治・国際経済の動きと地域主義', 336, 2, FALSE, '2008年の世界金融危機以降に、G8に新興国を加えた主要20か国・地域(G20)が開催している首脳会談を何というか。', '', '金融サミット', ''),
  (1306, '公民', '第4章 国際社会とわたしたち', '3. 国際政治・国際経済の動きと地域主義', 338, 2, FALSE, '337に加盟している一部の国々が結んだ、全貿易品目の関税撤廃を原則とし、サービスや投資の自由化を推進するための協定を ( ) という。', '', '環太平洋経済連携協定 (TPP) (TPP11協定)', 'かんたいへいようけいざいれんけいきょうてい'),
  (1307, '公民', '第4章 国際社会とわたしたち', '3. 国際政治・国際経済の動きと地域主義', 339, 2, FALSE, '北米自由貿易協定(NAFTA)を見直し、アメリカ合衆国・メキシコ・カナダの間で結ばれた協定を何というか。', '2020年に発効した', '米国・メキシコ・カナダ協定 (USMCA)', ''),
  (1308, '公民', '第4章 国際社会とわたしたち', '3. 国際政治・国際経済の動きと地域主義', 340, 2, FALSE, '328と329間の経済格差などについて討議し、政策を立案する国際連合の補助機関を何というか。', '略称はUNCTAD。本部はジュネーブ', '国連貿易開発会議', ''),
  (1309, '公民', '第4章 国際社会とわたしたち', '4. 世界のさまざまな問題と日本の役割', 341, 1, FALSE, '核保有国をアメリカ合衆国・イギリス・フランス・ソ連(現ロシア連邦)・中国の5か国に限定し、核兵器をもたない国が新たに核兵器をもつこと、核保有国が核兵器をもたない国に渡すことを禁止した条約を何というか。', '', '核拡散防止条約 (NPT)', 'かくかくさんぼうしじょうやく'),
  (1310, '公民', '第4章 国際社会とわたしたち', '4. 世界のさまざまな問題と日本の役割', 342, 1, FALSE, '温室効果ガスの濃度が高まり、地球の気温が上昇する現象を何というか。', '氷河がとけ、海抜の低い地域の水没などが考えられる', '地球温暖化', ''),
  (1311, '公民', '第4章 国際社会とわたしたち', '4. 世界のさまざまな問題と日本の役割', 343, 1, FALSE, '工場や自動車から排出される硫黄酸化物や窒素酸化物が大気中で硫酸や硝酸に変化して大気中の水分にとけこみ、雨や雪となって降ってくるものを何というか。', '森林や農作物が枯れたり、魚が死んだりする', '酸性雨', ''),
  (1312, '公民', '第4章 国際社会とわたしたち', '4. 世界のさまざまな問題と日本の役割', 344, 1, FALSE, '( ) によって、紫外線の量が増加し、人体に悪影響をおよぼすことが問題となっている。', '', 'オゾン層の破壊', 'はかい'),
  (1313, '公民', '第4章 国際社会とわたしたち', '4. 世界のさまざまな問題と日本の役割', 346, 1, FALSE, '東南アジアやラテンアメリカでは、木材の伐採や農地の開発などによって ( ) の減少が進行しており、生物種の絶滅の危惧などを招いている。', '', '熱帯林', ''),
  (1314, '公民', '第4章 国際社会とわたしたち', '4. 世界のさまざまな問題と日本の役割', 347, 1, FALSE, '地球温暖化防止京都会議で採択された ( ) で、温室効果ガスの排出量を、先進国全体で5%削減することなどが定められた。', '', '京都議定書', ''),
  (1315, '公民', '第4章 国際社会とわたしたち', '4. 世界のさまざまな問題と日本の役割', 348, 1, FALSE, '347に代わる、2020年以降の地球温暖化対策の新たな国際的枠組みを何というか。', 'すべての国に温室効果ガスの削減目標の提出を義務づけた', 'パリ協定', ''),
  (1316, '公民', '第4章 国際社会とわたしたち', '4. 世界のさまざまな問題と日本の役割', 349, 1, FALSE, '水鳥など多くの生物がすむ湿地を国際的に登録し、守っていくことを目的としている条約を何というか。', '2021年現在、日本では52か所が登録', 'ラムサール条約', ''),
  (1317, '公民', '第4章 国際社会とわたしたち', '4. 世界のさまざまな問題と日本の役割', 350, 1, FALSE, '持続可能な社会を実現するため、世界が直面している問題の解決に向けて、2030年までに達成することをめざした17の目標をアルファベット4字で何というか。', '', 'SDGs', 'エスディージーズ'),
  (1318, '公民', '第4章 国際社会とわたしたち', '4. 世界のさまざまな問題と日本の役割', 351, 1, FALSE, '先進国が発展途上国と協定を結んで、経済開発や福祉の向上を図る目的で行う資金や技術援助のことを何というか。', '日本は贈与の割合が低い', '政府開発援助 (ODA)', 'えんじょ'),
  (1319, '公民', '第4章 国際社会とわたしたち', '4. 世界のさまざまな問題と日本の役割', 352, 1, FALSE, '民間によってつくられ、平和・人権問題などに取り組んでいる組織を略称で何というか。', '国境なき医師団、アムネスティ-インターナショナルなどがある', 'NGO', ''),
